fn generated_gap_portfolio_pair_case(prefix: &str, left: u128, right: u128) -> PairCase {
    let name = Box::leak(format!("{prefix} ({left} \u{2218} {right})").into_boxed_str());
    PairCase {
        name,
        pair: ConcatenationSystem::new(left, right),
    }
}

fn generated_gap_portfolio_pair_cases(prefix: &str, pairs: &[(u128, u128)]) -> Vec<PairCase> {
    pairs
        .iter()
        .map(|&(left, right)| generated_gap_portfolio_pair_case(prefix, left, right))
        .collect()
}

fn generated_prime_gap_pair_cases(
    pair_family: &str,
    pair_gap: u32,
    lower_bound: u128,
    pair_count: usize,
) -> Vec<PairCase> {
    let mut pairs = Vec::new();
    let mut left = if lower_bound.is_multiple_of(2) {
        lower_bound + 1
    } else {
        lower_bound
    };
    while pairs.len() < pair_count {
        let right = left + pair_gap as u128;
        if is_prime_u128(left) && is_prime_u128(right) {
            pairs.push(generated_gap_portfolio_pair_case(
                &format!("{pair_family} generated control pair"),
                left,
                right,
            ));
        }
        left += 2;
    }
    pairs
}

fn connector_gap26_generated_pair_cases() -> Vec<PairCase> {
    generated_prime_gap_pair_cases("prime-gap26", 26, 240000, 36)
}

