pub fn connector_signal_settings(small_prime_bound: u32) -> SignalReportSettings {
    SignalReportSettings {
        widths: WIDTHS.to_vec(),
        digits: DIGITS.to_vec(),
        residue_moduli: RESIDUE_MODULI.to_vec(),
        small_primes: small_primes_up_to(small_prime_bound),
    }
}

pub fn build_connector_signal_analysis(small_prime_bound: u32) -> ConnectorSignalAnalysis {
    let settings = connector_signal_settings(small_prime_bound);
    let reports: Vec<_> = maintained_connector_pair_cases()
        .iter()
        .map(|case| {
            let summary = scan_single_digit_hits(case.pair, WIDTHS, DIGITS, RESIDUE_MODULI);
            let audit = summary.signal_audit(&settings.small_primes);
            let sweep = build_residual_sweep(case.name, &summary);
            NamedPairReport {
                name: case.name.to_string(),
                summary,
                audit,
                sweep,
            }
        })
        .collect();

    let canonical = reports.first().expect("canonical report should exist");
    assert_canonical_source_case(&canonical.summary);
    let canonical_source_cases = build_canonical_source_rows(&canonical.summary);
    let comparison = build_comparison_verdict(&reports);
    let residual_sweep_summary = reports.iter().map(summarize_residual_sweep).collect();

    ConnectorSignalAnalysis {
        settings,
        canonical_source_cases,
        comparison,
        residual_sweep_summary,
        reports,
    }
}

pub fn build_signal_report_bundle(analysis: &ConnectorSignalAnalysis) -> SignalReportBundle {
    SignalReportBundle {
        export_version: CONNECTOR_SIGNAL_EXPORT_VERSION,
        generated_at_utc: export_timestamp_utc(),
        settings: analysis.settings.clone(),
        canonical_source_cases: analysis.canonical_source_cases.clone(),
        comparison: analysis.comparison.clone(),
        residual_sweep_summary: analysis.residual_sweep_summary.clone(),
        pairs: exported_pair_reports(&analysis.reports),
    }
}

pub fn build_connector_signal_atlas() -> ConnectorSignalAtlas {
    let analysis = build_connector_signal_analysis(DEFAULT_SMALL_PRIME_BOUND);
    let residue_survivor_rows = build_residue_survivor_rows(&analysis.reports);
    let residual_boundary_rows =
        build_residual_boundary_rows(&analysis.reports, &residue_survivor_rows);
    let residual_target_pick = pick_residual_target(&residual_boundary_rows);
    let residual_target_follow_up =
        build_residual_target_follow_up(&analysis.reports, residual_target_pick.as_ref());
    ConnectorSignalAtlas {
        schema_version: CONNECTOR_SIGNAL_ATLAS_SCHEMA_VERSION.to_string(),
        artifact_id: CONNECTOR_SIGNAL_ATLAS_ARTIFACT_ID.to_string(),
        generator_command: CONNECTOR_SIGNAL_ATLAS_GENERATOR_COMMAND.to_string(),
        drift_check_command: CONNECTOR_SIGNAL_ATLAS_DRIFT_CHECK_COMMAND.to_string(),
        settings: analysis.settings,
        maintained_pairs: exported_pair_reports(&analysis.reports),
        canonical_source_cases: analysis.canonical_source_cases,
        comparison: analysis.comparison,
        residual_sweep_summary: analysis.residual_sweep_summary,
        residue_survivor_rows,
        residual_boundary_rows,
        residual_target_pick,
        residual_target_follow_up,
        proof_links: connector_signal_proof_links(),
        claim_status: connector_signal_claim_status(),
    }
}

pub fn build_connector_width6_stress_report() -> ConnectorWidth6StressReport {
    let settings = ConnectorWidth6StressSettings {
        width: CONNECTOR_STRESS_WIDTH,
        digits: DIGITS.to_vec(),
        residue_moduli: RESIDUE_MODULI.to_vec(),
        small_prime_bounds: DEFAULT_SWEEP_BOUNDS.to_vec(),
        control_policy: "small-twin-prime-ladder-around-selected-width6-target".to_string(),
    };
    let pair_cases = connector_width6_stress_pair_cases();
    let mut rows = Vec::new();

    for case in &pair_cases {
        for &bound in DEFAULT_SWEEP_BOUNDS {
            rows.push(build_connector_width6_stress_row(case, bound));
        }
    }

    let mut pair_summaries: Vec<_> = pair_cases
        .iter()
        .enumerate()
        .filter_map(|(index, case)| summarize_width6_stress_pair(index + 1, case, &rows))
        .collect();
    assign_median_absolute_gap_ranks(&mut pair_summaries);
    let selected_pair_label = "Selected twin-prime target (11 \u{2218} 13)".to_string();
    let selected_pair_summary = pair_summaries
        .iter()
        .find(|summary| summary.pair_label == selected_pair_label)
        .cloned()
        .expect("selected width-6 stress target summary should exist");
    let selected_vs_controls_status =
        selected_vs_controls_status(&selected_pair_summary, &pair_summaries);
    let median_gap_monotone_by_pair_size = median_gap_monotone_by_pair_size(&pair_summaries);
    let ladder_pattern_status = ladder_pattern_status(
        &selected_pair_summary,
        &pair_summaries,
        median_gap_monotone_by_pair_size,
    );
    let selected_median_absolute_gap_rank = selected_pair_summary.median_absolute_gap_rank;
    let signed_gap_sign_sequence = pair_summaries
        .iter()
        .map(|summary| {
            let sign = if summary.positive_gap_count == summary.bound_count {
                "+"
            } else if summary.negative_gap_count == summary.bound_count {
                "-"
            } else {
                "mixed"
            };
            format!("{}:{}", summary.left, sign)
        })
        .collect();
    let ladder_peak_follow_up = build_width6_peak_follow_up(&pair_summaries, &rows);
    let ladder_peak_matched_control_screen = ladder_peak_follow_up
        .as_ref()
        .and_then(build_width6_peak_matched_control_screen);
    let target_decision = width6_stress_target_decision(&selected_pair_summary);
    let replication_null_atlas = build_connector_replication_null_atlas_from_screen(
        ladder_peak_matched_control_screen.as_ref(),
    );

    let mut report = ConnectorWidth6StressReport {
        schema_version: CONNECTOR_WIDTH6_STRESS_SCHEMA_VERSION.to_string(),
        artifact_id: CONNECTOR_WIDTH6_STRESS_ARTIFACT_ID.to_string(),
        generator_command: CONNECTOR_WIDTH6_STRESS_GENERATOR_COMMAND.to_string(),
        settings,
        selected_pair_label,
        selected_pair_summary,
        selected_vs_controls_status,
        ladder_pattern_status,
        median_gap_monotone_by_pair_size,
        selected_median_absolute_gap_rank,
        signed_gap_sign_sequence,
        ladder_peak_follow_up,
        ladder_peak_matched_control_screen,
        replication_null_atlas,
        target_decision,
        pair_summaries,
        rows,
        claim_status: "bounded-empirical-stress-test-not-connector-law".to_string(),
    };
    compact_connector_width6_stress_report_for_export(&mut report);
    report
}

