fn compact_orthogonal_pair_family_control_matrix(
    control: &mut Option<ConnectorWidth6OrthogonalPairFamilyControlMatrix>,
) {
    let Some(control) = control else {
        return;
    };
    for family in &mut control.pair_families {
        family.rankings.clear();
        family.rows.clear();
        if let Some(replication) = &mut family.fresh_replication {
            replication.rows.clear();
        }
    }
}

fn compact_non_mod3_candidate_picker(control: &mut Option<ConnectorWidth6NonMod3CandidatePicker>) {
    if let Some(control) = control {
        control.rankings.clear();
        control.rows.clear();
    }
}

fn compact_interior_non_mod3_family_picker(
    control: &mut Option<ConnectorWidth6InteriorNonMod3FamilyPicker>,
) {
    if let Some(control) = control {
        control.rankings.clear();
        control.rows.clear();
    }
}

fn compact_multi_digit_motif_family_picker(
    control: &mut Option<ConnectorWidth6MultiDigitMotifFamilyPicker>,
) {
    if let Some(control) = control {
        control.rankings.clear();
        control.rows.clear();
    }
}

