fn build_selected_branch_independent_replication(
    branch: &ConnectorWidth6StressBranchStatusRow,
    small_primes: &[u32],
    peak_signed_gap: f64,
    peak: &ConnectorWidth6PeakFollowUp,
) -> Option<ConnectorWidth6SelectedBranchIndependentReplication> {
    if branch.branch_status == "collapsed" || branch.edge == "mixed" {
        return None;
    }

    let position = if branch.edge == "leading" {
        0
    } else {
        branch.width.checked_sub(1)?
    };
    let pair_cases = connector_selected_branch_independent_pair_cases();
    let mut rows = Vec::new();
    for case in &pair_cases {
        if let Some(row) = build_peak_matched_control_row(
            case,
            branch.width,
            position,
            branch.digit,
            "selected-branch-independent-replication",
            small_primes,
            peak_signed_gap,
            peak,
        ) {
            rows.push(row);
        }
    }

    let row_count = rows.len();
    let theorem_blocked_row_count = rows.iter().filter(|row| row.mod3_theorem_blocked).count();
    let nonblocked_row_count = rows.iter().filter(|row| !row.mod3_theorem_blocked).count();
    let residue_admissible_pair_count = rows
        .iter()
        .filter(|row| row.residue_admissible_in_both_directions)
        .count();
    let reverse_only_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .count();
    let forward_only_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "forward-only-prime-hit")
        .count();
    let both_hit_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "both-prime-hit")
        .count();
    let neither_hit_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "neither-prime-hit")
        .count();
    let fully_theorem_blocked = row_count > 0 && theorem_blocked_row_count == row_count;
    let replication_decision = if fully_theorem_blocked {
        "retired-all-fresh-independent-rows-theorem-blocked-by-mod3-null-layer"
    } else if nonblocked_row_count > 0 && reverse_only_pair_count > 0 {
        "survived-independent-replication-residue-profiler-next"
    } else {
        "collapsed-no-fresh-nonblocked-reverse-only-hit"
    };
    let next_experiment_target = if fully_theorem_blocked {
        "select-new-non-mod3-connector-stress-family-after-00000006-retirement"
    } else if nonblocked_row_count > 0 && reverse_only_pair_count > 0 {
        "residue-profile-surviving-independent-connector-stress-branch"
    } else {
        "select-next-connector-stress-branch-after-independent-collapse"
    };

    Some(ConnectorWidth6SelectedBranchIndependentReplication {
        selection_rule: "selected-branch-on-next-twelve-disjoint-twin-prime-pairs-after-1019-1021"
            .to_string(),
        source_branch_id: branch.branch_id.clone(),
        source_branch_status: branch.branch_status.clone(),
        edge: branch.edge.clone(),
        width: branch.width,
        position,
        digit: branch.digit,
        connector: branch.connector.clone(),
        fresh_pair_count: pair_cases.len(),
        fresh_pair_labels: pair_cases
            .iter()
            .map(|case| case.name.to_string())
            .collect(),
        row_count,
        theorem_blocked_row_count,
        nonblocked_row_count,
        residue_admissible_pair_count,
        reverse_only_pair_count,
        forward_only_pair_count,
        both_hit_pair_count,
        neither_hit_pair_count,
        exact_layer_decision:
            "decimal-connector-multiple-of-3-null-layer-blocks-every-fresh-twin-pair-above-3"
                .to_string(),
        exact_layer_lean_module: CONNECTOR_PROFILE_EXAMPLES_MODULE.to_string(),
        exact_layer_lean_theorems: vec![
            TWIN_PRIME_ABOVE_THREE_MOD3_FORWARD_BLOCKED_THEOREM.to_string(),
            TWIN_PRIME_ABOVE_THREE_MOD3_REVERSE_BLOCKED_THEOREM.to_string(),
        ],
        replication_decision: replication_decision.to_string(),
        next_experiment_target: next_experiment_target.to_string(),
        rows,
    })
}

fn build_non_mod3_candidate_picker(
    small_primes: &[u32],
    peak_signed_gap: f64,
    peak: &ConnectorWidth6PeakFollowUp,
    additional_retired_candidates: Vec<ConnectorWidth6RetiredNonMod3Candidate>,
) -> Option<ConnectorWidth6NonMod3CandidatePicker> {
    let widths = (5..=9).collect::<Vec<_>>();
    let digits = vec![1_u8, 2, 4, 5, 7];
    let pair_cases = connector_selected_branch_independent_pair_cases();
    let mut rows = Vec::new();

    for case in &pair_cases {
        for width in &widths {
            for digit in &digits {
                if let Some(row) = build_peak_matched_control_row(
                    case,
                    *width,
                    0,
                    *digit,
                    "non-mod3-candidate-picker-leading",
                    small_primes,
                    peak_signed_gap,
                    peak,
                ) {
                    if !connector_fresh_ladder_mod3_blocks(&row.connector) {
                        rows.push(row);
                    }
                }
                if let Some(row) = build_peak_matched_control_row(
                    case,
                    *width,
                    width - 1,
                    *digit,
                    "non-mod3-candidate-picker-trailing",
                    small_primes,
                    peak_signed_gap,
                    peak,
                ) {
                    if !connector_fresh_ladder_mod3_blocks(&row.connector) {
                        rows.push(row);
                    }
                }
            }
        }
    }

    if rows.is_empty() {
        return None;
    }

    rows.sort_by(|left, right| {
        left.left
            .cmp(&right.left)
            .then_with(|| left.right.cmp(&right.right))
            .then_with(|| left.width.cmp(&right.width))
            .then_with(|| left.digit.cmp(&right.digit))
            .then_with(|| left.position.cmp(&right.position))
    });
    let rankings = rank_edge_pair_replication_cells(&rows);
    let mut retired_candidates = retired_non_mod3_candidates();
    retired_candidates.extend(additional_retired_candidates);
    let retired_candidate_ids = retired_candidates
        .iter()
        .map(|candidate| candidate.candidate_id.clone())
        .collect::<Vec<_>>();
    let retired_candidate_id_set = retired_candidate_ids
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    let selected_candidate = rankings
        .iter()
        .find(|row| {
            row.reverse_only_pair_count > 0
                && !retired_candidate_id_set.contains(&non_mod3_rank_candidate_id(row))
        })
        .cloned();
    let reverse_only_cell_count = rankings
        .iter()
        .filter(|row| row.reverse_only_pair_count > 0)
        .count();
    let theorem_blocked_row_count = rows.iter().filter(|row| row.mod3_theorem_blocked).count();
    let nonblocked_row_count = rows.iter().filter(|row| !row.mod3_theorem_blocked).count();
    let picker_decision = if selected_candidate.is_some() && !retired_candidate_ids.is_empty() {
        "fresh-nonmod3-candidate-selected-after-retiring-collapsed-separator"
    } else if selected_candidate.is_some() {
        "fresh-nonmod3-candidate-selected-for-independent-replication"
    } else {
        "fresh-nonmod3-candidate-picker-found-no-reverse-only-branch"
    };
    let next_experiment_target = selected_candidate
        .as_ref()
        .map(|candidate| {
            format!(
                "independently-replicate-nonmod3-{}-{}-edge-width{}-digit{}",
                candidate.connector, candidate.edge, candidate.width, candidate.digit
            )
        })
        .unwrap_or_else(|| "no-nonmod3-connector-stress-family-selected".to_string());

    Some(ConnectorWidth6NonMod3CandidatePicker {
        selection_rule:
            "after-mod3-retirement;fresh-independent-ladder;widths-5-through-9;edges-leading-trailing;digits-1-2-4-5-7;rank-by-reverse-only-count-gap"
                .to_string(),
        fresh_pair_count: pair_cases.len(),
        fresh_pair_labels: pair_cases
            .iter()
            .map(|case| case.name.to_string())
            .collect(),
        widths,
        digits,
        edges: vec!["leading".to_string(), "trailing".to_string()],
        retired_candidate_count: retired_candidates.len(),
        retired_candidate_ids,
        retired_candidates,
        row_count: rows.len(),
        theorem_blocked_row_count,
        nonblocked_row_count,
        ranked_cell_count: rankings.len(),
        reverse_only_cell_count,
        selected_candidate,
        picker_decision: picker_decision.to_string(),
        next_experiment_target,
        rankings,
        rows,
    })
}

