fn build_non_mod3_residue_profile_from_rows(
    selection_rule: &str,
    source_candidate_id: &str,
    edge: &str,
    width: u32,
    position: u32,
    digit: u8,
    connector: &str,
    source_rows: &[ConnectorWidth6PeakMatchedControlRow],
    target_family: &str,
) -> Option<ConnectorWidth6NonMod3CandidateResidueProfile> {
    let moduli = vec![3_u32, 5, 7, 11, 13, 17, 19, 23, 29, 31];
    let reverse_only_rows = source_rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .collect::<Vec<_>>();
    if reverse_only_rows.is_empty() {
        return None;
    }
    let comparison_rows = source_rows
        .iter()
        .filter(|row| row.contrast_class != "reverse-only-prime-hit")
        .collect::<Vec<_>>();
    let mut rows = moduli
        .iter()
        .map(|modulus| {
            let reverse_only_residues = reverse_only_rows
                .iter()
                .map(|row| (row.left % *modulus as u128) as u32)
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            let comparison_residues = comparison_rows
                .iter()
                .map(|row| (row.left % *modulus as u128) as u32)
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            let comparison_set = comparison_residues.iter().copied().collect::<BTreeSet<_>>();
            let shared_residues = reverse_only_residues
                .iter()
                .copied()
                .filter(|residue| comparison_set.contains(residue))
                .collect::<Vec<_>>();
            let separator_status = if reverse_only_residues.is_empty() {
                "no-reverse-only-residues"
            } else if shared_residues.is_empty() {
                "exact-residue-separator"
            } else {
                "overlapping-residue-classes"
            };

            ConnectorWidth6NonMod3CandidateResidueProfileRow {
                modulus: *modulus,
                reverse_only_pair_count: reverse_only_rows.len(),
                comparison_pair_count: comparison_rows.len(),
                reverse_only_residues,
                comparison_residues,
                shared_residues,
                separator_status: separator_status.to_string(),
            }
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| left.modulus.cmp(&right.modulus));

    let exact_separator_count = rows
        .iter()
        .filter(|row| row.separator_status == "exact-residue-separator")
        .count();
    let best_separator = rows
        .iter()
        .filter(|row| row.separator_status == "exact-residue-separator")
        .min_by(|left, right| {
            left.reverse_only_residues
                .len()
                .cmp(&right.reverse_only_residues.len())
                .then_with(|| left.modulus.cmp(&right.modulus))
        })
        .cloned();
    let profile_decision = if best_separator.is_some() {
        "small-prime-residue-separator-found-replicate-before-lean"
    } else {
        "no-small-prime-residue-separator-found-after-second-ladder"
    };
    let next_experiment_target = best_separator
        .as_ref()
        .map(|separator| {
            format!(
                "replicate-{}-{}-mod{}-residue-separator-before-lean",
                target_family, connector, separator.modulus
            )
        })
        .unwrap_or_else(|| {
            format!(
                "replicate-{}-{}-without-residue-separator-before-lean",
                target_family, connector
            )
        });

    Some(ConnectorWidth6NonMod3CandidateResidueProfile {
        selection_rule: selection_rule.to_string(),
        source_candidate_id: source_candidate_id.to_string(),
        edge: edge.to_string(),
        width,
        position,
        digit,
        connector: connector.to_string(),
        moduli,
        reverse_only_pair_count: reverse_only_rows.len(),
        comparison_pair_count: comparison_rows.len(),
        profiled_modulus_count: rows.len(),
        exact_separator_count,
        best_separator,
        profile_decision: profile_decision.to_string(),
        next_experiment_target,
        rows,
    })
}

fn build_non_mod3_residue_separator_replication(
    profile: &ConnectorWidth6NonMod3CandidateResidueProfile,
    small_primes: &[u32],
    peak_signed_gap: f64,
    peak: &ConnectorWidth6PeakFollowUp,
) -> Option<ConnectorWidth6NonMod3ResidueSeparatorReplication> {
    let separator = profile.best_separator.as_ref()?;
    let pair_cases = connector_non_mod3_residue_separator_replication_pair_cases();
    let mut rows = Vec::new();

    for case in &pair_cases {
        if let Some(row) = build_peak_matched_control_row(
            case,
            profile.width,
            profile.position,
            profile.digit,
            "non-mod3-residue-separator-replication",
            small_primes,
            peak_signed_gap,
            peak,
        ) {
            rows.push(row);
        }
    }

    rows.sort_by(|left, right| {
        left.left
            .cmp(&right.left)
            .then_with(|| left.right.cmp(&right.right))
    });
    let reverse_only_rows = rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .collect::<Vec<_>>();
    let comparison_rows = rows
        .iter()
        .filter(|row| row.contrast_class != "reverse-only-prime-hit")
        .collect::<Vec<_>>();
    let reverse_only_residues = reverse_only_rows
        .iter()
        .map(|row| (row.left % separator.modulus as u128) as u32)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let comparison_residues = comparison_rows
        .iter()
        .map(|row| (row.left % separator.modulus as u128) as u32)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let source_set = separator
        .reverse_only_residues
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    let comparison_set = comparison_residues.iter().copied().collect::<BTreeSet<_>>();
    let reverse_set = reverse_only_residues
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    let shared_residues = reverse_only_residues
        .iter()
        .copied()
        .filter(|residue| comparison_set.contains(residue))
        .collect::<Vec<_>>();
    let retained_residue_count = reverse_only_residues
        .iter()
        .filter(|residue| source_set.contains(residue))
        .count();
    let split_residue_count = reverse_only_residues
        .iter()
        .filter(|residue| !source_set.contains(residue))
        .count();
    let collapsed_residue_count = separator
        .reverse_only_residues
        .iter()
        .filter(|residue| !reverse_set.contains(residue))
        .count();

    let source_retained_exactly = !reverse_only_residues.is_empty()
        && reverse_set == source_set
        && shared_residues.is_empty();
    let separator_status = if reverse_only_residues.is_empty() {
        "collapsed-no-reverse-only-on-third-ladder"
    } else if source_retained_exactly {
        "retained-source-residue-separator-on-third-ladder"
    } else if shared_residues.is_empty() {
        "split-exact-residue-separator-on-third-ladder"
    } else {
        "collapsed-overlapping-residue-classes-on-third-ladder"
    };
    let replication_decision = match separator_status {
        "retained-source-residue-separator-on-third-ladder" => {
            format!(
                "mod{}-residue-separator-retained-lean-candidate",
                separator.modulus
            )
        }
        "split-exact-residue-separator-on-third-ladder" => {
            format!(
                "mod{}-residue-separator-split-keep-empirical",
                separator.modulus
            )
        }
        _ => format!(
            "mod{}-residue-separator-collapsed-keep-empirical",
            separator.modulus
        ),
    };
    let next_experiment_target = match separator_status {
        "retained-source-residue-separator-on-third-ladder" => format!(
            "lean-finite-classifier-candidate-nonmod3-{}-mod{}",
            profile.connector, separator.modulus
        ),
        "split-exact-residue-separator-on-third-ladder" => format!(
            "replicate-mutated-nonmod3-{}-mod{}-residue-separator-before-lean",
            profile.connector, separator.modulus
        ),
        _ => format!(
            "retire-nonmod3-{}-mod{}-residue-separator",
            profile.connector, separator.modulus
        ),
    };

    Some(ConnectorWidth6NonMod3ResidueSeparatorReplication {
        selection_rule:
            "test-best-second-ladder-mod19-separator-on-next-disjoint-twelve-twin-prime-pairs"
                .to_string(),
        source_candidate_id: profile.source_candidate_id.clone(),
        edge: profile.edge.clone(),
        width: profile.width,
        position: profile.position,
        digit: profile.digit,
        connector: profile.connector.clone(),
        source_modulus: separator.modulus,
        source_reverse_only_residues: separator.reverse_only_residues.clone(),
        fresh_pair_count: pair_cases.len(),
        fresh_pair_labels: pair_cases
            .iter()
            .map(|case| case.name.to_string())
            .collect(),
        row_count: rows.len(),
        reverse_only_pair_count: reverse_only_rows.len(),
        comparison_pair_count: comparison_rows.len(),
        reverse_only_residues,
        comparison_residues,
        shared_residues,
        retained_residue_count,
        split_residue_count,
        collapsed_residue_count,
        separator_status: separator_status.to_string(),
        replication_decision,
        next_experiment_target,
        rows,
    })
}

