fn build_interior_non_mod3_family_picker(
    small_primes: &[u32],
    peak_signed_gap: f64,
    peak: &ConnectorWidth6PeakFollowUp,
    retired_candidate_ids: &[String],
    selection_rule: &str,
) -> Option<ConnectorWidth6InteriorNonMod3FamilyPicker> {
    let widths = (5..=9).collect::<Vec<_>>();
    let digits = vec![1_u8, 2, 4, 5, 7];
    let pair_cases = connector_interior_non_mod3_source_pair_cases();
    let retired_candidate_ids = retired_candidate_ids
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    let mut rows = Vec::new();

    for case in &pair_cases {
        for width in &widths {
            for position in 1..(*width - 1) {
                for digit in &digits {
                    if let Some(row) = build_peak_matched_control_row(
                        case,
                        *width,
                        position,
                        *digit,
                        "interior-non-mod3-family-picker",
                        small_primes,
                        peak_signed_gap,
                        peak,
                    ) {
                        let candidate_id = format!(
                            "interior-width{}-position{}-digit{}-connector-{}",
                            row.width, row.position, row.digit, row.connector
                        );
                        if !connector_fresh_ladder_mod3_blocks(&row.connector)
                            && !retired_candidate_ids.contains(&candidate_id)
                        {
                            rows.push(row);
                        }
                    }
                }
            }
        }
    }

    if rows.is_empty() {
        return None;
    }

    rows.sort_by(|left, right| {
        left.left
            .cmp(&right.left)
            .then_with(|| left.right.cmp(&right.right))
            .then_with(|| left.width.cmp(&right.width))
            .then_with(|| left.position.cmp(&right.position))
            .then_with(|| left.digit.cmp(&right.digit))
    });
    let rankings = rank_interior_non_mod3_family_cells(&rows);
    let selected_candidate = rankings
        .iter()
        .find(|row| row.reverse_only_pair_count > 0)
        .cloned();
    let theorem_blocked_row_count = rows.iter().filter(|row| row.mod3_theorem_blocked).count();
    let nonblocked_row_count = rows.iter().filter(|row| !row.mod3_theorem_blocked).count();
    let reverse_only_cell_count = rankings
        .iter()
        .filter(|row| row.reverse_only_pair_count > 0)
        .count();
    let picker_decision = if selected_candidate.is_some() {
        "interior-nonmod3-family-selected-for-independent-replication"
    } else {
        "interior-nonmod3-family-picker-found-no-reverse-only-branch"
    };
    let next_experiment_target = selected_candidate
        .as_ref()
        .map(|candidate| {
            format!(
                "independently-replicate-interior-nonmod3-{}-width{}-position{}-digit{}",
                candidate.connector, candidate.width, candidate.position, candidate.digit
            )
        })
        .unwrap_or_else(|| "no-interior-nonmod3-connector-stress-family-selected".to_string());

    Some(ConnectorWidth6InteriorNonMod3FamilyPicker {
        selection_rule: selection_rule.to_string(),
        source_pair_count: pair_cases.len(),
        source_pair_labels: pair_cases
            .iter()
            .map(|case| case.name.to_string())
            .collect(),
        widths,
        digits,
        position_scope: "interior-only-positions-1-through-width-minus-2".to_string(),
        retired_candidate_count: retired_candidate_ids.len(),
        retired_candidate_ids: retired_candidate_ids.into_iter().collect(),
        row_count: rows.len(),
        theorem_blocked_row_count,
        nonblocked_row_count,
        ranked_cell_count: rankings.len(),
        reverse_only_cell_count,
        selected_candidate,
        picker_decision: picker_decision.to_string(),
        next_experiment_target,
        rankings,
        rows,
    })
}

