fn build_interior_non_mod3_family_replication_from_picker(
    picker: &ConnectorWidth6InteriorNonMod3FamilyPicker,
    small_primes: &[u32],
    peak_signed_gap: f64,
    peak: &ConnectorWidth6PeakFollowUp,
    pair_cases: Vec<PairCase>,
    selection_rule: &str,
    control_family: &str,
) -> Option<ConnectorWidth6InteriorNonMod3FamilyReplication> {
    let candidate = picker.selected_candidate.as_ref()?;
    let mut rows = Vec::new();

    for case in &pair_cases {
        if let Some(row) = build_peak_matched_control_row(
            case,
            candidate.width,
            candidate.position,
            candidate.digit,
            control_family,
            small_primes,
            peak_signed_gap,
            peak,
        ) {
            rows.push(row);
        }
    }

    rows.sort_by(|left, right| {
        left.left
            .cmp(&right.left)
            .then_with(|| left.right.cmp(&right.right))
    });
    let row_count = rows.len();
    let theorem_blocked_row_count = rows.iter().filter(|row| row.mod3_theorem_blocked).count();
    let nonblocked_row_count = rows.iter().filter(|row| !row.mod3_theorem_blocked).count();
    let residue_admissible_pair_count = rows
        .iter()
        .filter(|row| row.residue_admissible_in_both_directions)
        .count();
    let reverse_only_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .count();
    let forward_only_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "forward-only-prime-hit")
        .count();
    let both_hit_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "both-prime-hit")
        .count();
    let neither_hit_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "neither-prime-hit")
        .count();
    let reverse_only_pair_labels = rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .map(|row| row.pair_label.clone())
        .collect::<Vec<_>>();
    let strongest_pool = rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .collect::<Vec<_>>();
    let strongest_candidates = if strongest_pool.is_empty() {
        rows.iter().collect::<Vec<_>>()
    } else {
        strongest_pool
    };
    let strongest = strongest_candidates.iter().max_by(|left, right| {
        left.absolute_observed_to_corrected_ratio_gap
            .total_cmp(&right.absolute_observed_to_corrected_ratio_gap)
            .then_with(|| right.left.cmp(&left.left))
            .then_with(|| right.right.cmp(&left.right))
    })?;
    let source_candidate_id = interior_non_mod3_candidate_id(candidate);
    let replication_decision = if nonblocked_row_count > 0 && reverse_only_pair_count > 0 {
        "survived-interior-independent-ladder-residue-profiler-next"
    } else {
        "collapsed-interior-independent-ladder-retire-without-lean"
    };
    let next_experiment_target = if nonblocked_row_count > 0 && reverse_only_pair_count > 0 {
        format!(
            "residue-profile-interior-nonmod3-{}-width{}-position{}-digit{}",
            candidate.connector, candidate.width, candidate.position, candidate.digit
        )
    } else {
        format!(
            "retire-interior-nonmod3-{}-width{}-position{}-digit{}",
            candidate.connector, candidate.width, candidate.position, candidate.digit
        )
    };

    Some(ConnectorWidth6InteriorNonMod3FamilyReplication {
        selection_rule: selection_rule.to_string(),
        source_candidate_id,
        source_candidate_rank: candidate.rank,
        width: candidate.width,
        position: candidate.position,
        digit: candidate.digit,
        connector: candidate.connector.clone(),
        fresh_pair_count: pair_cases.len(),
        fresh_pair_labels: pair_cases
            .iter()
            .map(|case| case.name.to_string())
            .collect(),
        row_count,
        theorem_blocked_row_count,
        nonblocked_row_count,
        residue_admissible_pair_count,
        reverse_only_pair_count,
        forward_only_pair_count,
        both_hit_pair_count,
        neither_hit_pair_count,
        reverse_only_pair_labels,
        strongest_pair_label: strongest.pair_label.clone(),
        strongest_signed_observed_to_corrected_ratio_gap: strongest
            .signed_observed_to_corrected_ratio_gap,
        replication_decision: replication_decision.to_string(),
        next_experiment_target,
        rows,
    })
}

fn interior_non_mod3_candidate_id(row: &ConnectorWidth6InteriorNonMod3FamilyRankRow) -> String {
    format!(
        "interior-width{}-position{}-digit{}-connector-{}",
        row.width, row.position, row.digit, row.connector
    )
}

fn build_multi_digit_motif_family_picker(
    pivot_from_single_digit_retired_candidate_count: usize,
    selection_rule: &str,
) -> Option<ConnectorWidth6MultiDigitMotifFamilyPicker> {
    let widths = (5..=9).collect::<Vec<_>>();
    let digits = vec![1_u8, 2, 4, 5, 7];
    let pair_cases = connector_interior_non_mod3_source_pair_cases();
    let mut rows = Vec::new();

    for case in &pair_cases {
        for &width in &widths {
            for start_position in 1..(width - 2) {
                for &first_digit in &digits {
                    for &second_digit in &digits {
                        if let Some(row) = build_multi_digit_motif_row(
                            case,
                            width,
                            start_position,
                            [first_digit, second_digit],
                            "multi-digit-motif-family-picker",
                        ) {
                            if !row.mod3_theorem_blocked {
                                rows.push(row);
                            }
                        }
                    }
                }
            }
        }
    }

    if rows.is_empty() {
        return None;
    }

    rows.sort_by(|left, right| {
        left.left
            .cmp(&right.left)
            .then_with(|| left.right.cmp(&right.right))
            .then_with(|| left.width.cmp(&right.width))
            .then_with(|| left.start_position.cmp(&right.start_position))
            .then_with(|| left.motif_digits.cmp(&right.motif_digits))
    });
    let rankings = rank_multi_digit_motif_cells(&rows);
    let selected_motif = rankings
        .iter()
        .find(|row| row.reverse_only_pair_count > 0)
        .cloned();
    let theorem_blocked_row_count = rows.iter().filter(|row| row.mod3_theorem_blocked).count();
    let nonblocked_row_count = rows.iter().filter(|row| !row.mod3_theorem_blocked).count();
    let reverse_only_motif_count = rankings
        .iter()
        .filter(|row| row.reverse_only_pair_count > 0)
        .count();
    let picker_decision = if selected_motif.is_some() {
        "multi-digit-motif-selected-for-independent-replication"
    } else {
        "multi-digit-motif-picker-found-no-reverse-only-branch"
    };
    let next_experiment_target = selected_motif
        .as_ref()
        .map(|motif| {
            format!(
                "independently-replicate-multidigit-motif-{}-width{}-start{}-digits{}",
                motif.connector,
                motif.width,
                motif.start_position,
                motif_digits_label(&motif.motif_digits)
            )
        })
        .unwrap_or_else(|| "no-multidigit-motif-connector-stress-family-selected".to_string());

    Some(ConnectorWidth6MultiDigitMotifFamilyPicker {
        selection_rule: selection_rule.to_string(),
        source_pair_count: pair_cases.len(),
        source_pair_labels: pair_cases
            .iter()
            .map(|case| case.name.to_string())
            .collect(),
        widths,
        motif_width: 2,
        digits,
        position_scope: "adjacent-two-digit-interior-motifs-only".to_string(),
        pivot_from_single_digit_retired_candidate_count,
        row_count: rows.len(),
        theorem_blocked_row_count,
        nonblocked_row_count,
        ranked_motif_count: rankings.len(),
        reverse_only_motif_count,
        selected_motif,
        picker_decision: picker_decision.to_string(),
        next_experiment_target,
        rankings,
        rows,
    })
}

fn build_multi_digit_motif_family_independent_replication(
    picker: &ConnectorWidth6MultiDigitMotifFamilyPicker,
) -> Option<ConnectorWidth6MultiDigitMotifReplication> {
    let motif = picker.selected_motif.as_ref()?;
    let pair_cases = connector_multi_digit_motif_replication_pair_cases();
    let mut rows = Vec::new();

    for case in &pair_cases {
        let motif_digits = motif_digits_array(&motif.motif_digits)?;
        if let Some(row) = build_multi_digit_motif_row(
            case,
            motif.width,
            motif.start_position,
            motif_digits,
            "multi-digit-motif-independent-replication",
        ) {
            rows.push(row);
        }
    }

    rows.sort_by(|left, right| {
        left.left
            .cmp(&right.left)
            .then_with(|| left.right.cmp(&right.right))
    });
    let row_count = rows.len();
    let theorem_blocked_row_count = rows.iter().filter(|row| row.mod3_theorem_blocked).count();
    let nonblocked_row_count = rows.iter().filter(|row| !row.mod3_theorem_blocked).count();
    let residue_admissible_pair_count = rows
        .iter()
        .filter(|row| row.residue_admissible_in_both_directions)
        .count();
    let reverse_only_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .count();
    let forward_only_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "forward-only-prime-hit")
        .count();
    let both_hit_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "both-prime-hit")
        .count();
    let neither_hit_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "neither-prime-hit")
        .count();
    let reverse_only_pair_labels = rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .map(|row| row.pair_label.clone())
        .collect::<Vec<_>>();
    let replication_decision = if nonblocked_row_count > 0 && reverse_only_pair_count > 0 {
        "survived-multidigit-motif-independent-ladder-residue-profiler-next"
    } else {
        "collapsed-multidigit-motif-independent-ladder-retire-without-lean"
    };
    let source_motif_id = multi_digit_motif_id(motif);
    let next_experiment_target = if nonblocked_row_count > 0 && reverse_only_pair_count > 0 {
        format!(
            "residue-profile-multidigit-motif-{}-width{}-start{}-digits{}",
            motif.connector,
            motif.width,
            motif.start_position,
            motif_digits_label(&motif.motif_digits)
        )
    } else {
        format!(
            "retire-multidigit-motif-{}-width{}-start{}-digits{}",
            motif.connector,
            motif.width,
            motif.start_position,
            motif_digits_label(&motif.motif_digits)
        )
    };

    Some(ConnectorWidth6MultiDigitMotifReplication {
        selection_rule:
            "selected-multidigit-motif-on-next-twelve-disjoint-twin-prime-pairs-after-13679-13681"
                .to_string(),
        source_motif_id,
        source_motif_rank: motif.rank,
        width: motif.width,
        start_position: motif.start_position,
        motif_digits: motif.motif_digits.clone(),
        connector: motif.connector.clone(),
        fresh_pair_count: pair_cases.len(),
        fresh_pair_labels: pair_cases
            .iter()
            .map(|case| case.name.to_string())
            .collect(),
        row_count,
        theorem_blocked_row_count,
        nonblocked_row_count,
        residue_admissible_pair_count,
        reverse_only_pair_count,
        forward_only_pair_count,
        both_hit_pair_count,
        neither_hit_pair_count,
        reverse_only_pair_labels,
        replication_decision: replication_decision.to_string(),
        next_experiment_target,
        rows,
    })
}

fn build_multi_digit_motif_residue_profile(
    replication: &ConnectorWidth6MultiDigitMotifReplication,
) -> Option<ConnectorWidth6MultiDigitMotifResidueProfile> {
    let moduli = vec![3_u32, 5, 7, 11, 13, 17, 19, 23, 29, 31];
    let reverse_only_rows = replication
        .rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .collect::<Vec<_>>();
    if reverse_only_rows.is_empty() {
        return None;
    }
    let comparison_rows = replication
        .rows
        .iter()
        .filter(|row| row.contrast_class != "reverse-only-prime-hit")
        .collect::<Vec<_>>();
    let mut rows = moduli
        .iter()
        .map(|modulus| {
            let reverse_only_residues = reverse_only_rows
                .iter()
                .map(|row| (row.left % *modulus as u128) as u32)
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            let comparison_residues = comparison_rows
                .iter()
                .map(|row| (row.left % *modulus as u128) as u32)
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            let comparison_set = comparison_residues.iter().copied().collect::<BTreeSet<_>>();
            let shared_residues = reverse_only_residues
                .iter()
                .copied()
                .filter(|residue| comparison_set.contains(residue))
                .collect::<Vec<_>>();
            let separator_status = if reverse_only_residues.is_empty() {
                "no-reverse-only-residues"
            } else if shared_residues.is_empty() {
                "exact-residue-separator"
            } else {
                "overlapping-residue-classes"
            };

            ConnectorWidth6NonMod3CandidateResidueProfileRow {
                modulus: *modulus,
                reverse_only_pair_count: reverse_only_rows.len(),
                comparison_pair_count: comparison_rows.len(),
                reverse_only_residues,
                comparison_residues,
                shared_residues,
                separator_status: separator_status.to_string(),
            }
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| left.modulus.cmp(&right.modulus));

    let exact_separator_count = rows
        .iter()
        .filter(|row| row.separator_status == "exact-residue-separator")
        .count();
    let best_separator = rows
        .iter()
        .filter(|row| row.separator_status == "exact-residue-separator")
        .min_by(|left, right| {
            left.reverse_only_residues
                .len()
                .cmp(&right.reverse_only_residues.len())
                .then_with(|| left.modulus.cmp(&right.modulus))
        })
        .cloned();
    let profile_decision = if best_separator.is_some() {
        "small-prime-residue-separator-found-replicate-before-lean"
    } else {
        "no-small-prime-residue-separator-found-after-multidigit-ladder"
    };
    let next_experiment_target = best_separator
        .as_ref()
        .map(|separator| {
            format!(
                "replicate-multidigit-motif-{}-mod{}-residue-separator-before-lean",
                replication.connector, separator.modulus
            )
        })
        .unwrap_or_else(|| {
            format!(
                "retire-multidigit-motif-{}-without-residue-separator",
                replication.connector
            )
        });

    Some(ConnectorWidth6MultiDigitMotifResidueProfile {
        selection_rule:
            "profile-survived-multidigit-motif-reverse-only-left-endpoints-by-small-prime-residue-before-lean"
                .to_string(),
        source_motif_id: replication.source_motif_id.clone(),
        width: replication.width,
        start_position: replication.start_position,
        motif_digits: replication.motif_digits.clone(),
        connector: replication.connector.clone(),
        moduli,
        reverse_only_pair_count: reverse_only_rows.len(),
        comparison_pair_count: comparison_rows.len(),
        profiled_modulus_count: rows.len(),
        exact_separator_count,
        best_separator,
        profile_decision: profile_decision.to_string(),
        next_experiment_target,
        rows,
    })
}

fn build_multi_digit_motif_residue_separator_replication(
    profile: &ConnectorWidth6MultiDigitMotifResidueProfile,
) -> Option<ConnectorWidth6MultiDigitMotifResidueSeparatorReplication> {
    let separator = profile.best_separator.as_ref()?;
    let motif_digits = motif_digits_array(&profile.motif_digits)?;
    let pair_cases = connector_multi_digit_motif_residue_separator_pair_cases();
    let mut rows = Vec::new();

    for case in &pair_cases {
        if let Some(row) = build_multi_digit_motif_row(
            case,
            profile.width,
            profile.start_position,
            motif_digits,
            "multi-digit-motif-residue-separator-replication",
        ) {
            rows.push(row);
        }
    }

    rows.sort_by(|left, right| {
        left.left
            .cmp(&right.left)
            .then_with(|| left.right.cmp(&right.right))
    });
    let reverse_only_rows = rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .collect::<Vec<_>>();
    let comparison_rows = rows
        .iter()
        .filter(|row| row.contrast_class != "reverse-only-prime-hit")
        .collect::<Vec<_>>();
    let reverse_only_residues = reverse_only_rows
        .iter()
        .map(|row| (row.left % separator.modulus as u128) as u32)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let comparison_residues = comparison_rows
        .iter()
        .map(|row| (row.left % separator.modulus as u128) as u32)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let source_set = separator
        .reverse_only_residues
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    let comparison_set = comparison_residues.iter().copied().collect::<BTreeSet<_>>();
    let reverse_set = reverse_only_residues
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    let shared_residues = reverse_only_residues
        .iter()
        .copied()
        .filter(|residue| comparison_set.contains(residue))
        .collect::<Vec<_>>();
    let retained_residue_count = reverse_only_residues
        .iter()
        .filter(|residue| source_set.contains(residue))
        .count();
    let split_residue_count = reverse_only_residues
        .iter()
        .filter(|residue| !source_set.contains(residue))
        .count();
    let collapsed_residue_count = separator
        .reverse_only_residues
        .iter()
        .filter(|residue| !reverse_set.contains(residue))
        .count();

    let source_retained_exactly = !reverse_only_residues.is_empty()
        && reverse_set == source_set
        && shared_residues.is_empty();
    let separator_status = if reverse_only_residues.is_empty() {
        "collapsed-no-reverse-only-on-multidigit-separator-ladder"
    } else if source_retained_exactly {
        "retained-source-residue-separator-on-multidigit-separator-ladder"
    } else if shared_residues.is_empty() {
        "split-exact-residue-separator-on-multidigit-separator-ladder"
    } else {
        "collapsed-overlapping-residue-classes-on-multidigit-separator-ladder"
    };
    let replication_decision = match separator_status {
        "retained-source-residue-separator-on-multidigit-separator-ladder" => {
            format!(
                "mod{}-multidigit-residue-separator-retained-lean-candidate",
                separator.modulus
            )
        }
        "split-exact-residue-separator-on-multidigit-separator-ladder" => {
            format!(
                "mod{}-multidigit-residue-separator-mutated-retire-branch",
                separator.modulus
            )
        }
        _ => format!(
            "mod{}-multidigit-residue-separator-collapsed-retire-branch",
            separator.modulus
        ),
    };
    let next_experiment_target = match separator_status {
        "retained-source-residue-separator-on-multidigit-separator-ladder" => format!(
            "lean-finite-classifier-candidate-multidigit-motif-{}-mod{}",
            profile.connector, separator.modulus
        ),
        _ => format!(
            "retire-multidigit-motif-{}-mod{}-residue-separator-after-mutation",
            profile.connector, separator.modulus
        ),
    };

    Some(ConnectorWidth6MultiDigitMotifResidueSeparatorReplication {
        selection_rule:
            "test-best-multidigit-motif-residue-separator-on-next-disjoint-twelve-twin-prime-pairs"
                .to_string(),
        source_motif_id: profile.source_motif_id.clone(),
        width: profile.width,
        start_position: profile.start_position,
        motif_digits: profile.motif_digits.clone(),
        connector: profile.connector.clone(),
        source_modulus: separator.modulus,
        source_reverse_only_residues: separator.reverse_only_residues.clone(),
        fresh_pair_count: pair_cases.len(),
        fresh_pair_labels: pair_cases
            .iter()
            .map(|case| case.name.to_string())
            .collect(),
        row_count: rows.len(),
        reverse_only_pair_count: reverse_only_rows.len(),
        comparison_pair_count: comparison_rows.len(),
        reverse_only_residues,
        comparison_residues,
        shared_residues,
        retained_residue_count,
        split_residue_count,
        collapsed_residue_count,
        separator_status: separator_status.to_string(),
        replication_decision,
        next_experiment_target,
        rows,
    })
}

fn build_multi_digit_motif_retirement_summary(
    replication: &Option<ConnectorWidth6MultiDigitMotifResidueSeparatorReplication>,
) -> Vec<ConnectorWidth6MultiDigitMotifRetirementSummaryRow> {
    let Some(replication) = replication.as_ref() else {
        return Vec::new();
    };
    if replication.replication_decision
        != "mod11-multidigit-residue-separator-collapsed-retire-branch"
    {
        return Vec::new();
    }

    vec![ConnectorWidth6MultiDigitMotifRetirementSummaryRow {
        source_motif_id: replication.source_motif_id.clone(),
        width: replication.width,
        start_position: replication.start_position,
        motif_digits: replication.motif_digits.clone(),
        connector: replication.connector.clone(),
        source_modulus: replication.source_modulus,
        source_reverse_only_residues: replication.source_reverse_only_residues.clone(),
        separator_status: replication.separator_status.clone(),
        retirement_decision: replication.replication_decision.clone(),
        retirement_reason:
            "second disjoint separator ladder had zero reverse-only rows; retire before Lean"
                .to_string(),
    }]
}

