fn build_orthogonal_arithmetic_family_registry(
    square_triangular_replication: &Option<
        ConnectorWidth6OrthogonalPairFamilyResidueSeparatorReplication,
    >,
    residue_lattice_replication: &Option<
        ConnectorWidth6OrthogonalPairFamilyResidueSeparatorReplication,
    >,
    modular_walk_replication: &Option<
        ConnectorWidth6OrthogonalPairFamilyResidueSeparatorReplication,
    >,
    crt_paired_replication: Option<&ConnectorWidth6OrthogonalPairFamilyResidueSeparatorReplication>,
    multiplicative_order_replication: Option<
        &ConnectorWidth6OrthogonalPairFamilyResidueSeparatorReplication,
    >,
    automorphic_repunit_replication: Option<
        &ConnectorWidth6OrthogonalPairFamilyResidueSeparatorReplication,
    >,
    cyclic_reptend_replication: Option<
        &ConnectorWidth6OrthogonalPairFamilyResidueSeparatorReplication,
    >,
    carry_chain_replication: Option<
        &ConnectorWidth6OrthogonalPairFamilyResidueSeparatorReplication,
    >,
    base_mixed_replication: Option<&ConnectorWidth6OrthogonalPairFamilyResidueSeparatorReplication>,
) -> Option<ConnectorWidth6ArithmeticFamilyRegistry> {
    let modular_walk = modular_walk_replication.as_ref()?;
    if modular_walk.next_experiment_target
        != "select-next-arithmetic-connector-family-after-modular-walk-three-ladder-collapse"
    {
        return None;
    }

    let mut rows = Vec::new();
    if let Some(replication) = square_triangular_replication {
        rows.push(arithmetic_family_registry_retired_row(
            "square-triangular",
            "square and triangular connector values",
            "low-degree-integer-sequence",
            replication,
            "square/triangular branch collapsed on the separator ladder; keep as retired arithmetic baseline",
        ));
    }
    if let Some(replication) = residue_lattice_replication {
        rows.push(arithmetic_family_registry_retired_row(
            "residue-lattice",
            "bounded residue-lattice connector values",
            "residue-lattice",
            replication,
            "residue-lattice branch mutated on the separator ladder; do not reselect without a new design",
        ));
    }
    rows.push(arithmetic_family_registry_retired_row(
        "modular-walk",
        "low-degree modular-walk connector traces",
        "modular-walk",
        modular_walk,
        "modular-walk branch split on the separator ladder; route to a genuinely different arithmetic family",
    ));
    let crt_paired_collapsed = crt_paired_replication.is_some_and(|replication| {
        replication.next_experiment_target
            == "select-next-arithmetic-connector-family-after-crt-paired-three-ladder-collapse"
    });
    if let Some(replication) = crt_paired_replication {
        rows.push(arithmetic_family_registry_retired_row(
            "crt-paired",
            "CRT-paired connector values",
            "paired-congruence-system",
            replication,
            "CRT-paired branch collapsed on the separator ladder; route to a non-CRT arithmetic family",
        ));
    }
    let multiplicative_order_collapsed = multiplicative_order_replication.is_some_and(|replication| {
        replication.next_experiment_target
            == "select-next-arithmetic-connector-family-after-multiplicative-order-three-ladder-collapse"
    });
    if let Some(replication) = multiplicative_order_replication {
        rows.push(arithmetic_family_registry_retired_row(
            "multiplicative-order",
            "multiplicative-order connector values",
            "unit-order-orbit-family",
            replication,
            "multiplicative-order branch mutated on the separator ladder; keep excluded before inventing another arithmetic connector family",
        ));
    }
    let automorphic_repunit_collapsed = automorphic_repunit_replication.is_some_and(|replication| {
        replication.next_experiment_target
            == "select-next-arithmetic-connector-family-after-automorphic-repunit-three-ladder-collapse"
    });
    let automorphic_repunit_theorem_candidate =
        automorphic_repunit_replication.is_some_and(|replication| {
            replication
                .next_experiment_target
                .starts_with("lean-finite-classifier-candidate-orthogonal-automorphic-repunit-")
        });
    if let Some(replication) = automorphic_repunit_replication {
        if automorphic_repunit_collapsed {
            rows.push(arithmetic_family_registry_retired_row(
                "automorphic-repunit",
                "automorphic/repunit-adjacent connector values",
                "base10-fixed-point-perturbation-family",
                replication,
                "automorphic/repunit branch failed the separator ladder; keep excluded before selecting another arithmetic connector family",
            ));
        } else {
            rows.push(ConnectorWidth6ArithmeticFamilyRegistryRow {
                family_id: "automorphic-repunit".to_string(),
                family_label: "automorphic/repunit-adjacent connector values".to_string(),
                family_class: "base10-fixed-point-perturbation-family".to_string(),
                status: "theorem-candidate".to_string(),
                evidence_branch_id: Some(replication.source_branch_id.clone()),
                evidence_modulus: Some(replication.source_modulus),
                evidence_decision: Some(replication.replication_decision.clone()),
                evidence_status: Some(replication.separator_status.clone()),
                next_target: replication.next_experiment_target.clone(),
                rationale:
                    "automorphic/repunit branch retained its separator on the third ladder; theorem-candidate material only, not a connector law"
                        .to_string(),
            });
        }
    }
    let cyclic_reptend_collapsed = cyclic_reptend_replication.is_some_and(|replication| {
        replication.next_experiment_target
            == "select-next-arithmetic-connector-family-after-cyclic-reptend-three-ladder-collapse"
    });
    let cyclic_reptend_theorem_candidate = cyclic_reptend_replication.is_some_and(|replication| {
        replication
            .next_experiment_target
            .starts_with("lean-finite-classifier-candidate-orthogonal-cyclic-reptend-")
    });
    if let Some(replication) = cyclic_reptend_replication {
        if cyclic_reptend_collapsed {
            rows.push(arithmetic_family_registry_retired_row(
                "cyclic-reptend",
                "cyclic-reptend connector values",
                "decimal-repetend-window-family",
                replication,
                "cyclic-reptend branch failed the separator ladder; keep excluded before selecting another arithmetic connector family",
            ));
        } else {
            rows.push(ConnectorWidth6ArithmeticFamilyRegistryRow {
                family_id: "cyclic-reptend".to_string(),
                family_label: "cyclic-reptend connector values".to_string(),
                family_class: "decimal-repetend-window-family".to_string(),
                status: "theorem-candidate".to_string(),
                evidence_branch_id: Some(replication.source_branch_id.clone()),
                evidence_modulus: Some(replication.source_modulus),
                evidence_decision: Some(replication.replication_decision.clone()),
                evidence_status: Some(replication.separator_status.clone()),
                next_target: replication.next_experiment_target.clone(),
                rationale:
                    "cyclic-reptend branch retained its separator on the third ladder; theorem-candidate material only, not a connector law"
                        .to_string(),
            });
        }
    }
    let carry_chain_collapsed = carry_chain_replication.is_some_and(|replication| {
        replication.next_experiment_target
            == "select-next-arithmetic-connector-family-after-carry-chain-three-ladder-collapse"
    });
    let carry_chain_theorem_candidate = carry_chain_replication.is_some_and(|replication| {
        replication
            .next_experiment_target
            .starts_with("lean-finite-classifier-candidate-orthogonal-carry-chain-")
    });
    if let Some(replication) = carry_chain_replication {
        if carry_chain_collapsed {
            rows.push(arithmetic_family_registry_retired_row(
                "carry-chain",
                "decimal carry-chain connector values",
                "decimal-carry-propagation-family",
                replication,
                "carry-chain branch failed the separator ladder; keep excluded before selecting another arithmetic connector family",
            ));
        } else {
            rows.push(ConnectorWidth6ArithmeticFamilyRegistryRow {
                family_id: "carry-chain".to_string(),
                family_label: "decimal carry-chain connector values".to_string(),
                family_class: "decimal-carry-propagation-family".to_string(),
                status: "theorem-candidate".to_string(),
                evidence_branch_id: Some(replication.source_branch_id.clone()),
                evidence_modulus: Some(replication.source_modulus),
                evidence_decision: Some(replication.replication_decision.clone()),
                evidence_status: Some(replication.separator_status.clone()),
                next_target: replication.next_experiment_target.clone(),
                rationale:
                    "carry-chain branch retained its separator on the third ladder; theorem-candidate material only, not a connector law"
                        .to_string(),
            });
        }
    }
    let base_mixed_collapsed = base_mixed_replication.is_some_and(|replication| {
        replication.next_experiment_target
            == "select-next-arithmetic-connector-family-after-base-mixed-three-ladder-collapse"
    });
    let base_mixed_theorem_candidate = base_mixed_replication.is_some_and(|replication| {
        replication
            .next_experiment_target
            .starts_with("lean-finite-classifier-candidate-orthogonal-base-mixed-")
    });
    if let Some(replication) = base_mixed_replication {
        if base_mixed_collapsed {
            rows.push(arithmetic_family_registry_retired_row(
                "base-mixed",
                "non-decimal maintained-lane connector values",
                "base-mixed-maintained-lane-family",
                replication,
                "base-mixed maintained-lane branch failed the separator ladder; keep excluded before selecting another connector surface",
            ));
        } else {
            rows.push(ConnectorWidth6ArithmeticFamilyRegistryRow {
                family_id: "base-mixed".to_string(),
                family_label: "non-decimal maintained-lane connector values".to_string(),
                family_class: "base-mixed-maintained-lane-family".to_string(),
                status: "theorem-candidate".to_string(),
                evidence_branch_id: Some(replication.source_branch_id.clone()),
                evidence_modulus: Some(replication.source_modulus),
                evidence_decision: Some(replication.replication_decision.clone()),
                evidence_status: Some(replication.separator_status.clone()),
                next_target: replication.next_experiment_target.clone(),
                rationale:
                    "base-mixed branch retained its separator on the third ladder; theorem-candidate material only, not a connector law"
                        .to_string(),
            });
        }
    }
    let selected = if base_mixed_collapsed
        || base_mixed_theorem_candidate
        || carry_chain_theorem_candidate
        || cyclic_reptend_theorem_candidate
        || automorphic_repunit_theorem_candidate
    {
        None
    } else if carry_chain_collapsed {
        Some((
            "base-mixed",
            "non-decimal maintained-lane connector values",
            "base-mixed-maintained-lane-family",
            "scan-orthogonal-base-mixed-connectors-under-source-fresh-separator-gate",
            "next connector surface after decimal arithmetic-family collapse; interprets maintained base-6/base-12/base-30 lane words as decimal connector values",
        ))
    } else if cyclic_reptend_collapsed {
        Some((
            "carry-chain",
            "decimal carry-chain connector values",
            "decimal-carry-propagation-family",
            "scan-orthogonal-carry-chain-connectors-under-source-fresh-separator-gate",
            "next arithmetic family after cyclic-reptend collapse; tests trigger digits adjacent to 9-runs and borrow-chain complements",
        ))
    } else if automorphic_repunit_collapsed {
        Some((
            "cyclic-reptend",
            "cyclic-reptend connector values",
            "decimal-repetend-window-family",
            "scan-orthogonal-cyclic-reptend-connectors-under-source-fresh-separator-gate",
            "next arithmetic family after automorphic/repunit collapse; tests cyclic windows of decimal repetends rather than fixed points, CRT lifts, or unit-order orbits",
        ))
    } else if multiplicative_order_collapsed {
        Some((
            "automorphic-repunit",
            "automorphic/repunit-adjacent connector values",
            "base10-fixed-point-perturbation-family",
            "scan-orthogonal-automorphic-repunit-connectors-under-source-fresh-separator-gate",
            "next arithmetic family after multiplicative-order collapse; tests base-10 automorphic fixed points and local repunit-block perturbations",
        ))
    } else if crt_paired_collapsed {
        Some((
            "multiplicative-order",
            "multiplicative-order connector values",
            "unit-order-orbit-family",
            "scan-orthogonal-multiplicative-order-connectors-under-source-fresh-separator-gate",
            "next arithmetic family after CRT-paired collapse; uses powers in small-prime unit groups rather than CRT lifts",
        ))
    } else {
        Some((
            "crt-paired",
            "CRT-paired connector values",
            "paired-congruence-system",
            "scan-orthogonal-crt-paired-connectors-under-source-fresh-separator-gate",
            "next arithmetic family after square/triangular, residue-lattice, and modular-walk collapses; uses paired CRT constraints rather than one-modulus walks",
        ))
    };
    if let Some((family_id, family_label, family_class, selected_target, rationale)) = selected {
        rows.push(ConnectorWidth6ArithmeticFamilyRegistryRow {
            family_id: family_id.to_string(),
            family_label: family_label.to_string(),
            family_class: family_class.to_string(),
            status: "selected-next-family".to_string(),
            evidence_branch_id: None,
            evidence_modulus: None,
            evidence_decision: None,
            evidence_status: None,
            next_target: selected_target.to_string(),
            rationale: rationale.to_string(),
        });
    }

    Some(ConnectorWidth6ArithmeticFamilyRegistry {
        selection_rule: if base_mixed_collapsed {
            "after-decimal-arithmetic-and-base-mixed-three-ladder-collapse;record-retired-arithmetic-connector-families;require-a-new-non-decimal-or-non-connector-surface"
        } else if base_mixed_theorem_candidate {
            "after-decimal-arithmetic-collapse;base-mixed-maintained-lane-family-retained-separator;route-to-finite-classifier-theorem-candidate"
        } else if carry_chain_collapsed {
            "after-modular-walk-crt-paired-multiplicative-order-automorphic-repunit-cyclic-reptend-and-carry-chain-three-ladder-collapse;record-retired-arithmetic-connector-families;select-base-mixed-maintained-lane-family"
        } else if cyclic_reptend_collapsed {
            "after-modular-walk-crt-paired-multiplicative-order-automorphic-repunit-and-cyclic-reptend-three-ladder-collapse;record-retired-arithmetic-connector-families;select-carry-chain-family"
        } else if automorphic_repunit_collapsed {
            "after-modular-walk-crt-paired-multiplicative-order-and-automorphic-repunit-three-ladder-collapse;record-retired-arithmetic-connector-families;select-cyclic-reptend-family"
        } else if multiplicative_order_collapsed {
            "after-modular-walk-crt-paired-and-multiplicative-order-three-ladder-collapse;record-retired-arithmetic-connector-families;select-automorphic-repunit-fixed-point-perturbation-family"
        } else {
            "after-modular-walk-and-crt-paired-three-ladder-collapse;record-retired-arithmetic-connector-families;select-first-untried-structurally-distinct-family"
        }
        .to_string(),
        retired_family_count: rows
            .iter()
            .filter(|row| row.status == "retired")
            .count(),
        active_family_count: rows
            .iter()
            .filter(|row| row.status == "selected-next-family")
            .count(),
        selected_next_family_id: selected.map(|selected| selected.0.to_string()),
        selected_next_family_target: selected
            .map(|selected| selected.3.to_string())
            .or_else(|| {
                base_mixed_collapsed.then(|| {
                    "select-new-connector-surface-after-base-mixed-three-ladder-collapse"
                        .to_string()
                })
            })
            .or_else(|| {
                if base_mixed_theorem_candidate {
                    base_mixed_replication
                        .map(|replication| replication.next_experiment_target.clone())
                } else {
                    None
                }
            })
            .or_else(|| {
                carry_chain_collapsed.then(|| {
                    "select-new-arithmetic-connector-family-after-carry-chain-three-ladder-collapse"
                        .to_string()
                })
            })
            .or_else(|| {
                if carry_chain_theorem_candidate {
                    carry_chain_replication
                        .map(|replication| replication.next_experiment_target.clone())
                } else {
                    None
                }
            })
            .or_else(|| {
                if cyclic_reptend_theorem_candidate {
                    cyclic_reptend_replication
                        .map(|replication| replication.next_experiment_target.clone())
                } else {
                    None
                }
            })
            .or_else(|| {
                if automorphic_repunit_theorem_candidate {
                    automorphic_repunit_replication
                        .map(|replication| replication.next_experiment_target.clone())
                } else {
                    None
                }
            }),
        registry_decision: if base_mixed_collapsed {
            "retired-arithmetic-families-recorded-base-mixed-collapsed-select-new-surface"
                .to_string()
        } else if base_mixed_theorem_candidate {
            "retired-arithmetic-families-recorded-base-mixed-retained-theorem-candidate"
                .to_string()
        } else if carry_chain_collapsed {
            "retired-arithmetic-families-recorded-select-base-mixed-connectors-next".to_string()
        } else if carry_chain_theorem_candidate {
            "retired-arithmetic-families-recorded-carry-chain-retained-theorem-candidate"
                .to_string()
        } else if cyclic_reptend_collapsed {
            "retired-arithmetic-families-recorded-select-carry-chain-connectors-next".to_string()
        } else if cyclic_reptend_theorem_candidate {
            "retired-arithmetic-families-recorded-cyclic-reptend-retained-theorem-candidate"
                .to_string()
        } else if automorphic_repunit_collapsed {
            "retired-arithmetic-families-recorded-select-cyclic-reptend-connectors-next"
                .to_string()
        } else if automorphic_repunit_theorem_candidate {
            "retired-arithmetic-families-recorded-automorphic-repunit-retained-theorem-candidate"
                .to_string()
        } else if multiplicative_order_collapsed {
            "retired-arithmetic-families-recorded-select-automorphic-repunit-connectors-next"
                .to_string()
        } else if crt_paired_collapsed {
            "retired-arithmetic-families-recorded-select-multiplicative-order-connectors-next"
                .to_string()
        } else {
            "retired-arithmetic-families-recorded-select-crt-paired-connectors-next"
                .to_string()
        },
        rows,
    })
}

fn arithmetic_family_registry_retired_row(
    family_id: &str,
    family_label: &str,
    family_class: &str,
    replication: &ConnectorWidth6OrthogonalPairFamilyResidueSeparatorReplication,
    rationale: &str,
) -> ConnectorWidth6ArithmeticFamilyRegistryRow {
    ConnectorWidth6ArithmeticFamilyRegistryRow {
        family_id: family_id.to_string(),
        family_label: family_label.to_string(),
        family_class: family_class.to_string(),
        status: "retired".to_string(),
        evidence_branch_id: Some(replication.source_branch_id.clone()),
        evidence_modulus: Some(replication.source_modulus),
        evidence_decision: Some(replication.replication_decision.clone()),
        evidence_status: Some(replication.separator_status.clone()),
        next_target: replication.next_experiment_target.clone(),
        rationale: rationale.to_string(),
    }
}

fn build_orthogonal_crt_paired_connector_control_matrix(
    registry: &Option<ConnectorWidth6ArithmeticFamilyRegistry>,
) -> Option<ConnectorWidth6OrthogonalPairFamilyControlMatrix> {
    if registry
        .as_ref()
        .and_then(|registry| registry.selected_next_family_id.as_deref())
        != Some("crt-paired")
    {
        return None;
    }

    let widths = (5..=9).collect::<Vec<_>>();
    let pair_families = vec![
        build_orthogonal_crt_paired_connector_control(
            "cousin-prime-gap4",
            4,
            connector_orthogonal_gap4_source_pair_cases(),
            connector_orthogonal_gap4_fresh_pair_cases(),
            &widths,
        ),
        build_orthogonal_crt_paired_connector_control(
            "sexy-prime-gap6",
            6,
            connector_orthogonal_gap6_source_pair_cases(),
            connector_orthogonal_gap6_fresh_pair_cases(),
            &widths,
        ),
    ];
    let source_row_count = pair_families.iter().map(|family| family.row_count).sum();
    let fresh_row_count = pair_families
        .iter()
        .filter_map(|family| family.fresh_replication.as_ref())
        .map(|replication| replication.row_count)
        .sum();
    let mut selected_candidates = pair_families
        .iter()
        .filter_map(|family| {
            let selected = family.selected_motif.as_ref()?;
            let replication = family.fresh_replication.as_ref()?;
            (replication.reverse_only_pair_count > 0).then(|| {
                ConnectorWidth6OrthogonalPairFamilySelectedBranch {
                    branch_id: orthogonal_crt_paired_connector_branch_id(
                        replication.pair_gap,
                        replication.width,
                        &replication.connector,
                    ),
                    pair_family: replication.pair_family.clone(),
                    pair_gap: replication.pair_gap,
                    width: replication.width,
                    start_position: replication.start_position,
                    motif_positions: replication.motif_positions.clone(),
                    motif_digits: replication.motif_digits.clone(),
                    connector: replication.connector.clone(),
                    source_reverse_only_pair_count: selected.reverse_only_pair_count,
                    fresh_reverse_only_pair_count: replication.reverse_only_pair_count,
                    fresh_forward_only_pair_count: replication.forward_only_pair_count,
                    fresh_both_hit_pair_count: replication.both_hit_pair_count,
                    fresh_neither_hit_pair_count: replication.neither_hit_pair_count,
                    branch_status: "survived-independent-orthogonal-crt-paired-connector-ladder"
                        .to_string(),
                    next_experiment_target: replication.next_experiment_target.clone(),
                }
            })
        })
        .collect::<Vec<_>>();
    selected_candidates.sort_by(|left, right| {
        right
            .fresh_reverse_only_pair_count
            .cmp(&left.fresh_reverse_only_pair_count)
            .then_with(|| {
                right
                    .source_reverse_only_pair_count
                    .cmp(&left.source_reverse_only_pair_count)
            })
            .then_with(|| left.pair_family.cmp(&right.pair_family))
            .then_with(|| left.width.cmp(&right.width))
            .then_with(|| left.connector.cmp(&right.connector))
    });
    let selected_branch = selected_candidates.into_iter().next();
    let matrix_decision = if selected_branch.is_some() {
        "orthogonal-crt-paired-connector-control-survived-residue-profiler-next"
    } else {
        "orthogonal-crt-paired-connector-control-collapsed-retire-without-lean"
    };
    let next_experiment_target = selected_branch
        .as_ref()
        .map(|branch| branch.next_experiment_target.clone())
        .unwrap_or_else(|| {
            "select-next-arithmetic-connector-family-after-crt-paired-source-fresh-collapse"
                .to_string()
        });

    Some(ConnectorWidth6OrthogonalPairFamilyControlMatrix {
        selection_rule:
            "after-modular-walk-collapse;pivot-to-crt-paired-connector-values;scan-x-constrained-by-two-small-prime-residue-equations-and-lifted-by-their-product;source-fresh-separator-survival-before-theorem-candidate"
                .to_string(),
        pair_family_count: pair_families.len(),
        widths,
        motif_width: 0,
        digits: Vec::new(),
        position_scope:
            "CRT-paired connector values x = lift*(m*n)+crt(r_m,r_n), with (m,n) in [(7,11),(7,13),(11,17),(13,19),(17,23)], lift in 16..=31, and residues generated from a fixed seed list; nonzero digit positions are derived after value selection"
                .to_string(),
        excluded_connector_rule:
            "exclude connector values divisible by 3 as exact-arithmetic nuisance filter; no non-twin theorem claim attached"
                .to_string(),
        source_row_count,
        fresh_row_count,
        selected_branch,
        matrix_decision: matrix_decision.to_string(),
        next_experiment_target,
        pair_families,
    })
}

fn build_orthogonal_crt_paired_connector_control(
    pair_family: &str,
    pair_gap: u32,
    source_pair_cases: Vec<PairCase>,
    fresh_pair_cases: Vec<PairCase>,
    widths: &[u32],
) -> ConnectorWidth6OrthogonalPairFamilyControl {
    let mut rows = Vec::new();
    for case in &source_pair_cases {
        for &width in widths {
            for connector_value in crt_paired_connector_candidate_values(width) {
                if let Some(row) = build_connector_value_row(
                    case,
                    width,
                    connector_value,
                    &format!("orthogonal-crt-paired-connector-control-source-{pair_family}"),
                ) {
                    rows.push(row);
                }
            }
        }
    }
    rows.sort_by(|left, right| {
        left.left
            .cmp(&right.left)
            .then_with(|| left.right.cmp(&right.right))
            .then_with(|| left.width.cmp(&right.width))
            .then_with(|| left.connector.cmp(&right.connector))
    });
    let rankings = rank_multi_digit_motif_cells(&rows);
    let selected_motif = rankings
        .iter()
        .find(|row| row.reverse_only_pair_count > 0)
        .cloned();
    let fresh_replication = selected_motif.as_ref().map(|motif| {
        build_orthogonal_crt_paired_connector_replication(
            pair_family,
            pair_gap,
            motif,
            &fresh_pair_cases,
        )
    });
    let theorem_blocked_row_count = rows.iter().filter(|row| row.mod3_theorem_blocked).count();
    let nonblocked_row_count = rows.iter().filter(|row| !row.mod3_theorem_blocked).count();
    let reverse_only_motif_count = rankings
        .iter()
        .filter(|row| row.reverse_only_pair_count > 0)
        .count();
    let picker_decision = if selected_motif.is_some() {
        "orthogonal-crt-paired-connector-source-value-selected-for-fresh-ladder"
    } else {
        "orthogonal-crt-paired-connector-source-picker-found-no-reverse-only-branch"
    };
    let next_experiment_target = fresh_replication
        .as_ref()
        .map(|replication| replication.next_experiment_target.clone())
        .or_else(|| {
            selected_motif.as_ref().map(|motif| {
                format!(
                    "independently-replicate-orthogonal-crtpaired-gap{}-connector-{}-width{}",
                    pair_gap, motif.connector, motif.width
                )
            })
        })
        .unwrap_or_else(|| format!("no-orthogonal-crtpaired-{pair_family}-connector-selected"));

    ConnectorWidth6OrthogonalPairFamilyControl {
        pair_family: pair_family.to_string(),
        pair_gap,
        source_pair_count: source_pair_cases.len(),
        source_pair_labels: source_pair_cases
            .iter()
            .map(|case| case.name.to_string())
            .collect(),
        fresh_pair_count: fresh_pair_cases.len(),
        fresh_pair_labels: fresh_pair_cases
            .iter()
            .map(|case| case.name.to_string())
            .collect(),
        row_count: rows.len(),
        theorem_blocked_row_count,
        nonblocked_row_count,
        ranked_motif_count: rankings.len(),
        reverse_only_motif_count,
        selected_motif,
        fresh_replication,
        picker_decision: picker_decision.to_string(),
        next_experiment_target,
        rankings,
        rows,
    }
}

fn build_orthogonal_crt_paired_connector_replication(
    pair_family: &str,
    pair_gap: u32,
    motif: &ConnectorWidth6MultiDigitMotifRankRow,
    pair_cases: &[PairCase],
) -> ConnectorWidth6OrthogonalPairFamilyReplication {
    let connector_value = motif
        .connector
        .parse::<u128>()
        .expect("generated connector is numeric");
    let mut rows = Vec::new();
    for case in pair_cases {
        if let Some(row) = build_connector_value_row(
            case,
            motif.width,
            connector_value,
            &format!("orthogonal-crt-paired-connector-control-fresh-{pair_family}"),
        ) {
            rows.push(row);
        }
    }
    rows.sort_by(|left, right| {
        left.left
            .cmp(&right.left)
            .then_with(|| left.right.cmp(&right.right))
    });
    let row_count = rows.len();
    let theorem_blocked_row_count = rows.iter().filter(|row| row.mod3_theorem_blocked).count();
    let nonblocked_row_count = rows.iter().filter(|row| !row.mod3_theorem_blocked).count();
    let residue_admissible_pair_count = rows
        .iter()
        .filter(|row| row.residue_admissible_in_both_directions)
        .count();
    let reverse_only_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .count();
    let forward_only_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "forward-only-prime-hit")
        .count();
    let both_hit_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "both-prime-hit")
        .count();
    let neither_hit_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "neither-prime-hit")
        .count();
    let reverse_only_pair_labels = rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .map(|row| row.pair_label.clone())
        .collect::<Vec<_>>();
    let replication_decision = if nonblocked_row_count > 0 && reverse_only_pair_count > 0 {
        "survived-orthogonal-pair-family-independent-ladder-residue-profiler-next"
    } else {
        "collapsed-orthogonal-pair-family-independent-ladder-retire-without-lean"
    };
    let source_branch_id =
        orthogonal_crt_paired_connector_branch_id(pair_gap, motif.width, &motif.connector);
    let next_experiment_target = if nonblocked_row_count > 0 && reverse_only_pair_count > 0 {
        format!(
            "residue-profile-orthogonal-crtpaired-gap{}-connector-{}-width{}",
            pair_gap, motif.connector, motif.width
        )
    } else {
        format!(
            "retire-orthogonal-crtpaired-gap{}-connector-{}-width{}",
            pair_gap, motif.connector, motif.width
        )
    };

    ConnectorWidth6OrthogonalPairFamilyReplication {
        selection_rule: format!(
            "selected-{pair_family}-crt-paired-connector-on-fresh-disjoint-prime-pair-ladder"
        ),
        pair_family: pair_family.to_string(),
        pair_gap,
        source_branch_id,
        source_motif_rank: motif.rank,
        width: motif.width,
        start_position: motif.start_position,
        motif_positions: motif.motif_positions.clone(),
        motif_digits: motif.motif_digits.clone(),
        connector: motif.connector.clone(),
        fresh_pair_count: pair_cases.len(),
        fresh_pair_labels: pair_cases
            .iter()
            .map(|case| case.name.to_string())
            .collect(),
        row_count,
        theorem_blocked_row_count,
        nonblocked_row_count,
        residue_admissible_pair_count,
        reverse_only_pair_count,
        forward_only_pair_count,
        both_hit_pair_count,
        neither_hit_pair_count,
        reverse_only_pair_labels,
        replication_decision: replication_decision.to_string(),
        next_experiment_target,
        rows,
    }
}

fn build_orthogonal_multiplicative_order_connector_control_matrix(
    registry: &Option<ConnectorWidth6ArithmeticFamilyRegistry>,
) -> Option<ConnectorWidth6OrthogonalPairFamilyControlMatrix> {
    if registry
        .as_ref()
        .and_then(|registry| registry.selected_next_family_id.as_deref())
        != Some("multiplicative-order")
    {
        return None;
    }

    let widths = (5..=9).collect::<Vec<_>>();
    let pair_families = vec![
        build_orthogonal_multiplicative_order_connector_control(
            "cousin-prime-gap4",
            4,
            connector_orthogonal_gap4_source_pair_cases(),
            connector_orthogonal_gap4_fresh_pair_cases(),
            &widths,
        ),
        build_orthogonal_multiplicative_order_connector_control(
            "sexy-prime-gap6",
            6,
            connector_orthogonal_gap6_source_pair_cases(),
            connector_orthogonal_gap6_fresh_pair_cases(),
            &widths,
        ),
    ];
    let source_row_count = pair_families.iter().map(|family| family.row_count).sum();
    let fresh_row_count = pair_families
        .iter()
        .filter_map(|family| family.fresh_replication.as_ref())
        .map(|replication| replication.row_count)
        .sum();
    let mut selected_candidates = pair_families
        .iter()
        .filter_map(|family| {
            let selected = family.selected_motif.as_ref()?;
            let replication = family.fresh_replication.as_ref()?;
            (replication.reverse_only_pair_count > 0).then(|| {
                ConnectorWidth6OrthogonalPairFamilySelectedBranch {
                    branch_id: orthogonal_multiplicative_order_connector_branch_id(
                        replication.pair_gap,
                        replication.width,
                        &replication.connector,
                    ),
                    pair_family: replication.pair_family.clone(),
                    pair_gap: replication.pair_gap,
                    width: replication.width,
                    start_position: replication.start_position,
                    motif_positions: replication.motif_positions.clone(),
                    motif_digits: replication.motif_digits.clone(),
                    connector: replication.connector.clone(),
                    source_reverse_only_pair_count: selected.reverse_only_pair_count,
                    fresh_reverse_only_pair_count: replication.reverse_only_pair_count,
                    fresh_forward_only_pair_count: replication.forward_only_pair_count,
                    fresh_both_hit_pair_count: replication.both_hit_pair_count,
                    fresh_neither_hit_pair_count: replication.neither_hit_pair_count,
                    branch_status:
                        "survived-independent-orthogonal-multiplicative-order-connector-ladder"
                            .to_string(),
                    next_experiment_target: replication.next_experiment_target.clone(),
                }
            })
        })
        .collect::<Vec<_>>();
    selected_candidates.sort_by(|left, right| {
        right
            .fresh_reverse_only_pair_count
            .cmp(&left.fresh_reverse_only_pair_count)
            .then_with(|| {
                right
                    .source_reverse_only_pair_count
                    .cmp(&left.source_reverse_only_pair_count)
            })
            .then_with(|| left.pair_family.cmp(&right.pair_family))
            .then_with(|| left.width.cmp(&right.width))
            .then_with(|| left.connector.cmp(&right.connector))
    });
    let selected_branch = selected_candidates.into_iter().next();
    let matrix_decision = if selected_branch.is_some() {
        "orthogonal-multiplicative-order-connector-control-survived-residue-profiler-next"
    } else {
        "orthogonal-multiplicative-order-connector-control-collapsed-retire-without-lean"
    };
    let next_experiment_target = selected_branch
        .as_ref()
        .map(|branch| branch.next_experiment_target.clone())
        .unwrap_or_else(|| {
            "select-next-arithmetic-connector-family-after-multiplicative-order-source-fresh-collapse"
                .to_string()
        });

    Some(ConnectorWidth6OrthogonalPairFamilyControlMatrix {
        selection_rule:
            "after-crt-paired-collapse;pivot-to-multiplicative-order-connector-values;scan-small-prime-unit-power-orbits-lifted-outside-prior-quotient-windows;source-fresh-separator-survival-before-theorem-candidate"
                .to_string(),
        pair_family_count: pair_families.len(),
        widths,
        motif_width: 0,
        digits: Vec::new(),
        position_scope:
            "multiplicative-order connector values q*m+g^e mod m, with m in [7,11,13,17,19,23,29,31], generators [2,3,5,10] where coprime to m, e in 1..m-1, and q in 73..=120; nonzero digit positions are derived after value selection"
                .to_string(),
        excluded_connector_rule:
            "exclude connector values divisible by 3 as exact-arithmetic nuisance filter; no non-twin theorem claim attached"
                .to_string(),
        source_row_count,
        fresh_row_count,
        selected_branch,
        matrix_decision: matrix_decision.to_string(),
        next_experiment_target,
        pair_families,
    })
}

fn build_orthogonal_multiplicative_order_connector_control(
    pair_family: &str,
    pair_gap: u32,
    source_pair_cases: Vec<PairCase>,
    fresh_pair_cases: Vec<PairCase>,
    widths: &[u32],
) -> ConnectorWidth6OrthogonalPairFamilyControl {
    let mut rows = Vec::new();
    for case in &source_pair_cases {
        for &width in widths {
            for connector_value in multiplicative_order_connector_candidate_values(width) {
                if let Some(row) = build_connector_value_row(
                    case,
                    width,
                    connector_value,
                    &format!(
                        "orthogonal-multiplicative-order-connector-control-source-{pair_family}"
                    ),
                ) {
                    rows.push(row);
                }
            }
        }
    }
    rows.sort_by(|left, right| {
        left.left
            .cmp(&right.left)
            .then_with(|| left.right.cmp(&right.right))
            .then_with(|| left.width.cmp(&right.width))
            .then_with(|| left.connector.cmp(&right.connector))
    });
    let rankings = rank_multi_digit_motif_cells(&rows);
    let selected_motif = rankings
        .iter()
        .find(|row| row.reverse_only_pair_count > 0)
        .cloned();
    let fresh_replication = selected_motif.as_ref().map(|motif| {
        build_orthogonal_multiplicative_order_connector_replication(
            pair_family,
            pair_gap,
            motif,
            &fresh_pair_cases,
        )
    });
    let theorem_blocked_row_count = rows.iter().filter(|row| row.mod3_theorem_blocked).count();
    let nonblocked_row_count = rows.iter().filter(|row| !row.mod3_theorem_blocked).count();
    let reverse_only_motif_count = rankings
        .iter()
        .filter(|row| row.reverse_only_pair_count > 0)
        .count();
    let picker_decision = if selected_motif.is_some() {
        "orthogonal-multiplicative-order-connector-source-value-selected-for-fresh-ladder"
    } else {
        "orthogonal-multiplicative-order-connector-source-picker-found-no-reverse-only-branch"
    };
    let next_experiment_target = fresh_replication
        .as_ref()
        .map(|replication| replication.next_experiment_target.clone())
        .or_else(|| {
            selected_motif.as_ref().map(|motif| {
                format!(
                    "independently-replicate-orthogonal-multorder-gap{}-connector-{}-width{}",
                    pair_gap, motif.connector, motif.width
                )
            })
        })
        .unwrap_or_else(|| format!("no-orthogonal-multorder-{pair_family}-connector-selected"));

    ConnectorWidth6OrthogonalPairFamilyControl {
        pair_family: pair_family.to_string(),
        pair_gap,
        source_pair_count: source_pair_cases.len(),
        source_pair_labels: source_pair_cases
            .iter()
            .map(|case| case.name.to_string())
            .collect(),
        fresh_pair_count: fresh_pair_cases.len(),
        fresh_pair_labels: fresh_pair_cases
            .iter()
            .map(|case| case.name.to_string())
            .collect(),
        row_count: rows.len(),
        theorem_blocked_row_count,
        nonblocked_row_count,
        ranked_motif_count: rankings.len(),
        reverse_only_motif_count,
        selected_motif,
        fresh_replication,
        picker_decision: picker_decision.to_string(),
        next_experiment_target,
        rankings,
        rows,
    }
}

fn build_orthogonal_multiplicative_order_connector_replication(
    pair_family: &str,
    pair_gap: u32,
    motif: &ConnectorWidth6MultiDigitMotifRankRow,
    pair_cases: &[PairCase],
) -> ConnectorWidth6OrthogonalPairFamilyReplication {
    let connector_value = motif
        .connector
        .parse::<u128>()
        .expect("generated connector is numeric");
    let mut rows = Vec::new();
    for case in pair_cases {
        if let Some(row) = build_connector_value_row(
            case,
            motif.width,
            connector_value,
            &format!("orthogonal-multiplicative-order-connector-control-fresh-{pair_family}"),
        ) {
            rows.push(row);
        }
    }
    rows.sort_by(|left, right| {
        left.left
            .cmp(&right.left)
            .then_with(|| left.right.cmp(&right.right))
    });
    let row_count = rows.len();
    let theorem_blocked_row_count = rows.iter().filter(|row| row.mod3_theorem_blocked).count();
    let nonblocked_row_count = rows.iter().filter(|row| !row.mod3_theorem_blocked).count();
    let residue_admissible_pair_count = rows
        .iter()
        .filter(|row| row.residue_admissible_in_both_directions)
        .count();
    let reverse_only_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .count();
    let forward_only_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "forward-only-prime-hit")
        .count();
    let both_hit_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "both-prime-hit")
        .count();
    let neither_hit_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "neither-prime-hit")
        .count();
    let reverse_only_pair_labels = rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .map(|row| row.pair_label.clone())
        .collect::<Vec<_>>();
    let replication_decision = if nonblocked_row_count > 0 && reverse_only_pair_count > 0 {
        "survived-orthogonal-pair-family-independent-ladder-residue-profiler-next"
    } else {
        "collapsed-orthogonal-pair-family-independent-ladder-retire-without-lean"
    };
    let source_branch_id = orthogonal_multiplicative_order_connector_branch_id(
        pair_gap,
        motif.width,
        &motif.connector,
    );
    let next_experiment_target = if nonblocked_row_count > 0 && reverse_only_pair_count > 0 {
        format!(
            "residue-profile-orthogonal-multorder-gap{}-connector-{}-width{}",
            pair_gap, motif.connector, motif.width
        )
    } else {
        format!(
            "retire-orthogonal-multorder-gap{}-connector-{}-width{}",
            pair_gap, motif.connector, motif.width
        )
    };

    ConnectorWidth6OrthogonalPairFamilyReplication {
        selection_rule: format!(
            "selected-{pair_family}-multiplicative-order-connector-on-fresh-disjoint-prime-pair-ladder"
        ),
        pair_family: pair_family.to_string(),
        pair_gap,
        source_branch_id,
        source_motif_rank: motif.rank,
        width: motif.width,
        start_position: motif.start_position,
        motif_positions: motif.motif_positions.clone(),
        motif_digits: motif.motif_digits.clone(),
        connector: motif.connector.clone(),
        fresh_pair_count: pair_cases.len(),
        fresh_pair_labels: pair_cases
            .iter()
            .map(|case| case.name.to_string())
            .collect(),
        row_count,
        theorem_blocked_row_count,
        nonblocked_row_count,
        residue_admissible_pair_count,
        reverse_only_pair_count,
        forward_only_pair_count,
        both_hit_pair_count,
        neither_hit_pair_count,
        reverse_only_pair_labels,
        replication_decision: replication_decision.to_string(),
        next_experiment_target,
        rows,
    }
}

