fn pair_family_connector_value_rankings(
    pair_family: &str,
    source_pair_cases: &[PairCase],
) -> Vec<ConnectorWidth6MultiDigitMotifRankRow> {
    let mut rows = Vec::new();
    for case in source_pair_cases {
        for (width, connector_value) in pair_family_gap_portfolio_connector_values() {
            if let Some(row) = build_connector_value_row(
                case,
                width,
                connector_value,
                &format!("pair-family-topn-source-{pair_family}"),
            ) {
                rows.push(row);
            }
        }
    }
    rank_multi_digit_motif_cells(&rows)
}

fn build_pair_family_topn_motif_surface_profile(
    surface_profile: Option<&ConnectorWidth6PairFamilySurfaceResidueProfile>,
    picker: Option<&ConnectorWidth6PairFamilySurfacePicker>,
) -> Option<ConnectorWidth6PairFamilyTopNMotifSurfaceProfile> {
    let surface_profile = surface_profile?;
    if surface_profile.profile_decision != "no-small-prime-family-surface-residue-separator-found" {
        return None;
    }
    let selected_surface = picker?.selected_surface.as_ref()?;
    if selected_surface.surface_id != surface_profile.surface_id {
        return None;
    }

    let top_n_per_family = 3;
    let mut motif_rows = Vec::new();
    let mut fresh_rows = Vec::new();
    let mut connectors = BTreeSet::new();

    for pair_family in &selected_surface.pair_families {
        let source_pair_cases = connector_pair_family_source_pair_cases(pair_family)?;
        let fresh_pair_cases = connector_pair_family_fresh_pair_cases(pair_family)?;
        let rankings = pair_family_connector_value_rankings(pair_family, &source_pair_cases);
        let top_motifs = rankings
            .iter()
            .filter(|row| row.reverse_only_pair_count > 0)
            .take(top_n_per_family)
            .cloned()
            .collect::<Vec<_>>();

        for motif in top_motifs {
            let connector_value = motif.connector.parse::<u128>().ok()?;
            let mut rows = Vec::new();
            for case in &fresh_pair_cases {
                if let Some(row) = build_connector_value_row(
                    case,
                    motif.width,
                    connector_value,
                    &format!("pair-family-topn-fresh-{pair_family}"),
                ) {
                    rows.push(row);
                }
            }
            rows.sort_by(|left, right| {
                left.left
                    .cmp(&right.left)
                    .then_with(|| left.right.cmp(&right.right))
            });
            let fresh_reverse_only_pair_count = rows
                .iter()
                .filter(|row| row.contrast_class == "reverse-only-prime-hit")
                .count();
            let fresh_forward_only_pair_count = rows
                .iter()
                .filter(|row| row.contrast_class == "forward-only-prime-hit")
                .count();
            let fresh_both_hit_pair_count = rows
                .iter()
                .filter(|row| row.contrast_class == "both-prime-hit")
                .count();
            let fresh_neither_hit_pair_count = rows
                .iter()
                .filter(|row| row.contrast_class == "neither-prime-hit")
                .count();
            let motif_status = if fresh_reverse_only_pair_count > 0 {
                "fresh-reverse-only-survived"
            } else {
                "fresh-reverse-only-collapsed"
            };
            connectors.insert(motif.connector.clone());
            motif_rows.push(ConnectorWidth6PairFamilyTopNMotifRow {
                pair_family: pair_family.clone(),
                pair_gap: 8,
                source_rank: motif.rank,
                width: motif.width,
                connector: motif.connector.clone(),
                source_reverse_only_pair_count: motif.reverse_only_pair_count,
                fresh_reverse_only_pair_count,
                fresh_forward_only_pair_count,
                fresh_both_hit_pair_count,
                fresh_neither_hit_pair_count,
                motif_status: motif_status.to_string(),
            });
            fresh_rows.extend(rows);
        }
    }

    fresh_rows.sort_by(|left, right| {
        left.control_family
            .cmp(&right.control_family)
            .then_with(|| left.connector.cmp(&right.connector))
            .then_with(|| left.left.cmp(&right.left))
            .then_with(|| left.right.cmp(&right.right))
    });
    motif_rows.sort_by(|left, right| {
        left.pair_family
            .cmp(&right.pair_family)
            .then_with(|| left.source_rank.cmp(&right.source_rank))
            .then_with(|| left.connector.cmp(&right.connector))
    });

    let moduli = vec![3_u32, 5, 7, 11, 13, 17, 19, 23, 29, 31];
    let reverse_only_rows = fresh_rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .collect::<Vec<_>>();
    let comparison_rows = fresh_rows
        .iter()
        .filter(|row| row.contrast_class != "reverse-only-prime-hit")
        .collect::<Vec<_>>();
    let mut residue_rows = moduli
        .iter()
        .map(|modulus| {
            let reverse_only_residues = reverse_only_rows
                .iter()
                .map(|row| (row.left % *modulus as u128) as u32)
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            let comparison_residues = comparison_rows
                .iter()
                .map(|row| (row.left % *modulus as u128) as u32)
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            let comparison_set = comparison_residues.iter().copied().collect::<BTreeSet<_>>();
            let shared_residues = reverse_only_residues
                .iter()
                .copied()
                .filter(|residue| comparison_set.contains(residue))
                .collect::<Vec<_>>();
            let separator_status = if reverse_only_residues.is_empty() {
                "no-reverse-only-residues"
            } else if shared_residues.is_empty() {
                "exact-residue-separator"
            } else {
                "overlapping-residue-classes"
            };

            ConnectorWidth6NonMod3CandidateResidueProfileRow {
                modulus: *modulus,
                reverse_only_pair_count: reverse_only_rows.len(),
                comparison_pair_count: comparison_rows.len(),
                reverse_only_residues,
                comparison_residues,
                shared_residues,
                separator_status: separator_status.to_string(),
            }
        })
        .collect::<Vec<_>>();
    residue_rows.sort_by(|left, right| left.modulus.cmp(&right.modulus));

    let exact_separator_count = residue_rows
        .iter()
        .filter(|row| row.separator_status == "exact-residue-separator")
        .count();
    let best_separator = residue_rows
        .iter()
        .filter(|row| row.separator_status == "exact-residue-separator")
        .min_by(|left, right| {
            left.reverse_only_residues
                .len()
                .cmp(&right.reverse_only_residues.len())
                .then_with(|| left.modulus.cmp(&right.modulus))
        })
        .cloned();
    let profile_decision = if best_separator.is_some() {
        "small-prime-topn-family-surface-residue-separator-found-replicate-before-lean"
    } else {
        "no-small-prime-topn-family-surface-residue-separator-found"
    };
    let next_experiment_target = best_separator
        .as_ref()
        .map(|separator| {
            format!(
                "replicate-topn-family-surface-{}-mod{}-residue-separator-before-lean",
                selected_surface.surface_id, separator.modulus
            )
        })
        .unwrap_or_else(|| {
            format!(
                "select-new-family-level-replication-surface-after-topn-{}-profile-no-small-prime-separator",
                selected_surface.surface_id
            )
        });

    Some(ConnectorWidth6PairFamilyTopNMotifSurfaceProfile {
        selection_rule:
            "after-selected-branch-family-surface-profile-fails;scan-top-3-source-motifs-per-pair-family-on-fresh-ladders-before-residue-profile"
                .to_string(),
        source_surface_id: selected_surface.surface_id.clone(),
        source_surface_label: selected_surface.surface_label.clone(),
        top_n_per_family,
        pair_family_count: selected_surface.pair_families.len(),
        pair_families: selected_surface.pair_families.clone(),
        source_motif_count: motif_rows.len(),
        fresh_survivor_motif_count: motif_rows
            .iter()
            .filter(|row| row.fresh_reverse_only_pair_count > 0)
            .count(),
        fresh_reverse_only_total: motif_rows
            .iter()
            .map(|row| row.fresh_reverse_only_pair_count)
            .sum(),
        fresh_forward_only_total: motif_rows
            .iter()
            .map(|row| row.fresh_forward_only_pair_count)
            .sum(),
        connectors: connectors.into_iter().collect(),
        moduli,
        row_count: fresh_rows.len(),
        reverse_only_pair_count: reverse_only_rows.len(),
        comparison_pair_count: comparison_rows.len(),
        profiled_modulus_count: residue_rows.len(),
        exact_separator_count,
        best_separator,
        profile_decision: profile_decision.to_string(),
        next_experiment_target,
        motif_rows,
        rows: residue_rows,
    })
}

fn build_pair_family_gap_cohort_geometry_control(
    topn_profile: Option<&ConnectorWidth6PairFamilyTopNMotifSurfaceProfile>,
) -> Option<ConnectorWidth6PairFamilyGapCohortGeometryControl> {
    let topn_profile = topn_profile?;
    if topn_profile.profile_decision != "no-small-prime-topn-family-surface-residue-separator-found"
    {
        return None;
    }

    let pair_families = vec![
        "prime-gap20".to_string(),
        "prime-gap22".to_string(),
        "prime-gap24".to_string(),
    ];
    let top_n_per_family = 10;
    let mut motif_rows = Vec::new();

    for pair_family in &pair_families {
        let source_pair_cases = connector_pair_family_source_pair_cases(pair_family)?;
        let fresh_pair_cases = connector_pair_family_fresh_pair_cases(pair_family)?;
        let rankings = pair_family_connector_value_rankings(pair_family, &source_pair_cases);
        let top_motifs = rankings
            .iter()
            .filter(|row| row.reverse_only_pair_count > 0)
            .take(top_n_per_family)
            .cloned()
            .collect::<Vec<_>>();

        for motif in top_motifs {
            let connector_value = motif.connector.parse::<u128>().ok()?;
            let mut rows = Vec::new();
            for case in &fresh_pair_cases {
                if let Some(row) = build_connector_value_row(
                    case,
                    motif.width,
                    connector_value,
                    &format!("pair-family-gap-cohort-geometry-fresh-{pair_family}"),
                ) {
                    rows.push(row);
                }
            }
            let fresh_reverse_only_pair_count = rows
                .iter()
                .filter(|row| row.contrast_class == "reverse-only-prime-hit")
                .count();
            let fresh_forward_only_pair_count = rows
                .iter()
                .filter(|row| row.contrast_class == "forward-only-prime-hit")
                .count();
            let fresh_both_hit_pair_count = rows
                .iter()
                .filter(|row| row.contrast_class == "both-prime-hit")
                .count();
            let fresh_neither_hit_pair_count = rows
                .iter()
                .filter(|row| row.contrast_class == "neither-prime-hit")
                .count();
            let motif_status = if fresh_reverse_only_pair_count > 0 {
                "fresh-reverse-only-survived"
            } else {
                "fresh-reverse-only-collapsed"
            };
            motif_rows.push(ConnectorWidth6PairFamilyTopNMotifRow {
                pair_family: pair_family.clone(),
                pair_gap: pair_family_gap(pair_family)?,
                source_rank: motif.rank,
                width: motif.width,
                connector: motif.connector.clone(),
                source_reverse_only_pair_count: motif.reverse_only_pair_count,
                fresh_reverse_only_pair_count,
                fresh_forward_only_pair_count,
                fresh_both_hit_pair_count,
                fresh_neither_hit_pair_count,
                motif_status: motif_status.to_string(),
            });
        }
    }

    motif_rows.sort_by(|left, right| {
        left.pair_family
            .cmp(&right.pair_family)
            .then_with(|| left.source_rank.cmp(&right.source_rank))
            .then_with(|| left.width.cmp(&right.width))
            .then_with(|| left.connector.cmp(&right.connector))
    });

    let mut grouped: BTreeMap<(u32, String), Vec<&ConnectorWidth6PairFamilyTopNMotifRow>> =
        BTreeMap::new();
    for row in &motif_rows {
        grouped
            .entry((row.width, row.connector.clone()))
            .or_default()
            .push(row);
    }

    let mut geometry_rows = grouped
        .into_iter()
        .map(|((width, connector), rows)| {
            let source_pair_families = rows
                .iter()
                .map(|row| row.pair_family.clone())
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            let fresh_pair_families = rows
                .iter()
                .filter(|row| row.fresh_reverse_only_pair_count > 0)
                .map(|row| row.pair_family.clone())
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            let source_selected_count = source_pair_families.len();
            let fresh_survivor_family_count = fresh_pair_families.len();
            let source_reverse_only_total = rows
                .iter()
                .map(|row| row.source_reverse_only_pair_count)
                .sum();
            let fresh_reverse_only_total = rows
                .iter()
                .map(|row| row.fresh_reverse_only_pair_count)
                .sum();
            let fresh_forward_only_total = rows
                .iter()
                .map(|row| row.fresh_forward_only_pair_count)
                .sum();
            let fresh_both_hit_total = rows.iter().map(|row| row.fresh_both_hit_pair_count).sum();
            let fresh_neither_hit_total = rows
                .iter()
                .map(|row| row.fresh_neither_hit_pair_count)
                .sum();
            let geometry_status = if source_selected_count >= 2 && fresh_survivor_family_count >= 2
            {
                "geometry-retained-across-gap-families"
            } else {
                "single-family-or-fresh-collapsed"
            };
            let next_experiment_target =
                if geometry_status == "geometry-retained-across-gap-families" {
                    format!(
                        "residue-profile-gap-cohort-width{}-connector-{}-across-gap20-22-24",
                        width, connector
                    )
                } else {
                    format!(
                    "do-not-profile-gap-cohort-width{}-connector-{}-without-shared-fresh-retention",
                    width, connector
                )
                };

            ConnectorWidth6PairFamilyGapCohortGeometryRow {
                width,
                connector,
                source_selected_count,
                source_reverse_only_total,
                source_pair_families,
                fresh_survivor_family_count,
                fresh_reverse_only_total,
                fresh_forward_only_total,
                fresh_both_hit_total,
                fresh_neither_hit_total,
                fresh_pair_families,
                geometry_status: geometry_status.to_string(),
                next_experiment_target,
            }
        })
        .collect::<Vec<_>>();

    geometry_rows.sort_by(|left, right| {
        right
            .fresh_survivor_family_count
            .cmp(&left.fresh_survivor_family_count)
            .then_with(|| {
                right
                    .fresh_reverse_only_total
                    .cmp(&left.fresh_reverse_only_total)
            })
            .then_with(|| {
                left.fresh_forward_only_total
                    .cmp(&right.fresh_forward_only_total)
            })
            .then_with(|| right.source_selected_count.cmp(&left.source_selected_count))
            .then_with(|| left.width.cmp(&right.width))
            .then_with(|| left.connector.cmp(&right.connector))
    });
    let retained_geometry_count = geometry_rows
        .iter()
        .filter(|row| row.geometry_status == "geometry-retained-across-gap-families")
        .count();
    let selected_geometry = geometry_rows
        .iter()
        .find(|row| row.geometry_status == "geometry-retained-across-gap-families")
        .cloned();
    let control_decision = if selected_geometry.is_some() {
        "pair-family-gap-cohort-geometry-retained-residue-profiler-next"
    } else {
        "pair-family-gap-cohort-geometry-not-retained-pivot-again"
    };
    let next_experiment_target = selected_geometry
        .as_ref()
        .map(|row| row.next_experiment_target.clone())
        .unwrap_or_else(|| {
            "select-new-family-level-replication-surface-after-gap20-22-24-geometry-no-shared-fresh-retention"
                .to_string()
        });

    Some(ConnectorWidth6PairFamilyGapCohortGeometryControl {
        selection_rule:
            "after-topn-family-surface-profile-finds-no-small-prime-separator;scan-top-10-frozen-connector motifs across new gap20-gap22-gap24 pair-family ladders and require shared fresh hit geometry before residue profiling"
                .to_string(),
        source_surface_id: "pair-family-gap-cohort-geometry-gap20-22-24".to_string(),
        top_n_per_family,
        pair_family_count: pair_families.len(),
        pair_families,
        source_motif_count: motif_rows.len(),
        fresh_motif_count: motif_rows.len(),
        fresh_survivor_motif_count: motif_rows
            .iter()
            .filter(|row| row.fresh_reverse_only_pair_count > 0)
            .count(),
        geometry_row_count: geometry_rows.len(),
        retained_geometry_count,
        selected_geometry,
        control_decision: control_decision.to_string(),
        next_experiment_target,
        motif_rows,
        geometry_rows,
    })
}

fn build_pair_family_gap_cohort_residue_profile(
    control: Option<&ConnectorWidth6PairFamilyGapCohortGeometryControl>,
) -> Option<ConnectorWidth6PairFamilyCohortResidueProfile> {
    let control = control?;
    let selected = control.selected_geometry.as_ref()?;
    if selected.geometry_status != "geometry-retained-across-gap-families" {
        return None;
    }

    let connector_value = selected.connector.parse::<u128>().ok()?;
    let mut rows = Vec::new();
    let mut fresh_survivor_branch_count = 0;
    for pair_family in &control.pair_families {
        let pair_cases = connector_pair_family_fresh_pair_cases(pair_family)?;
        let mut family_rows = Vec::new();
        for case in &pair_cases {
            if let Some(row) = build_connector_value_row(
                case,
                selected.width,
                connector_value,
                &format!("pair-family-gap-cohort-residue-profile-{pair_family}"),
            ) {
                family_rows.push(row);
            }
        }
        if family_rows
            .iter()
            .any(|row| row.contrast_class == "reverse-only-prime-hit")
        {
            fresh_survivor_branch_count += 1;
        }
        rows.extend(family_rows);
    }

    rows.sort_by(|left, right| {
        left.control_family
            .cmp(&right.control_family)
            .then_with(|| left.left.cmp(&right.left))
            .then_with(|| left.right.cmp(&right.right))
    });

    let moduli = vec![3_u32, 5, 7, 11, 13, 17, 19, 23, 29, 31];
    let reverse_only_rows = rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .collect::<Vec<_>>();
    let comparison_rows = rows
        .iter()
        .filter(|row| row.contrast_class != "reverse-only-prime-hit")
        .collect::<Vec<_>>();
    let mut residue_rows = moduli
        .iter()
        .map(|modulus| {
            let reverse_only_residues = reverse_only_rows
                .iter()
                .map(|row| (row.left % *modulus as u128) as u32)
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            let comparison_residues = comparison_rows
                .iter()
                .map(|row| (row.left % *modulus as u128) as u32)
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            let comparison_set = comparison_residues.iter().copied().collect::<BTreeSet<_>>();
            let shared_residues = reverse_only_residues
                .iter()
                .copied()
                .filter(|residue| comparison_set.contains(residue))
                .collect::<Vec<_>>();
            let separator_status = if reverse_only_residues.is_empty() {
                "no-reverse-only-residues"
            } else if shared_residues.is_empty() {
                "exact-residue-separator"
            } else {
                "overlapping-residue-classes"
            };

            ConnectorWidth6NonMod3CandidateResidueProfileRow {
                modulus: *modulus,
                reverse_only_pair_count: reverse_only_rows.len(),
                comparison_pair_count: comparison_rows.len(),
                reverse_only_residues,
                comparison_residues,
                shared_residues,
                separator_status: separator_status.to_string(),
            }
        })
        .collect::<Vec<_>>();
    residue_rows.sort_by(|left, right| left.modulus.cmp(&right.modulus));

    let exact_separator_count = residue_rows
        .iter()
        .filter(|row| row.separator_status == "exact-residue-separator")
        .count();
    let best_separator = residue_rows
        .iter()
        .filter(|row| row.separator_status == "exact-residue-separator")
        .min_by(|left, right| {
            left.reverse_only_residues
                .len()
                .cmp(&right.reverse_only_residues.len())
                .then_with(|| left.modulus.cmp(&right.modulus))
        })
        .cloned();
    let profile_decision = if best_separator.is_some() {
        "small-prime-gap-cohort-residue-separator-found-replicate-before-lean"
    } else {
        "no-small-prime-gap-cohort-residue-separator-found"
    };
    let next_experiment_target = best_separator
        .as_ref()
        .map(|separator| {
            format!(
                "replicate-gap-cohort-width{}-connector-{}-mod{}-residue-separator-before-lean",
                selected.width, selected.connector, separator.modulus
            )
        })
        .unwrap_or_else(|| {
            format!(
                "select-new-family-level-replication-surface-after-gap-cohort-{}-profile-no-small-prime-separator",
                selected.connector
            )
        });

    Some(ConnectorWidth6PairFamilyCohortResidueProfile {
        selection_rule:
            "profile-selected-gap20-gap22-gap24-cohort-geometry-by-small-prime-residue-before-lean"
                .to_string(),
        cohort_id: format!(
            "pair-family-gap-cohort-width{}-connector-{}",
            selected.width, selected.connector
        ),
        width: selected.width,
        connector: selected.connector.clone(),
        pair_families: control.pair_families.clone(),
        source_branch_ids: selected
            .source_pair_families
            .iter()
            .map(|family| {
                format!(
                    "pair-family-gap-cohort-geometry-{family}-width{}-connector-{}",
                    selected.width, selected.connector
                )
            })
            .collect(),
        branch_count: control.pair_families.len(),
        fresh_survivor_branch_count,
        moduli,
        row_count: rows.len(),
        reverse_only_pair_count: reverse_only_rows.len(),
        comparison_pair_count: comparison_rows.len(),
        profiled_modulus_count: residue_rows.len(),
        exact_separator_count,
        best_separator,
        profile_decision: profile_decision.to_string(),
        next_experiment_target,
        rows: residue_rows,
    })
}

fn build_pair_family_gap_cohort_residue_separator_replication(
    profile: &ConnectorWidth6PairFamilyCohortResidueProfile,
) -> Option<ConnectorWidth6PairFamilyCohortResidueSeparatorReplication> {
    let separator = profile.best_separator.as_ref()?;
    let connector_value = profile.connector.parse::<u128>().ok()?;
    let mut rows = Vec::new();
    let mut separator_pair_labels = Vec::new();

    for pair_family in &profile.pair_families {
        let pair_cases = connector_pair_family_separator_pair_cases(pair_family)?;
        for case in pair_cases {
            separator_pair_labels.push(case.name.to_string());
            if let Some(row) = build_connector_value_row(
                &case,
                profile.width,
                connector_value,
                &format!("pair-family-gap-cohort-residue-separator-replication-{pair_family}"),
            ) {
                rows.push(row);
            }
        }
    }

    rows.sort_by(|left, right| {
        left.control_family
            .cmp(&right.control_family)
            .then_with(|| left.left.cmp(&right.left))
            .then_with(|| left.right.cmp(&right.right))
    });
    separator_pair_labels.sort();
    separator_pair_labels.dedup();

    let reverse_only_rows = rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .collect::<Vec<_>>();
    let comparison_rows = rows
        .iter()
        .filter(|row| row.contrast_class != "reverse-only-prime-hit")
        .collect::<Vec<_>>();
    let reverse_only_residues = reverse_only_rows
        .iter()
        .map(|row| (row.left % separator.modulus as u128) as u32)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let comparison_residues = comparison_rows
        .iter()
        .map(|row| (row.left % separator.modulus as u128) as u32)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let source_set = separator
        .reverse_only_residues
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    let comparison_set = comparison_residues.iter().copied().collect::<BTreeSet<_>>();
    let reverse_set = reverse_only_residues
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    let shared_residues = reverse_only_residues
        .iter()
        .copied()
        .filter(|residue| comparison_set.contains(residue))
        .collect::<Vec<_>>();
    let retained_residue_count = reverse_only_residues
        .iter()
        .filter(|residue| source_set.contains(residue))
        .count();
    let split_residue_count = reverse_only_residues
        .iter()
        .filter(|residue| !source_set.contains(residue))
        .count();
    let collapsed_residue_count = separator
        .reverse_only_residues
        .iter()
        .filter(|residue| !reverse_set.contains(residue))
        .count();

    let source_retained_exactly = !reverse_only_residues.is_empty()
        && reverse_set == source_set
        && shared_residues.is_empty();
    let separator_status = if reverse_only_residues.is_empty() {
        "collapsed-no-reverse-only-on-gap-cohort-separator-ladders"
    } else if source_retained_exactly {
        "retained-source-residue-separator-on-gap-cohort-separator-ladders"
    } else if shared_residues.is_empty() {
        "split-exact-residue-separator-on-gap-cohort-separator-ladders"
    } else {
        "collapsed-overlapping-residue-classes-on-gap-cohort-separator-ladders"
    };
    let replication_decision = match separator_status {
        "retained-source-residue-separator-on-gap-cohort-separator-ladders" => {
            format!(
                "mod{}-gap-cohort-residue-separator-retained-lean-candidate",
                separator.modulus
            )
        }
        "split-exact-residue-separator-on-gap-cohort-separator-ladders" => {
            format!(
                "mod{}-gap-cohort-residue-separator-mutated-keep-empirical",
                separator.modulus
            )
        }
        _ => format!(
            "mod{}-gap-cohort-residue-separator-collapsed-keep-empirical",
            separator.modulus
        ),
    };
    let next_experiment_target = if separator_status
        == "retained-source-residue-separator-on-gap-cohort-separator-ladders"
    {
        format!(
            "lean-finite-classifier-candidate-gap-cohort-width{}-connector-{}-mod{}",
            profile.width, profile.connector, separator.modulus
        )
    } else {
        format!(
            "select-new-family-level-replication-surface-after-gap-cohort-{}-separator-collapse",
            profile.connector
        )
    };

    Some(ConnectorWidth6PairFamilyCohortResidueSeparatorReplication {
        selection_rule:
            "test-best-gap-cohort-residue-separator-on-gap20-gap22-gap24-separator-ladders-before-lean"
                .to_string(),
        cohort_id: profile.cohort_id.clone(),
        width: profile.width,
        connector: profile.connector.clone(),
        pair_families: profile.pair_families.clone(),
        source_branch_ids: profile.source_branch_ids.clone(),
        source_modulus: separator.modulus,
        source_reverse_only_residues: separator.reverse_only_residues.clone(),
        separator_family_count: profile.pair_families.len(),
        separator_pair_count: separator_pair_labels.len(),
        separator_pair_labels,
        row_count: rows.len(),
        reverse_only_pair_count: reverse_only_rows.len(),
        comparison_pair_count: comparison_rows.len(),
        reverse_only_residues,
        comparison_residues,
        shared_residues,
        retained_residue_count,
        split_residue_count,
        collapsed_residue_count,
        separator_status: separator_status.to_string(),
        replication_decision,
        next_experiment_target,
        rows,
    })
}

fn ratio_geometry_bias_direction(reverse_only: usize, forward_only: usize) -> String {
    if reverse_only > forward_only {
        "reverse".to_string()
    } else if forward_only > reverse_only {
        "forward".to_string()
    } else {
        "neutral".to_string()
    }
}

fn ratio_geometry_family_row_from_counts(
    stage: &str,
    pair_family: &str,
    source_rank: usize,
    width: u32,
    connector: &str,
    reverse_only_pair_count: usize,
    forward_only_pair_count: usize,
    both_hit_pair_count: usize,
    neither_hit_pair_count: usize,
) -> Option<ConnectorWidth6PairFamilyGapCohortRatioGeometryFamilyRow> {
    Some(ConnectorWidth6PairFamilyGapCohortRatioGeometryFamilyRow {
        stage: stage.to_string(),
        pair_family: pair_family.to_string(),
        pair_gap: pair_family_gap(pair_family)?,
        source_rank,
        width,
        connector: connector.to_string(),
        reverse_only_pair_count,
        forward_only_pair_count,
        both_hit_pair_count,
        neither_hit_pair_count,
        signed_hit_delta: reverse_only_pair_count as i32 - forward_only_pair_count as i32,
        bias_direction: ratio_geometry_bias_direction(
            reverse_only_pair_count,
            forward_only_pair_count,
        ),
    })
}

fn build_pair_family_gap_cohort_ratio_geometry_control(
    profile: Option<&ConnectorWidth6PairFamilyCohortResidueProfile>,
    geometry_control: Option<&ConnectorWidth6PairFamilyGapCohortGeometryControl>,
) -> Option<ConnectorWidth6PairFamilyGapCohortRatioGeometryControl> {
    let profile = profile?;
    if profile.profile_decision != "no-small-prime-gap-cohort-residue-separator-found" {
        return None;
    }
    let geometry_control = geometry_control?;

    let mut family_rows = Vec::new();
    for row in &geometry_control.motif_rows {
        family_rows.push(ratio_geometry_family_row_from_counts(
            "fresh",
            &row.pair_family,
            row.source_rank,
            row.width,
            &row.connector,
            row.fresh_reverse_only_pair_count,
            row.fresh_forward_only_pair_count,
            row.fresh_both_hit_pair_count,
            row.fresh_neither_hit_pair_count,
        )?);
    }

    let mut grouped: BTreeMap<
        (u32, String),
        Vec<&ConnectorWidth6PairFamilyGapCohortRatioGeometryFamilyRow>,
    > = BTreeMap::new();
    for row in &family_rows {
        grouped
            .entry((row.width, row.connector.clone()))
            .or_default()
            .push(row);
    }

    let mut geometry_rows = grouped
        .into_iter()
        .map(|((width, connector), rows)| {
            let source_pair_families = rows
                .iter()
                .map(|row| row.pair_family.clone())
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            let reverse_biased_family_count = rows
                .iter()
                .filter(|row| row.bias_direction == "reverse")
                .count();
            let forward_biased_family_count = rows
                .iter()
                .filter(|row| row.bias_direction == "forward")
                .count();
            let neutral_family_count = rows
                .iter()
                .filter(|row| row.bias_direction == "neutral")
                .count();
            let (retained_bias_direction, retained_bias_family_count) =
                if reverse_biased_family_count >= forward_biased_family_count {
                    ("reverse", reverse_biased_family_count)
                } else {
                    ("forward", forward_biased_family_count)
                };
            let fresh_reverse_only_total = rows
                .iter()
                .map(|row| row.reverse_only_pair_count)
                .sum();
            let fresh_forward_only_total = rows
                .iter()
                .map(|row| row.forward_only_pair_count)
                .sum();
            let fresh_both_hit_total = rows.iter().map(|row| row.both_hit_pair_count).sum();
            let fresh_neither_hit_total = rows.iter().map(|row| row.neither_hit_pair_count).sum();
            let signed_hit_delta_total = rows.iter().map(|row| row.signed_hit_delta).sum::<i32>();
            let absolute_hit_delta_total = signed_hit_delta_total.unsigned_abs() as usize;
            let ratio_geometry_status = if retained_bias_family_count >= 2 {
                "ratio-geometry-retained-across-gap-families"
            } else {
                "ratio-geometry-not-retained-across-gap-families"
            };
            let next_experiment_target =
                if ratio_geometry_status == "ratio-geometry-retained-across-gap-families" {
                    format!(
                        "replicate-gap-cohort-ratio-geometry-width{}-connector-{}-bias-{}-on-separator-ladders",
                        width, connector, retained_bias_direction
                    )
                } else {
                    format!(
                        "do-not-replicate-gap-cohort-ratio-geometry-width{}-connector-{}-without-shared-direction",
                        width, connector
                    )
                };

            ConnectorWidth6PairFamilyGapCohortRatioGeometryRow {
                width,
                connector,
                source_selected_count: source_pair_families.len(),
                source_pair_families,
                reverse_biased_family_count,
                forward_biased_family_count,
                neutral_family_count,
                retained_bias_direction: retained_bias_direction.to_string(),
                retained_bias_family_count,
                fresh_reverse_only_total,
                fresh_forward_only_total,
                fresh_both_hit_total,
                fresh_neither_hit_total,
                signed_hit_delta_total,
                absolute_hit_delta_total,
                ratio_geometry_status: ratio_geometry_status.to_string(),
                next_experiment_target,
            }
        })
        .collect::<Vec<_>>();

    geometry_rows.sort_by(|left, right| {
        right
            .retained_bias_family_count
            .cmp(&left.retained_bias_family_count)
            .then_with(|| {
                right
                    .absolute_hit_delta_total
                    .cmp(&left.absolute_hit_delta_total)
            })
            .then_with(|| right.source_selected_count.cmp(&left.source_selected_count))
            .then_with(|| left.width.cmp(&right.width))
            .then_with(|| left.connector.cmp(&right.connector))
    });
    let retained_geometry_count = geometry_rows
        .iter()
        .filter(|row| row.ratio_geometry_status == "ratio-geometry-retained-across-gap-families")
        .count();
    let selected_geometry = geometry_rows
        .iter()
        .find(|row| row.ratio_geometry_status == "ratio-geometry-retained-across-gap-families")
        .cloned();
    let control_decision = if selected_geometry.is_some() {
        "pair-family-gap-cohort-ratio-geometry-retained-replicate-next"
    } else {
        "pair-family-gap-cohort-ratio-geometry-not-retained-pivot-again"
    };
    let next_experiment_target = selected_geometry
        .as_ref()
        .map(|row| row.next_experiment_target.clone())
        .unwrap_or_else(|| {
            "select-new-family-level-replication-surface-after-gap-cohort-ratio-geometry-not-retained"
                .to_string()
        });

    Some(ConnectorWidth6PairFamilyGapCohortRatioGeometryControl {
        selection_rule:
            "after-gap-cohort-residue-profile-finds-no-small-prime-separator;compare shared forward/reverse hit-ratio geometry across gap20-gap22-gap24 fresh ladders"
                .to_string(),
        source_profile_id: profile.cohort_id.clone(),
        pair_family_count: geometry_control.pair_families.len(),
        pair_families: geometry_control.pair_families.clone(),
        family_row_count: family_rows.len(),
        geometry_row_count: geometry_rows.len(),
        retained_geometry_count,
        selected_geometry,
        control_decision: control_decision.to_string(),
        next_experiment_target,
        family_rows,
        geometry_rows,
    })
}

fn build_pair_family_gap_cohort_ratio_geometry_replication(
    control: &ConnectorWidth6PairFamilyGapCohortRatioGeometryControl,
) -> Option<ConnectorWidth6PairFamilyGapCohortRatioGeometryReplication> {
    let selected = control.selected_geometry.as_ref()?;
    let connector_value = selected.connector.parse::<u128>().ok()?;
    let mut family_rows = Vec::new();
    let mut separator_row_count = 0;

    for pair_family in &control.pair_families {
        let pair_cases = connector_pair_family_separator_pair_cases(pair_family)?;
        let mut reverse_only_pair_count = 0;
        let mut forward_only_pair_count = 0;
        let mut both_hit_pair_count = 0;
        let mut neither_hit_pair_count = 0;
        for case in &pair_cases {
            if let Some(row) = build_connector_value_row(
                case,
                selected.width,
                connector_value,
                &format!("pair-family-gap-cohort-ratio-geometry-separator-{pair_family}"),
            ) {
                separator_row_count += 1;
                match row.contrast_class.as_str() {
                    "reverse-only-prime-hit" => reverse_only_pair_count += 1,
                    "forward-only-prime-hit" => forward_only_pair_count += 1,
                    "both-prime-hit" => both_hit_pair_count += 1,
                    _ => neither_hit_pair_count += 1,
                }
            }
        }
        family_rows.push(ratio_geometry_family_row_from_counts(
            "separator",
            pair_family,
            0,
            selected.width,
            &selected.connector,
            reverse_only_pair_count,
            forward_only_pair_count,
            both_hit_pair_count,
            neither_hit_pair_count,
        )?);
    }

    let reverse_biased_family_count = family_rows
        .iter()
        .filter(|row| row.bias_direction == "reverse")
        .count();
    let forward_biased_family_count = family_rows
        .iter()
        .filter(|row| row.bias_direction == "forward")
        .count();
    let neutral_family_count = family_rows
        .iter()
        .filter(|row| row.bias_direction == "neutral")
        .count();
    let retained_direction_family_count = family_rows
        .iter()
        .filter(|row| row.bias_direction == selected.retained_bias_direction)
        .count();
    let split_direction = if selected.retained_bias_direction == "reverse" {
        "forward"
    } else {
        "reverse"
    };
    let split_direction_family_count = family_rows
        .iter()
        .filter(|row| row.bias_direction == split_direction)
        .count();
    let separator_reverse_only_total = family_rows
        .iter()
        .map(|row| row.reverse_only_pair_count)
        .sum();
    let separator_forward_only_total = family_rows
        .iter()
        .map(|row| row.forward_only_pair_count)
        .sum();
    let separator_signed_hit_delta_total = family_rows.iter().map(|row| row.signed_hit_delta).sum();
    let ratio_geometry_status = if retained_direction_family_count >= 2 {
        "retained-source-ratio-geometry-on-gap-cohort-separator-ladders"
    } else if split_direction_family_count >= 2 {
        "split-ratio-geometry-on-gap-cohort-separator-ladders"
    } else {
        "collapsed-ratio-geometry-on-gap-cohort-separator-ladders"
    };
    let replication_decision = match ratio_geometry_status {
        "retained-source-ratio-geometry-on-gap-cohort-separator-ladders" => {
            "gap-cohort-ratio-geometry-retained-expand-empirical-surface"
        }
        "split-ratio-geometry-on-gap-cohort-separator-ladders" => {
            "gap-cohort-ratio-geometry-split-keep-empirical"
        }
        _ => "gap-cohort-ratio-geometry-collapsed-keep-empirical",
    };
    let next_experiment_target = if ratio_geometry_status
        == "retained-source-ratio-geometry-on-gap-cohort-separator-ladders"
    {
        format!(
            "expand-gap-cohort-ratio-geometry-width{}-connector-{}-bias-{}-on-new-gap-ladders",
            selected.width, selected.connector, selected.retained_bias_direction
        )
    } else {
        format!(
            "select-new-family-level-replication-surface-after-gap-cohort-ratio-geometry-{}-collapse",
            selected.connector
        )
    };

    Some(ConnectorWidth6PairFamilyGapCohortRatioGeometryReplication {
        selection_rule:
            "test-retained-gap-cohort-ratio-geometry-on-gap20-gap22-gap24-separator-ladders-before-residue-or-lean-work"
                .to_string(),
        source_width: selected.width,
        source_connector: selected.connector.clone(),
        source_bias_direction: selected.retained_bias_direction.clone(),
        source_retained_bias_family_count: selected.retained_bias_family_count,
        pair_family_count: control.pair_families.len(),
        separator_row_count,
        reverse_biased_family_count,
        forward_biased_family_count,
        neutral_family_count,
        retained_direction_family_count,
        split_direction_family_count,
        separator_reverse_only_total,
        separator_forward_only_total,
        separator_signed_hit_delta_total,
        ratio_geometry_status: ratio_geometry_status.to_string(),
        replication_decision: replication_decision.to_string(),
        next_experiment_target,
        family_rows,
    })
}

fn ratio_geometry_expansion_ladders() -> Vec<(String, u32, u128, Vec<PairCase>)> {
    vec![
        (
            "prime-gap26".to_string(),
            26,
            240000,
            connector_gap26_generated_pair_cases(),
        ),
        (
            "prime-gap28".to_string(),
            28,
            253000,
            connector_gap28_generated_pair_cases(),
        ),
        (
            "prime-gap30".to_string(),
            30,
            266000,
            connector_gap30_generated_pair_cases(),
        ),
    ]
}

fn generated_gap_ladder_row(
    pair_family: &str,
    pair_gap: u32,
    lower_bound: u128,
    pair_cases: &[PairCase],
) -> Option<ConnectorWidth6GeneratedGapLadderRow> {
    let first = pair_cases.first()?;
    let last = pair_cases.last()?;
    Some(ConnectorWidth6GeneratedGapLadderRow {
        pair_family: pair_family.to_string(),
        pair_gap,
        lower_bound,
        pair_count: pair_cases.len(),
        source_pair_count: pair_cases.get(0..12)?.len(),
        fresh_pair_count: pair_cases.get(12..24)?.len(),
        separator_pair_count: pair_cases.get(24..36)?.len(),
        first_left: first.pair.left,
        first_right: first.pair.right,
        last_left: last.pair.left,
        last_right: last.pair.right,
    })
}

fn build_ratio_geometry_window_row(
    stage: &str,
    pair_family: &str,
    width: u32,
    connector_value: u128,
    connector: &str,
    pair_cases: &[PairCase],
) -> Option<ConnectorWidth6PairFamilyGapCohortRatioGeometryFamilyRow> {
    let mut reverse_only_pair_count = 0;
    let mut forward_only_pair_count = 0;
    let mut both_hit_pair_count = 0;
    let mut neither_hit_pair_count = 0;
    for case in pair_cases {
        if let Some(row) = build_connector_value_row(
            case,
            width,
            connector_value,
            &format!("pair-family-gap-cohort-ratio-geometry-expansion-{stage}-{pair_family}"),
        ) {
            match row.contrast_class.as_str() {
                "reverse-only-prime-hit" => reverse_only_pair_count += 1,
                "forward-only-prime-hit" => forward_only_pair_count += 1,
                "both-prime-hit" => both_hit_pair_count += 1,
                _ => neither_hit_pair_count += 1,
            }
        }
    }
    ratio_geometry_family_row_from_counts(
        stage,
        pair_family,
        0,
        width,
        connector,
        reverse_only_pair_count,
        forward_only_pair_count,
        both_hit_pair_count,
        neither_hit_pair_count,
    )
}

fn build_pair_family_gap_cohort_ratio_geometry_expansion(
    replication: Option<&ConnectorWidth6PairFamilyGapCohortRatioGeometryReplication>,
) -> Option<ConnectorWidth6PairFamilyGapCohortRatioGeometryExpansion> {
    let replication = replication?;
    if replication.replication_decision
        != "gap-cohort-ratio-geometry-retained-expand-empirical-surface"
    {
        return None;
    }
    let connector_value = replication.source_connector.parse::<u128>().ok()?;
    let ladders = ratio_geometry_expansion_ladders();
    let mut generated_ladders = Vec::new();
    let mut family_rows = Vec::new();

    for (pair_family, pair_gap, lower_bound, pair_cases) in &ladders {
        generated_ladders.push(generated_gap_ladder_row(
            pair_family,
            *pair_gap,
            *lower_bound,
            pair_cases,
        )?);
        for (stage, range) in [("source", 0..12), ("fresh", 12..24), ("separator", 24..36)] {
            family_rows.push(build_ratio_geometry_window_row(
                stage,
                pair_family,
                replication.source_width,
                connector_value,
                &replication.source_connector,
                pair_cases.get(range)?,
            )?);
        }
    }

    let reverse_biased_window_count = family_rows
        .iter()
        .filter(|row| row.bias_direction == "reverse")
        .count();
    let forward_biased_window_count = family_rows
        .iter()
        .filter(|row| row.bias_direction == "forward")
        .count();
    let neutral_window_count = family_rows
        .iter()
        .filter(|row| row.bias_direction == "neutral")
        .count();
    let retained_direction_window_count = family_rows
        .iter()
        .filter(|row| row.bias_direction == replication.source_bias_direction)
        .count();
    let split_direction = if replication.source_bias_direction == "reverse" {
        "forward"
    } else {
        "reverse"
    };
    let split_direction_window_count = family_rows
        .iter()
        .filter(|row| row.bias_direction == split_direction)
        .count();
    let window_count = family_rows.len();
    let expansion_status =
        if retained_direction_window_count >= 2 && split_direction_window_count == 0 {
            "retained-ratio-geometry-on-new-gap-ladders"
        } else if retained_direction_window_count >= 2
            && retained_direction_window_count >= split_direction_window_count
        {
            "mixed-retained-ratio-geometry-on-new-gap-ladders"
        } else if split_direction_window_count > retained_direction_window_count {
            "split-ratio-geometry-on-new-gap-ladders"
        } else {
            "collapsed-ratio-geometry-on-new-gap-ladders"
        };
    let expansion_decision = match expansion_status {
        "retained-ratio-geometry-on-new-gap-ladders" => {
            "gap-cohort-ratio-geometry-retained-test-correction-bounds-next"
        }
        "mixed-retained-ratio-geometry-on-new-gap-ladders" => {
            "gap-cohort-ratio-geometry-mixed-retained-test-correction-bounds-next"
        }
        "split-ratio-geometry-on-new-gap-ladders" => {
            "gap-cohort-ratio-geometry-split-keep-empirical"
        }
        _ => "gap-cohort-ratio-geometry-collapsed-record-falsification",
    };
    let next_experiment_target = if matches!(
        expansion_status,
        "retained-ratio-geometry-on-new-gap-ladders"
            | "mixed-retained-ratio-geometry-on-new-gap-ladders"
    ) {
        format!(
            "test-correction-bound-stability-gap-cohort-ratio-geometry-width{}-connector-{}",
            replication.source_width, replication.source_connector
        )
    } else {
        format!(
            "select-new-family-level-replication-surface-after-expanded-ratio-geometry-{}-collapse",
            replication.source_connector
        )
    };

    Some(ConnectorWidth6PairFamilyGapCohortRatioGeometryExpansion {
        selection_rule:
            "generate gap26-gap28-gap30 source/fresh/separator ladders and test retained 001139 ratio geometry before correction-bound normalization"
                .to_string(),
        source_width: replication.source_width,
        source_connector: replication.source_connector.clone(),
        source_bias_direction: replication.source_bias_direction.clone(),
        pair_family_count: ladders.len(),
        window_count,
        generated_pair_count: generated_ladders
            .iter()
            .map(|ladder| ladder.pair_count)
            .sum(),
        reverse_biased_window_count,
        forward_biased_window_count,
        neutral_window_count,
        retained_direction_window_count,
        split_direction_window_count,
        expansion_status: expansion_status.to_string(),
        expansion_decision: expansion_decision.to_string(),
        next_experiment_target,
        generated_ladders,
        family_rows,
    })
}

fn ratio_geometry_bias_direction_from_gap(value: f64) -> String {
    if value > 0.0 {
        "reverse".to_string()
    } else if value < 0.0 {
        "forward".to_string()
    } else {
        "neutral".to_string()
    }
}

fn corrected_observed_to_expected_ratios_for_pair(
    pair: ConcatenationSystem,
    width: u32,
    connector_value: u128,
    small_primes: &[u32],
) -> Option<(f64, f64)> {
    let forward_value = pair.forward(connector_value, width)?;
    let reverse_value = pair.reverse(connector_value, width)?;
    let forward_expected = corrected_expected_hit_for_value(forward_value, small_primes);
    let reverse_expected = corrected_expected_hit_for_value(reverse_value, small_primes);
    let forward_ratio = observed_to_corrected_ratio(is_prime_u128(forward_value), forward_expected);
    let reverse_ratio = observed_to_corrected_ratio(is_prime_u128(reverse_value), reverse_expected);
    Some((forward_ratio, reverse_ratio))
}

fn build_ratio_correction_bound_family_row(
    bound: u32,
    small_primes: &[u32],
    pair_family: &str,
    width: u32,
    connector_value: u128,
    pair_cases: &[PairCase],
) -> Option<ConnectorWidth6RatioCorrectionBoundFamilyRow> {
    let mut reverse_observed_to_corrected_ratio_sum = 0.0;
    let mut forward_observed_to_corrected_ratio_sum = 0.0;
    for case in pair_cases {
        let (forward_ratio, reverse_ratio) = corrected_observed_to_expected_ratios_for_pair(
            case.pair,
            width,
            connector_value,
            small_primes,
        )?;
        forward_observed_to_corrected_ratio_sum += forward_ratio;
        reverse_observed_to_corrected_ratio_sum += reverse_ratio;
    }
    let signed_observed_to_corrected_ratio_gap =
        reverse_observed_to_corrected_ratio_sum - forward_observed_to_corrected_ratio_sum;
    Some(ConnectorWidth6RatioCorrectionBoundFamilyRow {
        small_prime_bound: bound,
        pair_family: pair_family.to_string(),
        pair_gap: pair_family_gap(pair_family)?,
        row_count: pair_cases.len(),
        reverse_observed_to_corrected_ratio_sum,
        forward_observed_to_corrected_ratio_sum,
        signed_observed_to_corrected_ratio_gap,
        bias_direction: ratio_geometry_bias_direction_from_gap(
            signed_observed_to_corrected_ratio_gap,
        ),
    })
}

fn build_pair_family_gap_cohort_ratio_correction_bound_stability(
    expansion: Option<&ConnectorWidth6PairFamilyGapCohortRatioGeometryExpansion>,
) -> Option<ConnectorWidth6PairFamilyGapCohortRatioCorrectionBoundStability> {
    let expansion = expansion?;
    if !matches!(
        expansion.expansion_status.as_str(),
        "retained-ratio-geometry-on-new-gap-ladders"
            | "mixed-retained-ratio-geometry-on-new-gap-ladders"
    ) {
        return None;
    }
    let connector_value = expansion.source_connector.parse::<u128>().ok()?;
    let ladders = ratio_geometry_expansion_ladders();
    let mut bound_rows = Vec::new();
    let mut family_rows = Vec::new();

    for &bound in DEFAULT_SWEEP_BOUNDS {
        let small_primes = small_primes_up_to(bound);
        let mut bound_family_rows = Vec::new();
        for (pair_family, _pair_gap, _lower_bound, pair_cases) in &ladders {
            bound_family_rows.push(build_ratio_correction_bound_family_row(
                bound,
                &small_primes,
                pair_family,
                expansion.source_width,
                connector_value,
                pair_cases,
            )?);
        }
        let reverse_positive_family_count = bound_family_rows
            .iter()
            .filter(|row| row.bias_direction == "reverse")
            .count();
        let forward_positive_family_count = bound_family_rows
            .iter()
            .filter(|row| row.bias_direction == "forward")
            .count();
        let neutral_family_count = bound_family_rows
            .iter()
            .filter(|row| row.bias_direction == "neutral")
            .count();
        let aggregate_reverse_observed_to_corrected_ratio = bound_family_rows
            .iter()
            .map(|row| row.reverse_observed_to_corrected_ratio_sum)
            .sum();
        let aggregate_forward_observed_to_corrected_ratio = bound_family_rows
            .iter()
            .map(|row| row.forward_observed_to_corrected_ratio_sum)
            .sum();
        let aggregate_signed_observed_to_corrected_ratio_gap =
            aggregate_reverse_observed_to_corrected_ratio
                - aggregate_forward_observed_to_corrected_ratio;
        let stability_status = if aggregate_signed_observed_to_corrected_ratio_gap > 0.0
            && reverse_positive_family_count >= 2
        {
            "reverse-positive-correction-bound"
        } else {
            "not-reverse-positive-correction-bound"
        };
        bound_rows.push(ConnectorWidth6RatioCorrectionBoundRow {
            small_prime_bound: bound,
            small_primes,
            pair_family_count: bound_family_rows.len(),
            reverse_positive_family_count,
            forward_positive_family_count,
            neutral_family_count,
            aggregate_reverse_observed_to_corrected_ratio,
            aggregate_forward_observed_to_corrected_ratio,
            aggregate_signed_observed_to_corrected_ratio_gap,
            stability_status: stability_status.to_string(),
        });
        family_rows.extend(bound_family_rows);
    }

    let stable_bound_count = bound_rows
        .iter()
        .filter(|row| row.stability_status == "reverse-positive-correction-bound")
        .count();
    let unstable_bound_count = bound_rows.len() - stable_bound_count;
    let stability_status = if stable_bound_count == bound_rows.len() {
        "stable-reverse-correction-bound-geometry-across-default-bounds"
    } else if stable_bound_count > 0 {
        "mixed-correction-bound-geometry-across-default-bounds"
    } else {
        "collapsed-correction-bound-geometry-across-default-bounds"
    };
    let stability_decision = match stability_status {
        "stable-reverse-correction-bound-geometry-across-default-bounds" => {
            "correction-bound-stability-retained-expand-ratio-geometry-atlas-next"
        }
        "mixed-correction-bound-geometry-across-default-bounds" => {
            "correction-bound-stability-mixed-keep-empirical"
        }
        _ => "correction-bound-stability-collapsed-record-falsification",
    };
    let next_experiment_target = if stability_status
        == "stable-reverse-correction-bound-geometry-across-default-bounds"
    {
        "expand-ratio-geometry-001139-to-size-band-and-gap-band-controls".to_string()
    } else {
        "select-new-family-level-replication-surface-after-ratio-geometry-correction-bound-instability"
                .to_string()
    };

    Some(
        ConnectorWidth6PairFamilyGapCohortRatioCorrectionBoundStability {
            selection_rule:
                "normalize 001139 gap26-gap28-gap30 ratio geometry by small-prime correction bounds before theorem growth"
                    .to_string(),
            source_width: expansion.source_width,
            source_connector: expansion.source_connector.clone(),
            source_bias_direction: expansion.source_bias_direction.clone(),
            bounds: DEFAULT_SWEEP_BOUNDS.to_vec(),
            bound_count: bound_rows.len(),
            stable_bound_count,
            unstable_bound_count,
            pair_family_count: ladders.len(),
            row_count: family_rows.iter().map(|row| row.row_count).sum(),
            stability_status: stability_status.to_string(),
            stability_decision: stability_decision.to_string(),
            next_experiment_target,
            bound_rows,
            family_rows,
        },
    )
}

fn ratio_geometry_atlas_surfaces() -> Vec<(&'static str, Vec<&'static str>)> {
    vec![
        (
            "gap-band",
            vec!["prime-gap14", "prime-gap16", "prime-gap18"],
        ),
        (
            "size-band",
            vec![
                "prime-gap8-size40k",
                "prime-gap8-size80k",
                "prime-gap8-size120k",
            ],
        ),
    ]
}

fn connector_pair_family_all_window_pair_cases(pair_family: &str) -> Option<Vec<PairCase>> {
    let mut pair_cases = connector_pair_family_source_pair_cases(pair_family)?;
    pair_cases.extend(connector_pair_family_fresh_pair_cases(pair_family)?);
    pair_cases.extend(connector_pair_family_separator_pair_cases(pair_family)?);
    Some(pair_cases)
}

fn ratio_geometry_atlas_correction_bound_status(
    aggregate_signed_gap: f64,
    reverse_positive_family_count: usize,
    forward_positive_family_count: usize,
) -> &'static str {
    if aggregate_signed_gap.abs() <= 0.01
        && reverse_positive_family_count > 0
        && forward_positive_family_count > 0
    {
        "balanced-split-correction-bound"
    } else if aggregate_signed_gap > 0.0 && reverse_positive_family_count >= 2 {
        "stable-reverse-correction-bound"
    } else if aggregate_signed_gap > 0.0 && reverse_positive_family_count > 0 {
        "aggregate-positive-family-concentrated-correction-bound"
    } else {
        "split-or-forward-correction-bound"
    }
}

fn ratio_geometry_atlas_surface_correction_status(
    correction_rows: &[ConnectorWidth6RatioGeometryAtlasCorrectionBoundRow],
) -> String {
    let stable_bound_count = correction_rows
        .iter()
        .filter(|row| row.correction_bound_status == "stable-reverse-correction-bound")
        .count();
    let balanced_bound_count = correction_rows
        .iter()
        .filter(|row| row.correction_bound_status == "balanced-split-correction-bound")
        .count();
    let concentrated_bound_count = correction_rows
        .iter()
        .filter(|row| {
            row.correction_bound_status == "aggregate-positive-family-concentrated-correction-bound"
        })
        .count();

    if stable_bound_count == correction_rows.len() {
        "stable-reverse-correction-bound-geometry-across-default-bounds".to_string()
    } else if balanced_bound_count == correction_rows.len() {
        "balanced-split-correction-bound-geometry-across-default-bounds".to_string()
    } else if concentrated_bound_count == correction_rows.len() {
        "aggregate-positive-but-family-concentrated-across-default-bounds".to_string()
    } else {
        "mixed-or-collapsed-correction-bound-geometry-across-default-bounds".to_string()
    }
}

fn build_pair_family_gap_cohort_ratio_geometry_atlas(
    stability: Option<&ConnectorWidth6PairFamilyGapCohortRatioCorrectionBoundStability>,
) -> Option<ConnectorWidth6PairFamilyGapCohortRatioGeometryAtlas> {
    let stability = stability?;
    if stability.next_experiment_target
        != "expand-ratio-geometry-001139-to-size-band-and-gap-band-controls"
    {
        return None;
    }
    let connector_value = stability.source_connector.parse::<u128>().ok()?;
    let mut surface_rows = Vec::new();
    let mut family_rows = Vec::new();
    let mut correction_bound_rows = Vec::new();
    let surfaces = ratio_geometry_atlas_surfaces();

    for (surface_id, pair_families) in &surfaces {
        let mut surface_family_rows = Vec::new();
        for pair_family in pair_families {
            for (stage, pair_cases) in [
                (
                    "source",
                    connector_pair_family_source_pair_cases(pair_family)?,
                ),
                (
                    "fresh",
                    connector_pair_family_fresh_pair_cases(pair_family)?,
                ),
                (
                    "separator",
                    connector_pair_family_separator_pair_cases(pair_family)?,
                ),
            ] {
                let row = build_ratio_geometry_window_row(
                    stage,
                    pair_family,
                    stability.source_width,
                    connector_value,
                    &stability.source_connector,
                    &pair_cases,
                )?;
                surface_family_rows.push(row.clone());
                family_rows.push(row);
            }
        }

        let mut surface_correction_rows = Vec::new();
        for &bound in DEFAULT_SWEEP_BOUNDS {
            let small_primes = small_primes_up_to(bound);
            let mut bound_family_rows = Vec::new();
            for pair_family in pair_families {
                let pair_cases = connector_pair_family_all_window_pair_cases(pair_family)?;
                bound_family_rows.push(build_ratio_correction_bound_family_row(
                    bound,
                    &small_primes,
                    pair_family,
                    stability.source_width,
                    connector_value,
                    &pair_cases,
                )?);
            }
            let reverse_positive_family_count = bound_family_rows
                .iter()
                .filter(|row| row.bias_direction == "reverse")
                .count();
            let forward_positive_family_count = bound_family_rows
                .iter()
                .filter(|row| row.bias_direction == "forward")
                .count();
            let neutral_family_count = bound_family_rows
                .iter()
                .filter(|row| row.bias_direction == "neutral")
                .count();
            let aggregate_reverse_observed_to_corrected_ratio = bound_family_rows
                .iter()
                .map(|row| row.reverse_observed_to_corrected_ratio_sum)
                .sum();
            let aggregate_forward_observed_to_corrected_ratio = bound_family_rows
                .iter()
                .map(|row| row.forward_observed_to_corrected_ratio_sum)
                .sum();
            let aggregate_signed_observed_to_corrected_ratio_gap =
                aggregate_reverse_observed_to_corrected_ratio
                    - aggregate_forward_observed_to_corrected_ratio;
            let correction_bound_status = ratio_geometry_atlas_correction_bound_status(
                aggregate_signed_observed_to_corrected_ratio_gap,
                reverse_positive_family_count,
                forward_positive_family_count,
            )
            .to_string();
            let correction_row = ConnectorWidth6RatioGeometryAtlasCorrectionBoundRow {
                surface_id: (*surface_id).to_string(),
                small_prime_bound: bound,
                small_primes,
                pair_family_count: bound_family_rows.len(),
                reverse_positive_family_count,
                forward_positive_family_count,
                neutral_family_count,
                aggregate_reverse_observed_to_corrected_ratio,
                aggregate_forward_observed_to_corrected_ratio,
                aggregate_signed_observed_to_corrected_ratio_gap,
                correction_bound_status,
            };
            surface_correction_rows.push(correction_row.clone());
            correction_bound_rows.push(correction_row);
        }

        let reverse_biased_window_count = surface_family_rows
            .iter()
            .filter(|row| row.bias_direction == "reverse")
            .count();
        let forward_biased_window_count = surface_family_rows
            .iter()
            .filter(|row| row.bias_direction == "forward")
            .count();
        let neutral_window_count = surface_family_rows
            .iter()
            .filter(|row| row.bias_direction == "neutral")
            .count();
        let retained_direction_window_count = surface_family_rows
            .iter()
            .filter(|row| row.bias_direction == stability.source_bias_direction)
            .count();
        let split_direction_window_count = surface_family_rows
            .iter()
            .filter(|row| {
                row.bias_direction != stability.source_bias_direction
                    && row.bias_direction != "neutral"
            })
            .count();
        let raw_geometry_status =
            match reverse_biased_window_count.cmp(&forward_biased_window_count) {
                std::cmp::Ordering::Greater => "raw-reverse-window-biased",
                std::cmp::Ordering::Less => "raw-forward-window-biased",
                std::cmp::Ordering::Equal => "raw-balanced-window-biased",
            };
        let correction_bound_status =
            ratio_geometry_atlas_surface_correction_status(&surface_correction_rows);
        let stable_bound_count = surface_correction_rows
            .iter()
            .filter(|row| row.correction_bound_status == "stable-reverse-correction-bound")
            .count();
        let balanced_bound_count = surface_correction_rows
            .iter()
            .filter(|row| row.correction_bound_status == "balanced-split-correction-bound")
            .count();
        let concentrated_bound_count = surface_correction_rows
            .iter()
            .filter(|row| {
                row.correction_bound_status
                    == "aggregate-positive-family-concentrated-correction-bound"
            })
            .count();
        let split_bound_count = surface_correction_rows.len()
            - stable_bound_count
            - balanced_bound_count
            - concentrated_bound_count;

        surface_rows.push(ConnectorWidth6RatioGeometryAtlasSurfaceRow {
            surface_id: (*surface_id).to_string(),
            pair_families: pair_families
                .iter()
                .map(|family| (*family).to_string())
                .collect(),
            pair_family_count: pair_families.len(),
            window_count: surface_family_rows.len(),
            reverse_biased_window_count,
            forward_biased_window_count,
            neutral_window_count,
            retained_direction_window_count,
            split_direction_window_count,
            raw_geometry_status: raw_geometry_status.to_string(),
            correction_bound_status,
            stable_bound_count,
            balanced_bound_count,
            concentrated_bound_count,
            split_bound_count,
        });
    }

    let gap_band_status = surface_rows
        .iter()
        .find(|row| row.surface_id == "gap-band")
        .map(|row| row.correction_bound_status.clone())
        .unwrap_or_else(|| "missing-gap-band".to_string());
    let size_band_status = surface_rows
        .iter()
        .find(|row| row.surface_id == "size-band")
        .map(|row| row.correction_bound_status.clone())
        .unwrap_or_else(|| "missing-size-band".to_string());
    let atlas_status = if gap_band_status
        == "stable-reverse-correction-bound-geometry-across-default-bounds"
        && size_band_status == "stable-reverse-correction-bound-geometry-across-default-bounds"
    {
        "ratio-geometry-001139-stable-across-size-and-gap-bands"
    } else {
        "ratio-geometry-001139-not-stable-across-size-and-gap-bands"
    };
    let atlas_decision = if atlas_status == "ratio-geometry-001139-stable-across-size-and-gap-bands"
    {
        "ratio-geometry-001139-retained-as-family-level-invariant-profile-before-lean"
    } else {
        "ratio-geometry-001139-collapsed-as-family-level-invariant-record-falsification"
    };
    let next_experiment_target =
        if atlas_status == "ratio-geometry-001139-stable-across-size-and-gap-bands" {
            "search-exact-arithmetic-invariant-for-ratio-geometry-001139-size-gap-atlas"
        } else {
            "select-new-cohort-invariant-after-ratio-geometry-001139-size-gap-atlas-collapse"
        };

    Some(ConnectorWidth6PairFamilyGapCohortRatioGeometryAtlas {
        selection_rule:
            "project correction-stable 001139 ratio geometry across gap-band and size-band controls before theorem growth"
                .to_string(),
        source_width: stability.source_width,
        source_connector: stability.source_connector.clone(),
        source_bias_direction: stability.source_bias_direction.clone(),
        surface_count: surface_rows.len(),
        surfaces: surfaces
            .iter()
            .map(|(surface_id, _)| (*surface_id).to_string())
            .collect(),
        bounds: DEFAULT_SWEEP_BOUNDS.to_vec(),
        bound_count: DEFAULT_SWEEP_BOUNDS.len(),
        family_row_count: family_rows.len(),
        correction_bound_row_count: correction_bound_rows.len(),
        gap_band_status,
        size_band_status,
        atlas_status: atlas_status.to_string(),
        atlas_decision: atlas_decision.to_string(),
        next_experiment_target: next_experiment_target.to_string(),
        surface_rows,
        family_rows,
        correction_bound_rows,
    })
}

fn ratio_geometry_picker_correction_bound_status(
    aggregate_signed_gap: f64,
    reverse_positive_family_count: usize,
    forward_positive_family_count: usize,
) -> &'static str {
    if aggregate_signed_gap > 0.0 && reverse_positive_family_count >= 2 {
        "stable-reverse-correction-bound"
    } else if aggregate_signed_gap < 0.0 && forward_positive_family_count >= 2 {
        "stable-forward-correction-bound"
    } else if aggregate_signed_gap.abs() <= 0.01
        && reverse_positive_family_count > 0
        && forward_positive_family_count > 0
    {
        "balanced-split-correction-bound"
    } else if aggregate_signed_gap > 0.0 && reverse_positive_family_count > 0 {
        "aggregate-reverse-positive-family-concentrated-correction-bound"
    } else if aggregate_signed_gap < 0.0 && forward_positive_family_count > 0 {
        "aggregate-forward-positive-family-concentrated-correction-bound"
    } else {
        "split-or-neutral-correction-bound"
    }
}

fn ratio_geometry_picker_surface_status_and_direction(
    correction_rows: &[ConnectorWidth6RatioGeometryPickerCorrectionBoundRow],
) -> (String, String) {
    let reverse_stable_bound_count = correction_rows
        .iter()
        .filter(|row| row.correction_bound_status == "stable-reverse-correction-bound")
        .count();
    let forward_stable_bound_count = correction_rows
        .iter()
        .filter(|row| row.correction_bound_status == "stable-forward-correction-bound")
        .count();
    let balanced_bound_count = correction_rows
        .iter()
        .filter(|row| row.correction_bound_status == "balanced-split-correction-bound")
        .count();
    let concentrated_bound_count = correction_rows
        .iter()
        .filter(|row| row.correction_bound_status.contains("family-concentrated"))
        .count();

    if reverse_stable_bound_count == correction_rows.len() {
        (
            "stable-reverse-correction-bound-geometry-across-default-bounds".to_string(),
            "reverse".to_string(),
        )
    } else if forward_stable_bound_count == correction_rows.len() {
        (
            "stable-forward-correction-bound-geometry-across-default-bounds".to_string(),
            "forward".to_string(),
        )
    } else if balanced_bound_count == correction_rows.len() {
        (
            "balanced-split-correction-bound-geometry-across-default-bounds".to_string(),
            "none".to_string(),
        )
    } else if concentrated_bound_count == correction_rows.len() {
        (
            "family-concentrated-correction-bound-geometry-across-default-bounds".to_string(),
            "none".to_string(),
        )
    } else {
        (
            "mixed-or-collapsed-correction-bound-geometry-across-default-bounds".to_string(),
            "none".to_string(),
        )
    }
}

fn build_ratio_geometry_picker_surface_rows(
    width: u32,
    connector_value: u128,
    connector: &str,
    surface_id: &str,
    pair_families: &[&str],
) -> Option<(
    ConnectorWidth6RatioGeometryPickerSurfaceRow,
    Vec<ConnectorWidth6PairFamilyGapCohortRatioGeometryFamilyRow>,
    Vec<ConnectorWidth6RatioGeometryPickerCorrectionBoundRow>,
)> {
    let mut family_rows = Vec::new();
    for pair_family in pair_families {
        for (stage, pair_cases) in [
            (
                "source",
                connector_pair_family_source_pair_cases(pair_family)?,
            ),
            (
                "fresh",
                connector_pair_family_fresh_pair_cases(pair_family)?,
            ),
            (
                "separator",
                connector_pair_family_separator_pair_cases(pair_family)?,
            ),
        ] {
            family_rows.push(build_ratio_geometry_window_row(
                stage,
                pair_family,
                width,
                connector_value,
                connector,
                &pair_cases,
            )?);
        }
    }

    let mut correction_bound_rows = Vec::new();
    for &bound in DEFAULT_SWEEP_BOUNDS {
        let small_primes = small_primes_up_to(bound);
        let mut bound_family_rows = Vec::new();
        for pair_family in pair_families {
            let pair_cases = connector_pair_family_all_window_pair_cases(pair_family)?;
            bound_family_rows.push(build_ratio_correction_bound_family_row(
                bound,
                &small_primes,
                pair_family,
                width,
                connector_value,
                &pair_cases,
            )?);
        }
        let reverse_positive_family_count = bound_family_rows
            .iter()
            .filter(|row| row.bias_direction == "reverse")
            .count();
        let forward_positive_family_count = bound_family_rows
            .iter()
            .filter(|row| row.bias_direction == "forward")
            .count();
        let neutral_family_count = bound_family_rows
            .iter()
            .filter(|row| row.bias_direction == "neutral")
            .count();
        let aggregate_reverse_observed_to_corrected_ratio = bound_family_rows
            .iter()
            .map(|row| row.reverse_observed_to_corrected_ratio_sum)
            .sum();
        let aggregate_forward_observed_to_corrected_ratio = bound_family_rows
            .iter()
            .map(|row| row.forward_observed_to_corrected_ratio_sum)
            .sum();
        let aggregate_signed_observed_to_corrected_ratio_gap =
            aggregate_reverse_observed_to_corrected_ratio
                - aggregate_forward_observed_to_corrected_ratio;
        correction_bound_rows.push(ConnectorWidth6RatioGeometryPickerCorrectionBoundRow {
            width,
            connector: connector.to_string(),
            surface_id: surface_id.to_string(),
            small_prime_bound: bound,
            small_primes,
            pair_family_count: bound_family_rows.len(),
            reverse_positive_family_count,
            forward_positive_family_count,
            neutral_family_count,
            aggregate_reverse_observed_to_corrected_ratio,
            aggregate_forward_observed_to_corrected_ratio,
            aggregate_signed_observed_to_corrected_ratio_gap,
            correction_bound_status: ratio_geometry_picker_correction_bound_status(
                aggregate_signed_observed_to_corrected_ratio_gap,
                reverse_positive_family_count,
                forward_positive_family_count,
            )
            .to_string(),
        });
    }

    let reverse_biased_window_count = family_rows
        .iter()
        .filter(|row| row.bias_direction == "reverse")
        .count();
    let forward_biased_window_count = family_rows
        .iter()
        .filter(|row| row.bias_direction == "forward")
        .count();
    let neutral_window_count = family_rows
        .iter()
        .filter(|row| row.bias_direction == "neutral")
        .count();
    let reverse_stable_bound_count = correction_bound_rows
        .iter()
        .filter(|row| row.correction_bound_status == "stable-reverse-correction-bound")
        .count();
    let forward_stable_bound_count = correction_bound_rows
        .iter()
        .filter(|row| row.correction_bound_status == "stable-forward-correction-bound")
        .count();
    let balanced_bound_count = correction_bound_rows
        .iter()
        .filter(|row| row.correction_bound_status == "balanced-split-correction-bound")
        .count();
    let concentrated_bound_count = correction_bound_rows
        .iter()
        .filter(|row| row.correction_bound_status.contains("family-concentrated"))
        .count();
    let split_bound_count = correction_bound_rows.len()
        - reverse_stable_bound_count
        - forward_stable_bound_count
        - balanced_bound_count
        - concentrated_bound_count;
    let (correction_bound_status, stable_direction) =
        ratio_geometry_picker_surface_status_and_direction(&correction_bound_rows);

    Some((
        ConnectorWidth6RatioGeometryPickerSurfaceRow {
            width,
            connector: connector.to_string(),
            surface_id: surface_id.to_string(),
            pair_families: pair_families
                .iter()
                .map(|family| (*family).to_string())
                .collect(),
            pair_family_count: pair_families.len(),
            window_count: family_rows.len(),
            reverse_biased_window_count,
            forward_biased_window_count,
            neutral_window_count,
            reverse_stable_bound_count,
            forward_stable_bound_count,
            balanced_bound_count,
            concentrated_bound_count,
            split_bound_count,
            stable_direction,
            correction_bound_status,
        },
        family_rows,
        correction_bound_rows,
    ))
}

fn ratio_geometry_picker_direction_priority(direction: &str) -> usize {
    match direction {
        "reverse" => 0,
        "forward" => 1,
        _ => 2,
    }
}

fn build_pair_family_gap_cohort_ratio_geometry_picker(
    atlas: Option<&ConnectorWidth6PairFamilyGapCohortRatioGeometryAtlas>,
) -> Option<ConnectorWidth6PairFamilyGapCohortRatioGeometryPicker> {
    let atlas = atlas?;
    if atlas.next_experiment_target
        != "select-new-cohort-invariant-after-ratio-geometry-001139-size-gap-atlas-collapse"
    {
        return None;
    }

    let surfaces = ratio_geometry_atlas_surfaces();
    let mut candidate_rows = Vec::new();
    let mut surface_rows = Vec::new();
    let mut family_rows = Vec::new();
    let mut correction_bound_rows = Vec::new();

    for (width, connector_value) in pair_family_gap_portfolio_connector_values() {
        let connector = format!("{connector_value:0width$}", width = width as usize);
        let mut candidate_surface_rows = Vec::new();
        let mut candidate_correction_rows = Vec::new();
        for (surface_id, pair_families) in &surfaces {
            let (surface_row, surface_family_rows, surface_correction_rows) =
                build_ratio_geometry_picker_surface_rows(
                    width,
                    connector_value,
                    &connector,
                    surface_id,
                    pair_families,
                )?;
            candidate_surface_rows.push(surface_row.clone());
            surface_rows.push(surface_row);
            family_rows.extend(surface_family_rows);
            candidate_correction_rows.extend(surface_correction_rows.clone());
            correction_bound_rows.extend(surface_correction_rows);
        }

        let gap_surface = candidate_surface_rows
            .iter()
            .find(|row| row.surface_id == "gap-band")?;
        let size_surface = candidate_surface_rows
            .iter()
            .find(|row| row.surface_id == "size-band")?;
        let stable_surface_count = candidate_surface_rows
            .iter()
            .filter(|row| row.stable_direction == "reverse" || row.stable_direction == "forward")
            .count();
        let stable_bound_count = candidate_surface_rows
            .iter()
            .map(|row| row.reverse_stable_bound_count + row.forward_stable_bound_count)
            .sum();
        let shared_stable_direction = if gap_surface.stable_direction
            == size_surface.stable_direction
            && (gap_surface.stable_direction == "reverse"
                || gap_surface.stable_direction == "forward")
        {
            gap_surface.stable_direction.clone()
        } else {
            "none".to_string()
        };
        let candidate_status =
            if shared_stable_direction == "reverse" || shared_stable_direction == "forward" {
                "stable-family-level-ratio-geometry"
            } else if stable_surface_count > 0
                || candidate_surface_rows
                    .iter()
                    .any(|row| row.balanced_bound_count > 0 || row.concentrated_bound_count > 0)
            {
                "surface-split-or-concentrated"
            } else {
                "no-family-level-ratio-geometry"
            };
        let absolute_aggregate_corrected_ratio_gap = candidate_correction_rows
            .iter()
            .map(|row| row.aggregate_signed_observed_to_corrected_ratio_gap.abs())
            .sum();
        let next_experiment_target = if candidate_status == "stable-family-level-ratio-geometry" {
            format!(
                "residue-profile-cohort-invariant-width{width}-connector-{connector}-direction-{shared_stable_direction}"
            )
        } else {
            format!(
                "do-not-promote-frozen-portfolio-width{width}-connector-{connector}-ratio-geometry-without-shared-stable-direction"
            )
        };
        candidate_rows.push(ConnectorWidth6RatioGeometryPickerCandidateRow {
            candidate_rank: 0,
            width,
            connector,
            stable_surface_count,
            stable_bound_count,
            shared_stable_direction,
            gap_band_status: gap_surface.correction_bound_status.clone(),
            gap_band_stable_direction: gap_surface.stable_direction.clone(),
            size_band_status: size_surface.correction_bound_status.clone(),
            size_band_stable_direction: size_surface.stable_direction.clone(),
            absolute_aggregate_corrected_ratio_gap,
            candidate_status: candidate_status.to_string(),
            next_experiment_target,
        });
    }

    candidate_rows.sort_by(|left, right| {
        let left_stable = left.candidate_status == "stable-family-level-ratio-geometry";
        let right_stable = right.candidate_status == "stable-family-level-ratio-geometry";
        right_stable
            .cmp(&left_stable)
            .then_with(|| {
                ratio_geometry_picker_direction_priority(&left.shared_stable_direction).cmp(
                    &ratio_geometry_picker_direction_priority(&right.shared_stable_direction),
                )
            })
            .then_with(|| right.stable_surface_count.cmp(&left.stable_surface_count))
            .then_with(|| right.stable_bound_count.cmp(&left.stable_bound_count))
            .then_with(|| {
                right
                    .absolute_aggregate_corrected_ratio_gap
                    .partial_cmp(&left.absolute_aggregate_corrected_ratio_gap)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
            .then_with(|| left.width.cmp(&right.width))
            .then_with(|| left.connector.cmp(&right.connector))
    });
    for (index, row) in candidate_rows.iter_mut().enumerate() {
        row.candidate_rank = index + 1;
    }

    let stable_candidate_count = candidate_rows
        .iter()
        .filter(|row| row.candidate_status == "stable-family-level-ratio-geometry")
        .count();
    let selected_candidate = candidate_rows
        .iter()
        .find(|row| row.candidate_status == "stable-family-level-ratio-geometry")
        .cloned();
    let picker_decision = if selected_candidate.is_some() {
        "frozen-portfolio-cohort-invariant-picker-selected-stable-ratio-geometry"
    } else {
        "frozen-portfolio-cohort-invariant-picker-found-no-shared-stable-ratio-geometry"
    };
    let next_experiment_target = selected_candidate
        .as_ref()
        .map(|row| row.next_experiment_target.clone())
        .unwrap_or_else(|| {
            "select-new-cohort-invariant-surface-after-frozen-portfolio-ratio-picker-collapse"
                .to_string()
        });

    Some(ConnectorWidth6PairFamilyGapCohortRatioGeometryPicker {
        selection_rule:
            "scan frozen retired-head connector portfolio for direction-agnostic correction-stable family-level ratio geometry across gap-band and size-band surfaces"
                .to_string(),
        candidate_count: candidate_rows.len(),
        surface_count: surfaces.len(),
        surfaces: surfaces
            .iter()
            .map(|(surface_id, _)| (*surface_id).to_string())
            .collect(),
        bounds: DEFAULT_SWEEP_BOUNDS.to_vec(),
        bound_count: DEFAULT_SWEEP_BOUNDS.len(),
        stable_candidate_count,
        selected_candidate,
        picker_decision: picker_decision.to_string(),
        next_experiment_target,
        candidate_rows,
        surface_rows,
        family_rows,
        correction_bound_rows,
    })
}

fn cohort_invariant_target_contrast_class(direction: &str) -> Option<&'static str> {
    match direction {
        "reverse" => Some("reverse-only-prime-hit"),
        "forward" => Some("forward-only-prime-hit"),
        _ => None,
    }
}

fn build_cohort_invariant_surface_rows(
    surface_id: &str,
    pair_families: &[&str],
    width: u32,
    connector_value: u128,
) -> Option<Vec<ConnectorWidth6MultiDigitMotifRow>> {
    let mut rows = Vec::new();
    for pair_family in pair_families {
        for pair_cases in [
            connector_pair_family_source_pair_cases(pair_family)?,
            connector_pair_family_fresh_pair_cases(pair_family)?,
            connector_pair_family_separator_pair_cases(pair_family)?,
        ] {
            for case in &pair_cases {
                if let Some(row) = build_connector_value_row(
                    case,
                    width,
                    connector_value,
                    &format!("cohort-invariant-residue-profile-{surface_id}-{pair_family}"),
                ) {
                    rows.push(row);
                }
            }
        }
    }
    rows.sort_by(|left, right| {
        left.control_family
            .cmp(&right.control_family)
            .then_with(|| left.left.cmp(&right.left))
            .then_with(|| left.right.cmp(&right.right))
    });
    Some(rows)
}

fn cohort_invariant_residue_row(
    surface_id: &str,
    modulus: u32,
    target_rows: &[&ConnectorWidth6MultiDigitMotifRow],
    comparison_rows: &[&ConnectorWidth6MultiDigitMotifRow],
) -> ConnectorWidth6CohortInvariantResidueProfileRow {
    let target_residues = target_rows
        .iter()
        .map(|row| (row.left % modulus as u128) as u32)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let comparison_residues = comparison_rows
        .iter()
        .map(|row| (row.left % modulus as u128) as u32)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let comparison_set = comparison_residues.iter().copied().collect::<BTreeSet<_>>();
    let shared_residues = target_residues
        .iter()
        .copied()
        .filter(|residue| comparison_set.contains(residue))
        .collect::<Vec<_>>();
    let separator_status = if target_residues.is_empty() {
        "no-target-direction-residues"
    } else if shared_residues.is_empty() {
        "exact-residue-separator"
    } else {
        "overlapping-residue-classes"
    };

    ConnectorWidth6CohortInvariantResidueProfileRow {
        surface_id: surface_id.to_string(),
        modulus,
        target_pair_count: target_rows.len(),
        comparison_pair_count: comparison_rows.len(),
        target_residues,
        comparison_residues,
        shared_residues,
        separator_status: separator_status.to_string(),
    }
}

fn build_cohort_invariant_residue_profile_for_candidate(
    selected: &ConnectorWidth6RatioGeometryPickerCandidateRow,
    selection_rule: &str,
) -> Option<ConnectorWidth6CohortInvariantResidueProfile> {
    if selected.candidate_status != "stable-family-level-ratio-geometry" {
        return None;
    }
    let target_contrast_class =
        cohort_invariant_target_contrast_class(&selected.shared_stable_direction)?;
    let connector_value = selected.connector.parse::<u128>().ok()?;
    let moduli = vec![3_u32, 5, 7, 11, 13, 17, 19, 23, 29, 31];
    let surfaces = ratio_geometry_atlas_surfaces();
    let mut surface_rows = Vec::new();
    let mut residue_rows = Vec::new();
    let mut pair_families = BTreeSet::new();
    let mut total_row_count = 0;
    let mut total_target_pair_count = 0;
    let mut total_comparison_pair_count = 0;

    for (surface_id, surface_pair_families) in &surfaces {
        for pair_family in surface_pair_families {
            pair_families.insert((*pair_family).to_string());
        }
        let rows = build_cohort_invariant_surface_rows(
            surface_id,
            surface_pair_families,
            selected.width,
            connector_value,
        )?;
        let target_rows = rows
            .iter()
            .filter(|row| row.contrast_class == target_contrast_class)
            .collect::<Vec<_>>();
        let comparison_rows = rows
            .iter()
            .filter(|row| row.contrast_class != target_contrast_class)
            .collect::<Vec<_>>();
        total_row_count += rows.len();
        total_target_pair_count += target_rows.len();
        total_comparison_pair_count += comparison_rows.len();

        let mut surface_residue_rows = moduli
            .iter()
            .map(|modulus| {
                cohort_invariant_residue_row(surface_id, *modulus, &target_rows, &comparison_rows)
            })
            .collect::<Vec<_>>();
        surface_residue_rows.sort_by(|left, right| left.modulus.cmp(&right.modulus));
        let exact_separator_count = surface_residue_rows
            .iter()
            .filter(|row| row.separator_status == "exact-residue-separator")
            .count();
        let best_surface_separator = surface_residue_rows
            .iter()
            .filter(|row| row.separator_status == "exact-residue-separator")
            .min_by(|left, right| {
                left.target_residues
                    .len()
                    .cmp(&right.target_residues.len())
                    .then_with(|| left.modulus.cmp(&right.modulus))
            });
        let surface_status = if best_surface_separator.is_some() {
            "surface-has-small-prime-exact-separator"
        } else {
            "surface-has-no-small-prime-exact-separator"
        };
        surface_rows.push(ConnectorWidth6CohortInvariantResidueSurfaceRow {
            surface_id: (*surface_id).to_string(),
            pair_families: surface_pair_families
                .iter()
                .map(|family| (*family).to_string())
                .collect(),
            row_count: rows.len(),
            target_pair_count: target_rows.len(),
            comparison_pair_count: comparison_rows.len(),
            exact_separator_count,
            best_modulus: best_surface_separator.map(|row| row.modulus),
            best_target_residues: best_surface_separator
                .map(|row| row.target_residues.clone())
                .unwrap_or_default(),
            surface_status: surface_status.to_string(),
        });
        residue_rows.extend(surface_residue_rows);
    }

    let mut coherent_separators = Vec::new();
    for &modulus in &moduli {
        let rows_for_modulus = residue_rows
            .iter()
            .filter(|row| row.modulus == modulus)
            .collect::<Vec<_>>();
        if rows_for_modulus.len() != surfaces.len() {
            continue;
        }
        let first_target_residues = rows_for_modulus[0].target_residues.clone();
        let coherent = !first_target_residues.is_empty()
            && rows_for_modulus
                .iter()
                .all(|row| row.separator_status == "exact-residue-separator")
            && rows_for_modulus
                .iter()
                .all(|row| row.target_residues == first_target_residues);
        if coherent {
            coherent_separators.push(ConnectorWidth6CohortInvariantResidueSeparator {
                modulus,
                target_residues: first_target_residues,
                surface_count: surfaces.len(),
                exact_surface_count: rows_for_modulus.len(),
                target_pair_count: rows_for_modulus
                    .iter()
                    .map(|row| row.target_pair_count)
                    .sum(),
                comparison_pair_count: rows_for_modulus
                    .iter()
                    .map(|row| row.comparison_pair_count)
                    .sum(),
                separator_status: "coherent-exact-residue-separator-across-gap-size-surfaces"
                    .to_string(),
            });
        }
    }
    coherent_separators.sort_by(|left, right| {
        left.target_residues
            .len()
            .cmp(&right.target_residues.len())
            .then_with(|| left.modulus.cmp(&right.modulus))
    });
    let best_coherent_separator = coherent_separators.first().cloned();
    let exact_separator_count = residue_rows
        .iter()
        .filter(|row| row.separator_status == "exact-residue-separator")
        .count();
    let coherent_separator_count = coherent_separators.len();
    let profile_status = if best_coherent_separator.is_some() {
        "coherent-small-prime-residue-separator-retained-across-gap-size-surfaces"
    } else if exact_separator_count > 0 {
        "small-prime-residue-separators-not-coherent-across-gap-size-surfaces"
    } else {
        "no-small-prime-cohort-invariant-residue-separator"
    };
    let profile_decision = match profile_status {
        "coherent-small-prime-residue-separator-retained-across-gap-size-surfaces" => {
            "cohort-invariant-residue-separator-retained-theorem-candidate"
        }
        "small-prime-residue-separators-not-coherent-across-gap-size-surfaces" => {
            "cohort-invariant-residue-separator-not-coherent-record-falsification"
        }
        _ => "cohort-invariant-residue-profile-no-small-prime-separator-record-falsification",
    };
    let next_experiment_target = best_coherent_separator
        .as_ref()
        .map(|separator| {
            format!(
                "lean-finite-classifier-candidate-cohort-invariant-width{}-connector-{}-direction-{}-mod{}",
                selected.width,
                selected.connector,
                selected.shared_stable_direction,
                separator.modulus
            )
        })
        .unwrap_or_else(|| {
            format!(
                "select-new-cohort-invariant-after-{}-residue-profile-no-coherent-separator",
                selected.connector
            )
        });

    Some(ConnectorWidth6CohortInvariantResidueProfile {
        selection_rule: selection_rule.to_string(),
        source_width: selected.width,
        source_connector: selected.connector.clone(),
        source_direction: selected.shared_stable_direction.clone(),
        surfaces: surfaces
            .iter()
            .map(|(surface_id, _)| (*surface_id).to_string())
            .collect(),
        surface_count: surfaces.len(),
        pair_families: pair_families.into_iter().collect(),
        moduli,
        row_count: total_row_count,
        target_pair_count: total_target_pair_count,
        comparison_pair_count: total_comparison_pair_count,
        profiled_modulus_count: residue_rows.len(),
        exact_separator_count,
        coherent_separator_count,
        best_coherent_separator,
        profile_status: profile_status.to_string(),
        profile_decision: profile_decision.to_string(),
        next_experiment_target,
        surface_rows,
        residue_rows,
    })
}

