fn build_cohort_invariant_next_picker_from_profiles(
    picker: &ConnectorWidth6PairFamilyGapCohortRatioGeometryPicker,
    residue_profiles: &[&ConnectorWidth6CohortInvariantResidueProfile],
    selected_decision: &str,
    empty_decision: &str,
    empty_target: &str,
    selection_rule: &str,
) -> Option<ConnectorWidth6CohortInvariantNextPicker> {
    if residue_profiles.is_empty()
        || residue_profiles.iter().any(|profile| {
            profile.best_coherent_separator.is_some()
                || !profile
                    .next_experiment_target
                    .starts_with("select-new-cohort-invariant-after-")
        })
    {
        return None;
    }

    let excluded_profile_rows = residue_profiles
        .iter()
        .map(|profile| ConnectorWidth6CohortInvariantExcludedProfileRow {
            width: profile.source_width,
            connector: profile.source_connector.clone(),
            direction: profile.source_direction.clone(),
            profile_status: profile.profile_status.clone(),
            profile_decision: profile.profile_decision.clone(),
            next_experiment_target: profile.next_experiment_target.clone(),
        })
        .collect::<Vec<_>>();
    let excluded_keys = excluded_profile_rows
        .iter()
        .map(|row| (row.width, row.connector.clone(), row.direction.clone()))
        .collect::<BTreeSet<_>>();

    let mut candidate_rows = picker
        .candidate_rows
        .iter()
        .filter(|row| {
            !excluded_keys.contains(&(
                row.width,
                row.connector.clone(),
                row.shared_stable_direction.clone(),
            ))
        })
        .cloned()
        .collect::<Vec<_>>();
    for (index, row) in candidate_rows.iter_mut().enumerate() {
        row.candidate_rank = index + 1;
    }
    let stable_candidate_count = candidate_rows
        .iter()
        .filter(|row| row.candidate_status == "stable-family-level-ratio-geometry")
        .count();
    let selected_candidate = candidate_rows
        .iter()
        .find(|row| row.candidate_status == "stable-family-level-ratio-geometry")
        .cloned();
    let picker_decision = if selected_candidate.is_some() {
        selected_decision
    } else {
        empty_decision
    };
    let next_experiment_target = selected_candidate
        .as_ref()
        .map(|row| row.next_experiment_target.clone())
        .unwrap_or_else(|| empty_target.to_string());

    Some(ConnectorWidth6CohortInvariantNextPicker {
        selection_rule: selection_rule.to_string(),
        excluded_profile_count: excluded_profile_rows.len(),
        excluded_profile_rows,
        candidate_count: candidate_rows.len(),
        stable_candidate_count,
        selected_candidate,
        picker_decision: picker_decision.to_string(),
        next_experiment_target,
        candidate_rows,
    })
}

fn build_pair_family_gap_cohort_ratio_geometry_next_picker(
    picker: Option<&ConnectorWidth6PairFamilyGapCohortRatioGeometryPicker>,
    residue_profile: Option<&ConnectorWidth6CohortInvariantResidueProfile>,
) -> Option<ConnectorWidth6CohortInvariantNextPicker> {
    build_cohort_invariant_next_picker_from_profiles(
        picker?,
        &[residue_profile?],
        "cohort-invariant-next-picker-selected-unprofiled-stable-ratio-geometry",
        "cohort-invariant-next-picker-found-no-unprofiled-stable-ratio-geometry",
        "select-new-cohort-invariant-surface-after-profiled-stable-candidate-exhaustion",
        "exclude cohort invariants already residue-profiled without coherent separators, then select the next correction-stable family-level ratio geometry row",
    )
}

fn build_pair_family_gap_cohort_ratio_geometry_post_two_null_picker(
    picker: Option<&ConnectorWidth6PairFamilyGapCohortRatioGeometryPicker>,
    first_profile: Option<&ConnectorWidth6CohortInvariantResidueProfile>,
    second_profile: Option<&ConnectorWidth6CohortInvariantResidueProfile>,
) -> Option<ConnectorWidth6CohortInvariantNextPicker> {
    build_cohort_invariant_next_picker_from_profiles(
        picker?,
        &[first_profile?, second_profile?],
        "cohort-invariant-post-two-null-picker-selected-unprofiled-stable-ratio-geometry",
        "cohort-invariant-post-two-null-picker-found-no-unprofiled-stable-ratio-geometry",
        "select-new-cohort-invariant-surface-after-two-profiled-stable-candidate-nulls",
        "exclude both profiled cohort-invariant residue nulls, then select the next correction-stable family-level ratio geometry row",
    )
}

fn build_pair_family_gap_cohort_ratio_geometry_three_null_conclusion(
    picker: Option<&ConnectorWidth6PairFamilyGapCohortRatioGeometryPicker>,
    profiles: &[Option<&ConnectorWidth6CohortInvariantResidueProfile>],
) -> Option<ConnectorWidth6CohortInvariantThreeNullConclusion> {
    let picker = picker?;
    let profiles = profiles
        .iter()
        .copied()
        .collect::<Option<Vec<&ConnectorWidth6CohortInvariantResidueProfile>>>()?;
    if profiles.len() != 3
        || profiles.iter().any(|profile| {
            profile.source_direction != "reverse"
                || profile.best_coherent_separator.is_some()
                || profile.profile_status != "no-small-prime-cohort-invariant-residue-separator"
                || !profile
                    .next_experiment_target
                    .starts_with("select-new-cohort-invariant-after-")
        })
    {
        return None;
    }

    let collapsed_profile_rows = profiles
        .iter()
        .map(|profile| ConnectorWidth6CohortInvariantExcludedProfileRow {
            width: profile.source_width,
            connector: profile.source_connector.clone(),
            direction: profile.source_direction.clone(),
            profile_status: profile.profile_status.clone(),
            profile_decision: profile.profile_decision.clone(),
            next_experiment_target: profile.next_experiment_target.clone(),
        })
        .collect::<Vec<_>>();
    let collapsed_keys = collapsed_profile_rows
        .iter()
        .map(|row| (row.width, row.connector.clone(), row.direction.clone()))
        .collect::<BTreeSet<_>>();
    let mut forward_candidate_rows = picker
        .candidate_rows
        .iter()
        .filter(|row| {
            row.candidate_status == "stable-family-level-ratio-geometry"
                && row.shared_stable_direction == "forward"
                && !collapsed_keys.contains(&(
                    row.width,
                    row.connector.clone(),
                    row.shared_stable_direction.clone(),
                ))
        })
        .cloned()
        .collect::<Vec<_>>();
    for (index, row) in forward_candidate_rows.iter_mut().enumerate() {
        row.candidate_rank = index + 1;
    }
    let selected_forward_candidate = forward_candidate_rows.first().cloned();
    let next_experiment_target = selected_forward_candidate
        .as_ref()
        .map(|row| row.next_experiment_target.clone())
        .unwrap_or_else(|| {
            "select-new-cohort-invariant-surface-after-reverse-three-null-and-no-forward-stable-candidates"
                .to_string()
        });

    Some(ConnectorWidth6CohortInvariantThreeNullConclusion {
        selection_rule:
            "after three reverse stable-ratio cohort invariants fail the coherent small-prime residue gate, collapse the reverse residue route and pivot to remaining forward stable candidates"
                .to_string(),
        collapsed_direction: "reverse".to_string(),
        collapsed_profile_count: collapsed_profile_rows.len(),
        collapsed_profile_rows,
        conclusion_status:
            "reverse-stable-ratio-cohort-residue-route-collapsed-under-small-prime-exact-mask-rule"
                .to_string(),
        conclusion_decision:
            "pivot-to-forward-stable-ratio-cohort-candidates-after-three-reverse-residue-nulls"
                .to_string(),
        forward_candidate_count: forward_candidate_rows.len(),
        selected_forward_candidate,
        next_experiment_target,
        forward_candidate_rows,
    })
}

fn build_pair_family_gap_cohort_ratio_geometry_forward_null_conclusion(
    three_null_conclusion: Option<&ConnectorWidth6CohortInvariantThreeNullConclusion>,
    forward_profile: Option<&ConnectorWidth6CohortInvariantResidueProfile>,
) -> Option<ConnectorWidth6CohortInvariantForwardNullConclusion> {
    let three_null_conclusion = three_null_conclusion?;
    let forward_profile = forward_profile?;
    if forward_profile.source_direction != "forward"
        || forward_profile.best_coherent_separator.is_some()
        || !forward_profile
            .next_experiment_target
            .starts_with("select-new-cohort-invariant-after-")
    {
        return None;
    }

    let collapsed_profile_rows = vec![ConnectorWidth6CohortInvariantExcludedProfileRow {
        width: forward_profile.source_width,
        connector: forward_profile.source_connector.clone(),
        direction: forward_profile.source_direction.clone(),
        profile_status: forward_profile.profile_status.clone(),
        profile_decision: forward_profile.profile_decision.clone(),
        next_experiment_target: forward_profile.next_experiment_target.clone(),
    }];
    let collapsed_key = (
        forward_profile.source_width,
        forward_profile.source_connector.clone(),
        forward_profile.source_direction.clone(),
    );
    let mut remaining_stable_candidate_rows = three_null_conclusion
        .forward_candidate_rows
        .iter()
        .filter(|row| {
            (
                row.width,
                row.connector.clone(),
                row.shared_stable_direction.clone(),
            ) != collapsed_key
        })
        .cloned()
        .collect::<Vec<_>>();
    for (index, row) in remaining_stable_candidate_rows.iter_mut().enumerate() {
        row.candidate_rank = index + 1;
    }

    Some(ConnectorWidth6CohortInvariantForwardNullConclusion {
        selection_rule:
            "after the selected forward stable-ratio cohort invariant also fails the coherent small-prime residue gate, collapse the forward residue route instead of continuing row-by-row"
                .to_string(),
        collapsed_direction: "forward".to_string(),
        collapsed_profile_count: collapsed_profile_rows.len(),
        collapsed_profile_rows,
        conclusion_status:
            "forward-stable-ratio-cohort-residue-route-collapsed-under-small-prime-exact-mask-rule"
                .to_string(),
        conclusion_decision:
            "pivot-to-new-cohort-invariant-surface-after-forward-residue-null".to_string(),
        remaining_stable_candidate_count: remaining_stable_candidate_rows.len(),
        next_experiment_target:
            "select-new-cohort-invariant-surface-after-forward-route-small-prime-exact-mask-null"
                .to_string(),
        remaining_stable_candidate_rows,
    })
}

fn build_window_consensus_surface_row(
    width: u32,
    connector: &str,
    surface_id: &str,
    pair_families: &[&str],
    family_rows: &[ConnectorWidth6PairFamilyGapCohortRatioGeometryFamilyRow],
) -> Option<ConnectorWidth6WindowConsensusSurfaceRow> {
    let pair_family_set = pair_families.iter().copied().collect::<BTreeSet<_>>();
    let rows = family_rows
        .iter()
        .filter(|row| {
            row.width == width
                && row.connector == connector
                && pair_family_set.contains(row.pair_family.as_str())
        })
        .collect::<Vec<_>>();
    if rows.is_empty() {
        return None;
    }

    let reverse_biased_window_count = rows
        .iter()
        .filter(|row| row.bias_direction == "reverse")
        .count();
    let forward_biased_window_count = rows
        .iter()
        .filter(|row| row.bias_direction == "forward")
        .count();
    let neutral_window_count = rows
        .iter()
        .filter(|row| row.bias_direction == "neutral")
        .count();
    let (consensus_direction, consensus_window_count, opposite_window_count) =
        match reverse_biased_window_count.cmp(&forward_biased_window_count) {
            std::cmp::Ordering::Greater => (
                "reverse",
                reverse_biased_window_count,
                forward_biased_window_count,
            ),
            std::cmp::Ordering::Less => (
                "forward",
                forward_biased_window_count,
                reverse_biased_window_count,
            ),
            std::cmp::Ordering::Equal => ("none", 0, 0),
        };
    let source_consensus_window_count = rows
        .iter()
        .filter(|row| row.stage == "source" && row.bias_direction == consensus_direction)
        .count();
    let fresh_consensus_window_count = rows
        .iter()
        .filter(|row| row.stage == "fresh" && row.bias_direction == consensus_direction)
        .count();
    let separator_consensus_window_count = rows
        .iter()
        .filter(|row| row.stage == "separator" && row.bias_direction == consensus_direction)
        .count();
    let majority_threshold = rows.len() / 2 + 1;
    let surface_status = if consensus_direction != "none"
        && consensus_window_count >= majority_threshold
        && source_consensus_window_count > 0
        && fresh_consensus_window_count > 0
        && separator_consensus_window_count > 0
    {
        format!("{consensus_direction}-stage-complete-window-consensus")
    } else if consensus_direction != "none" && consensus_window_count >= majority_threshold {
        format!("{consensus_direction}-window-majority-with-stage-gap")
    } else if neutral_window_count == rows.len() {
        "neutral-window-consensus".to_string()
    } else {
        "split-window-consensus".to_string()
    };

    Some(ConnectorWidth6WindowConsensusSurfaceRow {
        width,
        connector: connector.to_string(),
        surface_id: surface_id.to_string(),
        pair_families: pair_families
            .iter()
            .map(|family| (*family).to_string())
            .collect(),
        window_count: rows.len(),
        reverse_biased_window_count,
        forward_biased_window_count,
        neutral_window_count,
        consensus_direction: consensus_direction.to_string(),
        consensus_window_count,
        opposite_window_count,
        source_consensus_window_count,
        fresh_consensus_window_count,
        separator_consensus_window_count,
        surface_status,
    })
}

fn build_pair_family_gap_cohort_window_consensus_surface(
    forward_null_conclusion: Option<&ConnectorWidth6CohortInvariantForwardNullConclusion>,
    picker: Option<&ConnectorWidth6PairFamilyGapCohortRatioGeometryPicker>,
) -> Option<ConnectorWidth6PairFamilyGapCohortWindowConsensusSurface> {
    let forward_null_conclusion = forward_null_conclusion?;
    let picker = picker?;
    if forward_null_conclusion.next_experiment_target
        != "select-new-cohort-invariant-surface-after-forward-route-small-prime-exact-mask-null"
    {
        return None;
    }

    let surfaces = ratio_geometry_atlas_surfaces();
    let mut surface_rows = Vec::new();
    let mut candidate_rows = Vec::new();
    for candidate in &picker.candidate_rows {
        let mut candidate_surface_rows = Vec::new();
        for (surface_id, pair_families) in &surfaces {
            let surface_row = build_window_consensus_surface_row(
                candidate.width,
                &candidate.connector,
                surface_id,
                pair_families,
                &picker.family_rows,
            )?;
            candidate_surface_rows.push(surface_row.clone());
            surface_rows.push(surface_row);
        }

        let consensus_surface_rows = candidate_surface_rows
            .iter()
            .filter(|row| {
                row.surface_status
                    .ends_with("stage-complete-window-consensus")
            })
            .collect::<Vec<_>>();
        let shared_consensus_direction = if consensus_surface_rows.len() == surfaces.len() {
            let first_direction = &consensus_surface_rows[0].consensus_direction;
            if first_direction != "none"
                && consensus_surface_rows
                    .iter()
                    .all(|row| row.consensus_direction == *first_direction)
            {
                first_direction.clone()
            } else {
                "none".to_string()
            }
        } else {
            "none".to_string()
        };
        let consensus_surface_count = consensus_surface_rows.len();
        let consensus_window_count = candidate_surface_rows
            .iter()
            .map(|row| {
                if shared_consensus_direction != "none" {
                    row.consensus_window_count
                } else {
                    0
                }
            })
            .sum();
        let opposite_window_count = candidate_surface_rows
            .iter()
            .map(|row| {
                if shared_consensus_direction != "none" {
                    row.opposite_window_count
                } else {
                    0
                }
            })
            .sum();
        let neutral_window_count = candidate_surface_rows
            .iter()
            .map(|row| row.neutral_window_count)
            .sum();
        let source_consensus_window_count = candidate_surface_rows
            .iter()
            .map(|row| {
                if row.consensus_direction == shared_consensus_direction {
                    row.source_consensus_window_count
                } else {
                    0
                }
            })
            .sum();
        let fresh_consensus_window_count = candidate_surface_rows
            .iter()
            .map(|row| {
                if row.consensus_direction == shared_consensus_direction {
                    row.fresh_consensus_window_count
                } else {
                    0
                }
            })
            .sum();
        let separator_consensus_window_count = candidate_surface_rows
            .iter()
            .map(|row| {
                if row.consensus_direction == shared_consensus_direction {
                    row.separator_consensus_window_count
                } else {
                    0
                }
            })
            .sum();
        let absolute_hit_delta_total = picker
            .family_rows
            .iter()
            .filter(|row| row.width == candidate.width && row.connector == candidate.connector)
            .map(|row| row.signed_hit_delta.unsigned_abs() as usize)
            .sum();
        let candidate_status =
            if shared_consensus_direction == "reverse" || shared_consensus_direction == "forward" {
                "shared-stage-complete-window-consensus"
            } else if consensus_surface_count > 0 {
                "partial-window-consensus"
            } else {
                "no-window-consensus"
            };
        let next_experiment_target = if candidate_status == "shared-stage-complete-window-consensus"
        {
            format!(
                "stress-test-window-consensus-cohort-invariant-width{}-connector-{}-direction-{}",
                candidate.width, candidate.connector, shared_consensus_direction
            )
        } else {
            format!(
                "do-not-promote-window-consensus-width{}-connector-{}-without-shared-stage-complete-consensus",
                candidate.width, candidate.connector
            )
        };

        candidate_rows.push(ConnectorWidth6WindowConsensusCandidateRow {
            candidate_rank: 0,
            width: candidate.width,
            connector: candidate.connector.clone(),
            shared_consensus_direction,
            consensus_surface_count,
            consensus_window_count,
            opposite_window_count,
            neutral_window_count,
            source_consensus_window_count,
            fresh_consensus_window_count,
            separator_consensus_window_count,
            absolute_hit_delta_total,
            candidate_status: candidate_status.to_string(),
            next_experiment_target,
        });
    }

    candidate_rows.sort_by(|left, right| {
        let left_status_rank =
            usize::from(left.candidate_status != "shared-stage-complete-window-consensus");
        let right_status_rank =
            usize::from(right.candidate_status != "shared-stage-complete-window-consensus");
        left_status_rank
            .cmp(&right_status_rank)
            .then_with(|| {
                right
                    .consensus_surface_count
                    .cmp(&left.consensus_surface_count)
            })
            .then_with(|| {
                right
                    .consensus_window_count
                    .cmp(&left.consensus_window_count)
            })
            .then_with(|| left.opposite_window_count.cmp(&right.opposite_window_count))
            .then_with(|| {
                right
                    .absolute_hit_delta_total
                    .cmp(&left.absolute_hit_delta_total)
            })
            .then_with(|| left.width.cmp(&right.width))
            .then_with(|| left.connector.cmp(&right.connector))
    });
    for (index, row) in candidate_rows.iter_mut().enumerate() {
        row.candidate_rank = index + 1;
    }
    let selected_candidate = candidate_rows
        .iter()
        .find(|row| row.candidate_status == "shared-stage-complete-window-consensus")
        .cloned();
    let (surface_decision, next_experiment_target) = if let Some(selected) = &selected_candidate {
        (
            "window-consensus-surface-selected-shared-stage-complete-invariant",
            selected.next_experiment_target.clone(),
        )
    } else {
        (
            "window-consensus-surface-found-no-shared-stage-complete-invariant",
            "select-new-cohort-invariant-surface-after-window-consensus-null".to_string(),
        )
    };

    Some(ConnectorWidth6PairFamilyGapCohortWindowConsensusSurface {
        selection_rule:
            "after reverse and forward small-prime exact-mask routes collapse, scan the frozen portfolio for shared source/fresh/separator window-consensus geometry across gap-band and size-band surfaces"
                .to_string(),
        source_route_status: forward_null_conclusion.conclusion_status.clone(),
        candidate_count: candidate_rows.len(),
        surface_count: surfaces.len(),
        surfaces: surfaces
            .iter()
            .map(|(surface_id, _)| (*surface_id).to_string())
            .collect(),
        window_count: surface_rows.iter().map(|row| row.window_count).sum(),
        selected_candidate,
        surface_decision: surface_decision.to_string(),
        next_experiment_target,
        candidate_rows,
        surface_rows,
    })
}

fn build_window_consensus_stress_family_rows(
    pair_family: &str,
    width: u32,
    connector_value: u128,
    connector: &str,
    source_pairs: Vec<PairCase>,
    fresh_pairs: Vec<PairCase>,
    separator_pairs: Vec<PairCase>,
) -> Option<Vec<ConnectorWidth6PairFamilyGapCohortRatioGeometryFamilyRow>> {
    let mut rows = Vec::new();
    for (stage, pair_cases) in [
        ("source", source_pairs),
        ("fresh", fresh_pairs),
        ("separator", separator_pairs),
    ] {
        rows.push(build_ratio_geometry_window_row(
            stage,
            pair_family,
            width,
            connector_value,
            connector,
            &pair_cases,
        )?);
    }
    Some(rows)
}

fn build_pair_family_gap_cohort_window_consensus_stress(
    surface: Option<&ConnectorWidth6PairFamilyGapCohortWindowConsensusSurface>,
) -> Option<ConnectorWidth6PairFamilyGapCohortWindowConsensusStress> {
    let surface = surface?;
    if surface.next_experiment_target
        != "stress-test-window-consensus-cohort-invariant-width6-connector-003727-direction-reverse"
    {
        return None;
    }
    let selected = surface.selected_candidate.as_ref()?;
    let connector_value = selected.connector.parse::<u128>().ok()?;
    let (size160_source, size160_fresh, size160_separator) =
        connector_gap8_size160k_generated_pair_cases();
    let (size200_source, size200_fresh, size200_separator) =
        connector_gap8_size200k_generated_pair_cases();
    let (size240_source, size240_fresh, size240_separator) =
        connector_gap8_size240k_generated_pair_cases();
    let stress_surfaces = vec![
        (
            "heldout-gap-band",
            vec![
                (
                    "prime-gap20",
                    connector_gap20_source_pair_cases(),
                    connector_gap20_fresh_pair_cases(),
                    connector_gap20_separator_pair_cases(),
                ),
                (
                    "prime-gap22",
                    connector_gap22_source_pair_cases(),
                    connector_gap22_fresh_pair_cases(),
                    connector_gap22_separator_pair_cases(),
                ),
                (
                    "prime-gap24",
                    connector_gap24_source_pair_cases(),
                    connector_gap24_fresh_pair_cases(),
                    connector_gap24_separator_pair_cases(),
                ),
            ],
        ),
        (
            "generated-gap8-size-band",
            vec![
                (
                    "prime-gap8-size160k",
                    size160_source,
                    size160_fresh,
                    size160_separator,
                ),
                (
                    "prime-gap8-size200k",
                    size200_source,
                    size200_fresh,
                    size200_separator,
                ),
                (
                    "prime-gap8-size240k",
                    size240_source,
                    size240_fresh,
                    size240_separator,
                ),
            ],
        ),
    ];

    let mut surface_rows = Vec::new();
    let mut family_rows = Vec::new();
    let mut surfaces = Vec::new();
    let mut pair_families = BTreeSet::new();
    for (surface_id, families) in stress_surfaces {
        surfaces.push(surface_id.to_string());
        let pair_family_names = families
            .iter()
            .map(|(pair_family, _, _, _)| *pair_family)
            .collect::<Vec<_>>();
        for (pair_family, source_pairs, fresh_pairs, separator_pairs) in families {
            pair_families.insert(pair_family.to_string());
            family_rows.extend(build_window_consensus_stress_family_rows(
                pair_family,
                selected.width,
                connector_value,
                &selected.connector,
                source_pairs,
                fresh_pairs,
                separator_pairs,
            )?);
        }
        surface_rows.push(build_window_consensus_surface_row(
            selected.width,
            &selected.connector,
            surface_id,
            &pair_family_names,
            &family_rows,
        )?);
    }

    let retained_surface_count = surface_rows
        .iter()
        .filter(|row| {
            row.consensus_direction == selected.shared_consensus_direction
                && row
                    .surface_status
                    .ends_with("stage-complete-window-consensus")
        })
        .count();
    let split_surface_count = surface_rows
        .iter()
        .filter(|row| {
            row.consensus_direction != selected.shared_consensus_direction
                && row.consensus_direction != "none"
        })
        .count();
    let collapsed_surface_count = surface_rows.len() - retained_surface_count - split_surface_count;
    let stress_status = if retained_surface_count == surface_rows.len() {
        "window-consensus-retained-on-heldout-gap-size-surfaces"
    } else if retained_surface_count > 0 {
        "window-consensus-split-on-heldout-gap-size-surfaces"
    } else {
        "window-consensus-collapsed-on-heldout-gap-size-surfaces"
    };
    let (stress_decision, next_experiment_target) = match stress_status {
        "window-consensus-retained-on-heldout-gap-size-surfaces" => (
            "window-consensus-heldout-stress-retained-expand-before-residue-profile",
            format!(
                "expand-window-consensus-{}-to-additional-gap-size-controls-before-residue-profile",
                selected.connector
            ),
        ),
        "window-consensus-split-on-heldout-gap-size-surfaces" => (
            "window-consensus-heldout-stress-split-record-falsification",
            "select-new-cohort-invariant-surface-after-window-consensus-heldout-split".to_string(),
        ),
        _ => (
            "window-consensus-heldout-stress-collapsed-record-falsification",
            "select-new-cohort-invariant-surface-after-window-consensus-heldout-collapse"
                .to_string(),
        ),
    };

    Some(ConnectorWidth6PairFamilyGapCohortWindowConsensusStress {
        selection_rule:
            "stress-test selected window-consensus cohort invariant on held-out gap20/22/24 and generated gap8 size160k/200k/240k source/fresh/separator windows before residue profiling"
                .to_string(),
        source_width: selected.width,
        source_connector: selected.connector.clone(),
        source_direction: selected.shared_consensus_direction.clone(),
        source_target: surface.next_experiment_target.clone(),
        surface_count: surface_rows.len(),
        surfaces,
        pair_family_count: pair_families.len(),
        window_count: family_rows.len(),
        retained_surface_count,
        split_surface_count,
        collapsed_surface_count,
        stress_status: stress_status.to_string(),
        stress_decision: stress_decision.to_string(),
        next_experiment_target,
        surface_rows,
        family_rows,
    })
}

