fn build_sign_persistence_surface_row(
    width: u32,
    connector: &str,
    surface_id: &str,
    pair_families: &[&str],
    family_rows: &[ConnectorWidth6PairFamilyGapCohortRatioGeometryFamilyRow],
) -> Option<ConnectorWidth6SignPersistenceSurfaceRow> {
    let pair_family_set = pair_families.iter().copied().collect::<BTreeSet<_>>();
    let rows = family_rows
        .iter()
        .filter(|row| {
            row.width == width
                && row.connector == connector
                && pair_family_set.contains(row.pair_family.as_str())
        })
        .collect::<Vec<_>>();
    if rows.is_empty() {
        return None;
    }

    let reverse_biased_window_count = rows
        .iter()
        .filter(|row| row.bias_direction == "reverse")
        .count();
    let forward_biased_window_count = rows
        .iter()
        .filter(|row| row.bias_direction == "forward")
        .count();
    let neutral_window_count = rows
        .iter()
        .filter(|row| row.bias_direction == "neutral")
        .count();
    let signed_hit_delta_total = rows.iter().map(|row| row.signed_hit_delta).sum::<i32>();
    let absolute_hit_delta_total = rows
        .iter()
        .map(|row| row.signed_hit_delta.unsigned_abs() as usize)
        .sum();
    let surface_direction = match reverse_biased_window_count.cmp(&forward_biased_window_count) {
        std::cmp::Ordering::Greater => "reverse",
        std::cmp::Ordering::Less => "forward",
        std::cmp::Ordering::Equal => "none",
    };
    let surface_status = match surface_direction {
        "reverse" => "reverse-sign-persistent-surface",
        "forward" => "forward-sign-persistent-surface",
        _ => "neutral-or-split-sign-surface",
    };

    Some(ConnectorWidth6SignPersistenceSurfaceRow {
        width,
        connector: connector.to_string(),
        surface_id: surface_id.to_string(),
        pair_families: pair_families
            .iter()
            .map(|family| (*family).to_string())
            .collect(),
        pair_family_count: pair_families.len(),
        window_count: rows.len(),
        reverse_biased_window_count,
        forward_biased_window_count,
        neutral_window_count,
        signed_hit_delta_total,
        absolute_hit_delta_total,
        surface_direction: surface_direction.to_string(),
        surface_status: surface_status.to_string(),
    })
}

fn build_pair_family_gap_cohort_sign_persistence_picker(
    stress: Option<&ConnectorWidth6PairFamilyGapCohortWindowConsensusStress>,
) -> Option<ConnectorWidth6PairFamilyGapCohortSignPersistencePicker> {
    let stress = stress?;
    if stress.next_experiment_target
        != "select-new-cohort-invariant-surface-after-window-consensus-heldout-collapse"
    {
        return None;
    }

    let surfaces = sign_persistence_surface_specs();
    let mut candidate_rows = Vec::new();
    let mut surface_rows = Vec::new();
    let mut family_rows = Vec::new();
    let mut pair_families = BTreeSet::new();

    for (width, connector_value) in pair_family_gap_portfolio_connector_values() {
        let connector = format!("{connector_value:0width$}", width = width as usize);
        let mut candidate_surface_rows = Vec::new();
        let mut candidate_family_rows = Vec::new();
        for (surface_id, families) in &surfaces {
            let pair_family_names = families
                .iter()
                .map(|(pair_family, _, _, _)| *pair_family)
                .collect::<Vec<_>>();
            for (pair_family, source_pairs, fresh_pairs, separator_pairs) in families {
                pair_families.insert((*pair_family).to_string());
                let rows = build_window_consensus_stress_family_rows(
                    pair_family,
                    width,
                    connector_value,
                    &connector,
                    source_pairs.clone(),
                    fresh_pairs.clone(),
                    separator_pairs.clone(),
                )?;
                candidate_family_rows.extend(rows.clone());
                family_rows.extend(rows);
            }
            let surface_row = build_sign_persistence_surface_row(
                width,
                &connector,
                surface_id,
                &pair_family_names,
                &candidate_family_rows,
            )?;
            candidate_surface_rows.push(surface_row.clone());
            surface_rows.push(surface_row);
        }

        let reverse_surface_count = candidate_surface_rows
            .iter()
            .filter(|row| row.surface_direction == "reverse")
            .count();
        let forward_surface_count = candidate_surface_rows
            .iter()
            .filter(|row| row.surface_direction == "forward")
            .count();
        let neutral_surface_count = candidate_surface_rows
            .iter()
            .filter(|row| row.surface_direction == "none")
            .count();
        let (persistent_direction, persistent_surface_count, opposite_surface_count) =
            match reverse_surface_count.cmp(&forward_surface_count) {
                std::cmp::Ordering::Greater => {
                    ("reverse", reverse_surface_count, forward_surface_count)
                }
                std::cmp::Ordering::Less => {
                    ("forward", forward_surface_count, reverse_surface_count)
                }
                std::cmp::Ordering::Equal => ("none", 0, 0),
            };
        let retained_window_count = candidate_surface_rows
            .iter()
            .map(|row| match persistent_direction {
                "reverse" => row.reverse_biased_window_count,
                "forward" => row.forward_biased_window_count,
                _ => 0,
            })
            .sum();
        let opposite_window_count = candidate_surface_rows
            .iter()
            .map(|row| match persistent_direction {
                "reverse" => row.forward_biased_window_count,
                "forward" => row.reverse_biased_window_count,
                _ => 0,
            })
            .sum();
        let neutral_window_count = candidate_surface_rows
            .iter()
            .map(|row| row.neutral_window_count)
            .sum();
        let signed_hit_delta_total = candidate_surface_rows
            .iter()
            .map(|row| row.signed_hit_delta_total)
            .sum::<i32>();
        let absolute_hit_delta_total = candidate_surface_rows
            .iter()
            .map(|row| row.absolute_hit_delta_total)
            .sum();
        let volatility_score =
            opposite_surface_count * 100 + neutral_surface_count * 25 + opposite_window_count;
        let candidate_status = if persistent_direction != "none"
            && persistent_surface_count >= 3
            && opposite_surface_count == 0
            && retained_window_count > opposite_window_count
        {
            "surface-sign-persistent-cohort-invariant"
        } else if persistent_direction != "none" && persistent_surface_count >= 2 {
            "mixed-sign-persistence"
        } else {
            "no-sign-persistence"
        };
        let next_experiment_target = if candidate_status
            == "surface-sign-persistent-cohort-invariant"
        {
            format!(
                    "stress-test-sign-persistence-cohort-invariant-width{width}-connector-{connector}-direction-{persistent_direction}"
                )
        } else {
            format!(
                    "do-not-promote-sign-persistence-width{width}-connector-{connector}-without-low-volatility-surface-retention"
                )
        };

        candidate_rows.push(ConnectorWidth6SignPersistenceCandidateRow {
            candidate_rank: 0,
            width,
            connector,
            persistent_direction: persistent_direction.to_string(),
            persistent_surface_count,
            opposite_surface_count,
            neutral_surface_count,
            retained_window_count,
            opposite_window_count,
            neutral_window_count,
            signed_hit_delta_total,
            absolute_hit_delta_total,
            volatility_score,
            candidate_status: candidate_status.to_string(),
            next_experiment_target,
        });
    }

    candidate_rows.sort_by(|left, right| {
        let left_persistent = left.candidate_status == "surface-sign-persistent-cohort-invariant";
        let right_persistent = right.candidate_status == "surface-sign-persistent-cohort-invariant";
        right_persistent
            .cmp(&left_persistent)
            .then_with(|| {
                ratio_geometry_picker_direction_priority(&left.persistent_direction).cmp(
                    &ratio_geometry_picker_direction_priority(&right.persistent_direction),
                )
            })
            .then_with(|| {
                right
                    .persistent_surface_count
                    .cmp(&left.persistent_surface_count)
            })
            .then_with(|| left.volatility_score.cmp(&right.volatility_score))
            .then_with(|| right.retained_window_count.cmp(&left.retained_window_count))
            .then_with(|| {
                right
                    .absolute_hit_delta_total
                    .cmp(&left.absolute_hit_delta_total)
            })
            .then_with(|| left.width.cmp(&right.width))
            .then_with(|| left.connector.cmp(&right.connector))
    });
    for (index, row) in candidate_rows.iter_mut().enumerate() {
        row.candidate_rank = index + 1;
    }

    let persistent_candidate_count = candidate_rows
        .iter()
        .filter(|row| row.candidate_status == "surface-sign-persistent-cohort-invariant")
        .count();
    let selected_candidate = candidate_rows
        .iter()
        .find(|row| row.candidate_status == "surface-sign-persistent-cohort-invariant")
        .cloned();
    let picker_decision = if selected_candidate.is_some() {
        "sign-persistence-picker-selected-low-volatility-cohort-invariant"
    } else {
        "sign-persistence-picker-found-no-low-volatility-cohort-invariant"
    };
    let next_experiment_target = selected_candidate
        .as_ref()
        .map(|row| row.next_experiment_target.clone())
        .unwrap_or_else(|| {
            "select-new-cohort-invariant-surface-after-sign-persistence-picker-collapse".to_string()
        });

    Some(ConnectorWidth6PairFamilyGapCohortSignPersistencePicker {
        selection_rule:
            "after held-out window-consensus collapse, scan frozen portfolio for same-sign low-volatility geometry across original and held-out gap/size surfaces before residue profiling"
                .to_string(),
        source_route_status: stress.stress_status.clone(),
        candidate_count: candidate_rows.len(),
        surface_count: surfaces.len(),
        surfaces: surfaces
            .iter()
            .map(|(surface_id, _)| (*surface_id).to_string())
            .collect(),
        pair_family_count: pair_families.len(),
        window_count: family_rows.len(),
        persistent_candidate_count,
        selected_candidate,
        picker_decision: picker_decision.to_string(),
        next_experiment_target,
        candidate_rows,
        surface_rows,
        family_rows,
    })
}

