fn build_pair_family_gap_cohort_sign_persistence_stress(
    picker: Option<&ConnectorWidth6PairFamilyGapCohortSignPersistencePicker>,
) -> Option<ConnectorWidth6PairFamilyGapCohortSignPersistenceStress> {
    let picker = picker?;
    if picker.next_experiment_target
        != "stress-test-sign-persistence-cohort-invariant-width6-connector-003727-direction-reverse"
    {
        return None;
    }
    let selected = picker.selected_candidate.as_ref()?;
    let connector_value = selected.connector.parse::<u128>().ok()?;
    let stress_surfaces = sign_persistence_stress_surface_specs();
    let mut surface_rows = Vec::new();
    let mut family_rows = Vec::new();
    let mut pair_families = BTreeSet::new();

    for (surface_id, families) in &stress_surfaces {
        let pair_family_names = families
            .iter()
            .map(|(pair_family, _, _, _)| *pair_family)
            .collect::<Vec<_>>();
        let mut surface_family_rows = Vec::new();
        for (pair_family, source_pairs, fresh_pairs, separator_pairs) in families {
            pair_families.insert((*pair_family).to_string());
            let rows = build_window_consensus_stress_family_rows(
                pair_family,
                selected.width,
                connector_value,
                &selected.connector,
                source_pairs.clone(),
                fresh_pairs.clone(),
                separator_pairs.clone(),
            )?;
            surface_family_rows.extend(rows.clone());
            family_rows.extend(rows);
        }
        surface_rows.push(build_sign_persistence_surface_row(
            selected.width,
            &selected.connector,
            surface_id,
            &pair_family_names,
            &surface_family_rows,
        )?);
    }

    let retained_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_direction == selected.persistent_direction)
        .count();
    let split_surface_count = surface_rows
        .iter()
        .filter(|row| {
            row.surface_direction != "none"
                && row.surface_direction != selected.persistent_direction
        })
        .count();
    let neutral_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_direction == "none")
        .count();
    let retained_window_count = surface_rows
        .iter()
        .map(|row| match selected.persistent_direction.as_str() {
            "reverse" => row.reverse_biased_window_count,
            "forward" => row.forward_biased_window_count,
            _ => 0,
        })
        .sum();
    let opposite_window_count = surface_rows
        .iter()
        .map(|row| match selected.persistent_direction.as_str() {
            "reverse" => row.forward_biased_window_count,
            "forward" => row.reverse_biased_window_count,
            _ => 0,
        })
        .sum();
    let neutral_window_count = surface_rows
        .iter()
        .map(|row| row.neutral_window_count)
        .sum();
    let signed_hit_delta_total = surface_rows
        .iter()
        .map(|row| row.signed_hit_delta_total)
        .sum();
    let absolute_hit_delta_total = surface_rows
        .iter()
        .map(|row| row.absolute_hit_delta_total)
        .sum();

    let (stress_status, stress_decision, next_experiment_target) = if retained_surface_count
        == surface_rows.len()
        && opposite_window_count == 0
    {
        (
            "sign-persistence-retained-on-fresh-surfaces",
            "sign-persistence-fresh-stress-retained-residue-profiler-next",
            format!(
                "residue-profile-sign-persistence-width{}-connector-{}-direction-{}",
                selected.width, selected.connector, selected.persistent_direction
            ),
        )
    } else if retained_surface_count > split_surface_count
        && retained_window_count > opposite_window_count
    {
        (
            "sign-persistence-mixed-retained-on-fresh-surfaces",
            "sign-persistence-fresh-stress-mixed-retained-residue-profiler-next",
            format!(
                "residue-profile-sign-persistence-width{}-connector-{}-direction-{}",
                selected.width, selected.connector, selected.persistent_direction
            ),
        )
    } else if split_surface_count > 0 || opposite_window_count > retained_window_count {
        (
            "sign-persistence-split-on-fresh-surfaces",
            "sign-persistence-fresh-stress-split-record-falsification",
            "select-new-cohort-invariant-surface-after-sign-persistence-fresh-split".to_string(),
        )
    } else {
        (
            "sign-persistence-collapsed-on-fresh-surfaces",
            "sign-persistence-fresh-stress-collapsed-record-falsification",
            "select-new-cohort-invariant-surface-after-sign-persistence-fresh-collapse".to_string(),
        )
    };

    Some(ConnectorWidth6PairFamilyGapCohortSignPersistenceStress {
        selection_rule:
            "stress-test selected low-volatility sign-persistence cohort invariant on disjoint generated gap32/34/36 and gap8 size280k/320k/360k windows before residue profiling"
                .to_string(),
        source_width: selected.width,
        source_connector: selected.connector.clone(),
        source_direction: selected.persistent_direction.clone(),
        source_target: picker.next_experiment_target.clone(),
        surface_count: surface_rows.len(),
        surfaces: stress_surfaces
            .iter()
            .map(|(surface_id, _)| (*surface_id).to_string())
            .collect(),
        pair_family_count: pair_families.len(),
        window_count: family_rows.len(),
        retained_surface_count,
        split_surface_count,
        neutral_surface_count,
        retained_window_count,
        opposite_window_count,
        neutral_window_count,
        signed_hit_delta_total,
        absolute_hit_delta_total,
        stress_status: stress_status.to_string(),
        stress_decision: stress_decision.to_string(),
        next_experiment_target,
        surface_rows,
        family_rows,
    })
}

fn volatility_ensemble_surface_specs() -> Vec<(
    &'static str,
    Vec<(&'static str, Vec<PairCase>, Vec<PairCase>, Vec<PairCase>)>,
)> {
    let mut surfaces = sign_persistence_surface_specs();
    surfaces.extend(sign_persistence_stress_surface_specs());
    surfaces
}

fn volatility_connector_label(width: u32, connector: &str) -> String {
    format!("width{width}:{connector}")
}

fn volatility_window_counts_for_direction(
    row: &ConnectorWidth6SignPersistenceSurfaceRow,
    direction: &str,
) -> (usize, usize) {
    match direction {
        "reverse" => (
            row.reverse_biased_window_count,
            row.forward_biased_window_count,
        ),
        "forward" => (
            row.forward_biased_window_count,
            row.reverse_biased_window_count,
        ),
        _ => (0, 0),
    }
}

fn build_volatility_ensemble_candidate_row(
    width: u32,
    connector: &str,
    surface_rows: &[ConnectorWidth6SignPersistenceSurfaceRow],
) -> ConnectorWidth6VolatilityEnsembleCandidateRow {
    let reverse_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_direction == "reverse")
        .count();
    let forward_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_direction == "forward")
        .count();
    let neutral_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_direction == "none")
        .count();
    let (retained_direction, retained_surface_count, opposite_surface_count) =
        match reverse_surface_count.cmp(&forward_surface_count) {
            std::cmp::Ordering::Greater => {
                ("reverse", reverse_surface_count, forward_surface_count)
            }
            std::cmp::Ordering::Less => ("forward", forward_surface_count, reverse_surface_count),
            std::cmp::Ordering::Equal => ("none", 0, 0),
        };
    let retained_window_count = surface_rows
        .iter()
        .map(|row| volatility_window_counts_for_direction(row, retained_direction).0)
        .sum();
    let opposite_window_count = surface_rows
        .iter()
        .map(|row| volatility_window_counts_for_direction(row, retained_direction).1)
        .sum();
    let neutral_window_count = surface_rows
        .iter()
        .map(|row| row.neutral_window_count)
        .sum();
    let signed_hit_delta_total = surface_rows
        .iter()
        .map(|row| row.signed_hit_delta_total)
        .sum();
    let absolute_hit_delta_total = surface_rows
        .iter()
        .map(|row| row.absolute_hit_delta_total)
        .sum();
    let volatility_score =
        opposite_surface_count * 100 + neutral_surface_count * 25 + opposite_window_count;
    let candidate_status = if retained_direction != "none" && retained_surface_count >= 4 {
        "connector-direction-retained-across-ensemble-surfaces"
    } else if retained_direction != "none" && retained_surface_count >= 3 {
        "connector-direction-mixed-across-ensemble-surfaces"
    } else {
        "no-connector-direction-ensemble"
    };

    ConnectorWidth6VolatilityEnsembleCandidateRow {
        candidate_rank: 0,
        width,
        connector: connector.to_string(),
        retained_direction: retained_direction.to_string(),
        retained_surface_count,
        opposite_surface_count,
        neutral_surface_count,
        retained_window_count,
        opposite_window_count,
        neutral_window_count,
        signed_hit_delta_total,
        absolute_hit_delta_total,
        volatility_score,
        candidate_status: candidate_status.to_string(),
    }
}

fn build_volatility_ensemble_row(
    direction: &str,
    surfaces: &[String],
    surface_rows: &[ConnectorWidth6SignPersistenceSurfaceRow],
) -> Option<ConnectorWidth6VolatilityEnsembleRow> {
    let mut supported_surfaces = Vec::new();
    let mut selected_connectors = BTreeSet::new();
    let mut retained_window_total = 0;
    let mut opposite_window_total = 0;
    let mut neutral_window_total = 0;
    let mut signed_hit_delta_total = 0;
    let mut absolute_hit_delta_total = 0;

    for surface_id in surfaces {
        let rows = surface_rows
            .iter()
            .filter(|row| row.surface_id == *surface_id && row.surface_direction == direction)
            .collect::<Vec<_>>();
        if rows.len() < 3 {
            continue;
        }
        supported_surfaces.push(surface_id.clone());
        for row in rows {
            selected_connectors.insert(volatility_connector_label(row.width, &row.connector));
            let (retained, opposite) = volatility_window_counts_for_direction(row, direction);
            retained_window_total += retained;
            opposite_window_total += opposite;
            neutral_window_total += row.neutral_window_count;
            signed_hit_delta_total += row.signed_hit_delta_total;
            absolute_hit_delta_total += row.absolute_hit_delta_total;
        }
    }

    if supported_surfaces.is_empty() {
        return None;
    }

    let selected_connectors = selected_connectors.into_iter().collect::<Vec<_>>();
    let connector_count = selected_connectors.len();
    let ensemble_status = if supported_surfaces.len() >= 4 {
        "volatility-ensemble-retained-across-surfaces"
    } else {
        "volatility-ensemble-below-four-surface-threshold"
    };
    let next_experiment_target = if ensemble_status
        == "volatility-ensemble-retained-across-surfaces"
    {
        format!("stress-test-volatility-ensemble-cohort-direction-{direction}-connector-count-{connector_count}")
    } else {
        format!(
            "do-not-promote-volatility-ensemble-direction-{direction}-without-four-surface-support"
        )
    };

    Some(ConnectorWidth6VolatilityEnsembleRow {
        ensemble_rank: 0,
        direction: direction.to_string(),
        supported_surface_count: supported_surfaces.len(),
        supported_surfaces,
        connector_count,
        selected_connectors,
        retained_window_total,
        opposite_window_total,
        neutral_window_total,
        signed_hit_delta_total,
        absolute_hit_delta_total,
        ensemble_status: ensemble_status.to_string(),
        next_experiment_target,
    })
}

fn build_pair_family_gap_cohort_volatility_ensemble_picker(
    stress: Option<&ConnectorWidth6PairFamilyGapCohortSignPersistenceStress>,
) -> Option<ConnectorWidth6PairFamilyGapCohortVolatilityEnsemblePicker> {
    let stress = stress?;
    if stress.next_experiment_target
        != "select-new-cohort-invariant-surface-after-sign-persistence-fresh-split"
    {
        return None;
    }

    let surfaces = volatility_ensemble_surface_specs();
    let surface_names = surfaces
        .iter()
        .map(|(surface_id, _)| (*surface_id).to_string())
        .collect::<Vec<_>>();
    let mut candidate_rows = Vec::new();
    let mut surface_rows = Vec::new();
    let mut family_rows = Vec::new();
    let mut pair_families = BTreeSet::new();

    for (width, connector_value) in pair_family_gap_portfolio_connector_values() {
        let connector = format!("{connector_value:0width$}", width = width as usize);
        let mut connector_surface_rows = Vec::new();
        for (surface_id, families) in &surfaces {
            let pair_family_names = families
                .iter()
                .map(|(pair_family, _, _, _)| *pair_family)
                .collect::<Vec<_>>();
            let mut surface_family_rows = Vec::new();
            for (pair_family, source_pairs, fresh_pairs, separator_pairs) in families {
                pair_families.insert((*pair_family).to_string());
                let rows = build_window_consensus_stress_family_rows(
                    pair_family,
                    width,
                    connector_value,
                    &connector,
                    source_pairs.clone(),
                    fresh_pairs.clone(),
                    separator_pairs.clone(),
                )?;
                surface_family_rows.extend(rows.clone());
                family_rows.extend(rows);
            }
            let surface_row = build_sign_persistence_surface_row(
                width,
                &connector,
                surface_id,
                &pair_family_names,
                &surface_family_rows,
            )?;
            connector_surface_rows.push(surface_row.clone());
            surface_rows.push(surface_row);
        }
        candidate_rows.push(build_volatility_ensemble_candidate_row(
            width,
            &connector,
            &connector_surface_rows,
        ));
    }

    candidate_rows.sort_by(|left, right| {
        let left_directional = left.retained_direction != "none";
        let right_directional = right.retained_direction != "none";
        right_directional
            .cmp(&left_directional)
            .then_with(|| {
                right
                    .retained_surface_count
                    .cmp(&left.retained_surface_count)
            })
            .then_with(|| left.volatility_score.cmp(&right.volatility_score))
            .then_with(|| right.retained_window_count.cmp(&left.retained_window_count))
            .then_with(|| {
                right
                    .absolute_hit_delta_total
                    .cmp(&left.absolute_hit_delta_total)
            })
            .then_with(|| {
                ratio_geometry_picker_direction_priority(&left.retained_direction).cmp(
                    &ratio_geometry_picker_direction_priority(&right.retained_direction),
                )
            })
            .then_with(|| left.width.cmp(&right.width))
            .then_with(|| left.connector.cmp(&right.connector))
    });
    for (index, row) in candidate_rows.iter_mut().enumerate() {
        row.candidate_rank = index + 1;
    }

    let mut ensemble_rows = ["reverse", "forward"]
        .into_iter()
        .filter_map(|direction| {
            build_volatility_ensemble_row(direction, &surface_names, &surface_rows)
        })
        .collect::<Vec<_>>();
    ensemble_rows.sort_by(|left, right| {
        let left_qualifies = left.ensemble_status == "volatility-ensemble-retained-across-surfaces";
        let right_qualifies =
            right.ensemble_status == "volatility-ensemble-retained-across-surfaces";
        right_qualifies
            .cmp(&left_qualifies)
            .then_with(|| {
                right
                    .supported_surface_count
                    .cmp(&left.supported_surface_count)
            })
            .then_with(|| right.connector_count.cmp(&left.connector_count))
            .then_with(|| left.opposite_window_total.cmp(&right.opposite_window_total))
            .then_with(|| {
                right
                    .absolute_hit_delta_total
                    .cmp(&left.absolute_hit_delta_total)
            })
            .then_with(|| {
                ratio_geometry_picker_direction_priority(&left.direction)
                    .cmp(&ratio_geometry_picker_direction_priority(&right.direction))
            })
            .then_with(|| left.selected_connectors.cmp(&right.selected_connectors))
    });
    for (index, row) in ensemble_rows.iter_mut().enumerate() {
        row.ensemble_rank = index + 1;
    }
    let qualifying_ensemble_count = ensemble_rows
        .iter()
        .filter(|row| row.ensemble_status == "volatility-ensemble-retained-across-surfaces")
        .count();
    let selected_ensemble = ensemble_rows
        .iter()
        .find(|row| row.ensemble_status == "volatility-ensemble-retained-across-surfaces")
        .cloned();
    let picker_decision = if selected_ensemble.is_some() {
        "volatility-ensemble-picker-selected-shared-direction-cohort"
    } else {
        "volatility-ensemble-picker-found-no-four-surface-ensemble"
    };
    let next_experiment_target = selected_ensemble
        .as_ref()
        .map(|row| row.next_experiment_target.clone())
        .unwrap_or_else(|| {
            "select-new-cohort-invariant-surface-after-volatility-ensemble-picker-collapse"
                .to_string()
        });

    Some(ConnectorWidth6PairFamilyGapCohortVolatilityEnsemblePicker {
        selection_rule:
            "after singleton sign-persistence split, scan frozen portfolio for direction cohorts where at least three connectors share a non-neutral surface direction and one direction spans at least four of six surfaces"
                .to_string(),
        source_route_status: stress.stress_status.clone(),
        candidate_count: candidate_rows.len(),
        surface_count: surface_names.len(),
        surfaces: surface_names,
        pair_family_count: pair_families.len(),
        window_count: family_rows.len(),
        ensemble_count: ensemble_rows.len(),
        qualifying_ensemble_count,
        selected_ensemble,
        picker_decision: picker_decision.to_string(),
        next_experiment_target,
        candidate_rows,
        ensemble_rows,
        surface_rows,
        family_rows,
    })
}

fn parse_volatility_connector_label(label: &str) -> Option<(u32, String)> {
    let (width, connector) = label.split_once(':')?;
    let width = width.strip_prefix("width")?.parse::<u32>().ok()?;
    Some((width, connector.to_string()))
}

fn build_volatility_ensemble_stress_surface_row(
    surface_id: &str,
    pair_families: &[&str],
    selected_direction: &str,
    connector_rows: &[ConnectorWidth6SignPersistenceSurfaceRow],
) -> ConnectorWidth6VolatilityEnsembleStressSurfaceRow {
    let retained_connector_count = connector_rows
        .iter()
        .filter(|row| row.surface_direction == selected_direction)
        .count();
    let opposite_connector_count = connector_rows
        .iter()
        .filter(|row| {
            row.surface_direction != "none" && row.surface_direction != selected_direction
        })
        .count();
    let neutral_connector_count = connector_rows
        .iter()
        .filter(|row| row.surface_direction == "none")
        .count();
    let retained_window_total = connector_rows
        .iter()
        .map(|row| volatility_window_counts_for_direction(row, selected_direction).0)
        .sum();
    let opposite_window_total = connector_rows
        .iter()
        .map(|row| volatility_window_counts_for_direction(row, selected_direction).1)
        .sum();
    let neutral_window_total = connector_rows
        .iter()
        .map(|row| row.neutral_window_count)
        .sum();
    let signed_hit_delta_total = connector_rows
        .iter()
        .map(|row| row.signed_hit_delta_total)
        .sum();
    let absolute_hit_delta_total = connector_rows
        .iter()
        .map(|row| row.absolute_hit_delta_total)
        .sum();
    let surface_status = if retained_connector_count >= 3
        && retained_connector_count > opposite_connector_count
        && retained_window_total > opposite_window_total
    {
        "volatility-ensemble-retained-fresh-surface"
    } else if retained_connector_count >= 3 && retained_window_total > opposite_window_total {
        "volatility-ensemble-mixed-retained-fresh-surface"
    } else if opposite_connector_count >= retained_connector_count
        || opposite_window_total >= retained_window_total
    {
        "volatility-ensemble-split-fresh-surface"
    } else {
        "volatility-ensemble-collapsed-fresh-surface"
    };

    ConnectorWidth6VolatilityEnsembleStressSurfaceRow {
        surface_id: surface_id.to_string(),
        pair_families: pair_families
            .iter()
            .map(|family| (*family).to_string())
            .collect(),
        connector_count: connector_rows.len(),
        retained_connector_count,
        opposite_connector_count,
        neutral_connector_count,
        retained_window_total,
        opposite_window_total,
        neutral_window_total,
        signed_hit_delta_total,
        absolute_hit_delta_total,
        surface_status: surface_status.to_string(),
    }
}

fn build_pair_family_gap_cohort_volatility_ensemble_stress(
    picker: Option<&ConnectorWidth6PairFamilyGapCohortVolatilityEnsemblePicker>,
) -> Option<ConnectorWidth6PairFamilyGapCohortVolatilityEnsembleStress> {
    let picker = picker?;
    if picker.next_experiment_target
        != "stress-test-volatility-ensemble-cohort-direction-forward-connector-count-14"
    {
        return None;
    }
    let selected = picker.selected_ensemble.as_ref()?;
    let selected_connectors = selected
        .selected_connectors
        .iter()
        .map(|label| parse_volatility_connector_label(label))
        .collect::<Option<Vec<_>>>()?;
    let stress_surfaces = volatility_ensemble_stress_surface_specs();
    let mut surfaces = Vec::new();
    let mut surface_rows = Vec::new();
    let mut connector_surface_rows = Vec::new();
    let mut family_rows = Vec::new();
    let mut pair_families = BTreeSet::new();

    for (surface_id, families) in stress_surfaces {
        surfaces.push(surface_id.to_string());
        let pair_family_names = families
            .iter()
            .map(|(pair_family, _, _, _)| *pair_family)
            .collect::<Vec<_>>();
        let mut surface_connector_rows = Vec::new();

        for (width, connector) in &selected_connectors {
            let connector_value = connector.parse::<u128>().ok()?;
            let mut connector_family_rows = Vec::new();
            for (pair_family, source_pairs, fresh_pairs, separator_pairs) in &families {
                pair_families.insert((*pair_family).to_string());
                let rows = build_window_consensus_stress_family_rows(
                    pair_family,
                    *width,
                    connector_value,
                    connector,
                    source_pairs.clone(),
                    fresh_pairs.clone(),
                    separator_pairs.clone(),
                )?;
                connector_family_rows.extend(rows.clone());
                family_rows.extend(rows);
            }
            let surface_row = build_sign_persistence_surface_row(
                *width,
                connector,
                surface_id,
                &pair_family_names,
                &connector_family_rows,
            )?;
            surface_connector_rows.push(surface_row.clone());
            connector_surface_rows.push(surface_row);
        }

        surface_rows.push(build_volatility_ensemble_stress_surface_row(
            surface_id,
            &pair_family_names,
            &selected.direction,
            &surface_connector_rows,
        ));
    }

    let retained_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_status == "volatility-ensemble-retained-fresh-surface")
        .count();
    let mixed_retained_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_status == "volatility-ensemble-mixed-retained-fresh-surface")
        .count();
    let split_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_status == "volatility-ensemble-split-fresh-surface")
        .count();
    let collapsed_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_status == "volatility-ensemble-collapsed-fresh-surface")
        .count();
    let retained_connector_total = surface_rows
        .iter()
        .map(|row| row.retained_connector_count)
        .sum();
    let opposite_connector_total = surface_rows
        .iter()
        .map(|row| row.opposite_connector_count)
        .sum();
    let neutral_connector_total = surface_rows
        .iter()
        .map(|row| row.neutral_connector_count)
        .sum();
    let retained_window_total = surface_rows
        .iter()
        .map(|row| row.retained_window_total)
        .sum();
    let opposite_window_total = surface_rows
        .iter()
        .map(|row| row.opposite_window_total)
        .sum();
    let neutral_window_total = surface_rows
        .iter()
        .map(|row| row.neutral_window_total)
        .sum();
    let signed_hit_delta_total = surface_rows
        .iter()
        .map(|row| row.signed_hit_delta_total)
        .sum();
    let absolute_hit_delta_total = surface_rows
        .iter()
        .map(|row| row.absolute_hit_delta_total)
        .sum();

    let stress_status = if retained_surface_count == surface_rows.len() {
        "volatility-ensemble-retained-on-fresh-surfaces"
    } else if retained_surface_count + mixed_retained_surface_count > 0
        && retained_window_total > opposite_window_total
    {
        "volatility-ensemble-mixed-retained-on-fresh-surfaces"
    } else if split_surface_count > 0
        || opposite_connector_total >= retained_connector_total
        || opposite_window_total >= retained_window_total
    {
        "volatility-ensemble-split-on-fresh-surfaces"
    } else {
        "volatility-ensemble-collapsed-on-fresh-surfaces"
    };
    let (stress_decision, next_experiment_target) = match stress_status {
        "volatility-ensemble-retained-on-fresh-surfaces"
        | "volatility-ensemble-mixed-retained-on-fresh-surfaces" => (
            "volatility-ensemble-fresh-stress-retained-anatomy-next",
            "analyze-volatility-ensemble-anatomy-direction-forward-connector-count-14".to_string(),
        ),
        "volatility-ensemble-split-on-fresh-surfaces" => (
            "volatility-ensemble-fresh-stress-split-record-falsification",
            "select-new-cohort-invariant-surface-after-volatility-ensemble-fresh-split".to_string(),
        ),
        _ => (
            "volatility-ensemble-fresh-stress-collapsed-record-falsification",
            "select-new-cohort-invariant-surface-after-volatility-ensemble-fresh-collapse"
                .to_string(),
        ),
    };

    Some(ConnectorWidth6PairFamilyGapCohortVolatilityEnsembleStress {
        selection_rule:
            "stress-test selected volatility/ensemble cohort on fresh generated gap38/40/42 and gap8 size400k/440k/480k surfaces before residue profiling or theorem work"
                .to_string(),
        source_direction: selected.direction.clone(),
        source_connector_count: selected.connector_count,
        source_connectors: selected.selected_connectors.clone(),
        source_supported_surface_count: selected.supported_surface_count,
        source_target: picker.next_experiment_target.clone(),
        surface_count: surface_rows.len(),
        surfaces,
        pair_family_count: pair_families.len(),
        connector_surface_row_count: connector_surface_rows.len(),
        family_window_row_count: family_rows.len(),
        retained_surface_count,
        mixed_retained_surface_count,
        split_surface_count,
        collapsed_surface_count,
        retained_connector_total,
        opposite_connector_total,
        neutral_connector_total,
        retained_window_total,
        opposite_window_total,
        neutral_window_total,
        signed_hit_delta_total,
        absolute_hit_delta_total,
        stress_status: stress_status.to_string(),
        stress_decision: stress_decision.to_string(),
        next_experiment_target,
        surface_rows,
        connector_surface_rows,
        family_rows,
    })
}

fn surface_family_for_contrast(surface_id: &str) -> &'static str {
    if surface_id == "size-band" || surface_id.contains("gap8-size") {
        "size-family"
    } else {
        "gap-family"
    }
}

fn build_surface_family_contrast_surface_row(
    surface_id: &str,
    selected_direction: &str,
    connector_rows: &[ConnectorWidth6SignPersistenceSurfaceRow],
) -> ConnectorWidth6SurfaceFamilyContrastSurfaceRow {
    let retained_connector_count = connector_rows
        .iter()
        .filter(|row| row.surface_direction == selected_direction)
        .count();
    let opposite_connector_count = connector_rows
        .iter()
        .filter(|row| {
            row.surface_direction != "none" && row.surface_direction != selected_direction
        })
        .count();
    let neutral_connector_count = connector_rows
        .iter()
        .filter(|row| row.surface_direction == "none")
        .count();
    let retained_window_total = connector_rows
        .iter()
        .map(|row| volatility_window_counts_for_direction(row, selected_direction).0)
        .sum();
    let opposite_window_total = connector_rows
        .iter()
        .map(|row| volatility_window_counts_for_direction(row, selected_direction).1)
        .sum();
    let neutral_window_total = connector_rows
        .iter()
        .map(|row| row.neutral_window_count)
        .sum();
    let signed_hit_delta_total = connector_rows
        .iter()
        .map(|row| row.signed_hit_delta_total)
        .sum();
    let absolute_hit_delta_total = connector_rows
        .iter()
        .map(|row| row.absolute_hit_delta_total)
        .sum();
    let surface_status = if retained_connector_count > opposite_connector_count
        && retained_window_total > opposite_window_total
    {
        "selected-direction-retained-surface"
    } else if opposite_connector_count > retained_connector_count
        && opposite_window_total > retained_window_total
    {
        "opposite-direction-split-surface"
    } else {
        "mixed-surface-family-contrast"
    };

    ConnectorWidth6SurfaceFamilyContrastSurfaceRow {
        surface_id: surface_id.to_string(),
        surface_family: surface_family_for_contrast(surface_id).to_string(),
        connector_count: connector_rows.len(),
        retained_connector_count,
        opposite_connector_count,
        neutral_connector_count,
        retained_window_total,
        opposite_window_total,
        neutral_window_total,
        signed_hit_delta_total,
        absolute_hit_delta_total,
        surface_status: surface_status.to_string(),
    }
}

fn build_surface_family_contrast_family_row(
    surface_family: &str,
    surface_rows: &[ConnectorWidth6SurfaceFamilyContrastSurfaceRow],
) -> ConnectorWidth6SurfaceFamilyContrastFamilyRow {
    let surfaces = surface_rows
        .iter()
        .map(|row| row.surface_id.clone())
        .collect::<Vec<_>>();
    let retained_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_status == "selected-direction-retained-surface")
        .count();
    let split_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_status == "opposite-direction-split-surface")
        .count();
    let mixed_surface_count = surface_rows.len() - retained_surface_count - split_surface_count;
    let connector_surface_count = surface_rows.iter().map(|row| row.connector_count).sum();
    let retained_connector_total = surface_rows
        .iter()
        .map(|row| row.retained_connector_count)
        .sum();
    let opposite_connector_total = surface_rows
        .iter()
        .map(|row| row.opposite_connector_count)
        .sum();
    let neutral_connector_total = surface_rows
        .iter()
        .map(|row| row.neutral_connector_count)
        .sum();
    let retained_window_total = surface_rows
        .iter()
        .map(|row| row.retained_window_total)
        .sum();
    let opposite_window_total = surface_rows
        .iter()
        .map(|row| row.opposite_window_total)
        .sum();
    let neutral_window_total = surface_rows
        .iter()
        .map(|row| row.neutral_window_total)
        .sum();
    let signed_hit_delta_total = surface_rows
        .iter()
        .map(|row| row.signed_hit_delta_total)
        .sum();
    let absolute_hit_delta_total = surface_rows
        .iter()
        .map(|row| row.absolute_hit_delta_total)
        .sum();
    let surface_family_status = if retained_connector_total > opposite_connector_total
        && retained_window_total > opposite_window_total
    {
        "selected-direction-retained-surface-family"
    } else if opposite_connector_total > retained_connector_total
        && opposite_window_total > retained_window_total
    {
        "opposite-direction-split-surface-family"
    } else {
        "mixed-surface-family-contrast"
    };

    ConnectorWidth6SurfaceFamilyContrastFamilyRow {
        surface_family: surface_family.to_string(),
        surface_count: surface_rows.len(),
        surfaces,
        connector_surface_count,
        retained_surface_count,
        split_surface_count,
        mixed_surface_count,
        retained_connector_total,
        opposite_connector_total,
        neutral_connector_total,
        retained_window_total,
        opposite_window_total,
        neutral_window_total,
        signed_hit_delta_total,
        absolute_hit_delta_total,
        surface_family_status: surface_family_status.to_string(),
    }
}

fn build_pair_family_gap_cohort_surface_family_contrast_picker(
    picker: Option<&ConnectorWidth6PairFamilyGapCohortVolatilityEnsemblePicker>,
    stress: Option<&ConnectorWidth6PairFamilyGapCohortVolatilityEnsembleStress>,
) -> Option<ConnectorWidth6PairFamilyGapCohortSurfaceFamilyContrastPicker> {
    let picker = picker?;
    let stress = stress?;
    if stress.next_experiment_target
        != "select-new-cohort-invariant-surface-after-volatility-ensemble-fresh-split"
    {
        return None;
    }
    let selected = picker.selected_ensemble.as_ref()?;
    let selected_connectors = selected.selected_connectors.iter().collect::<BTreeSet<_>>();
    let mut rows_by_surface: BTreeMap<String, Vec<ConnectorWidth6SignPersistenceSurfaceRow>> =
        BTreeMap::new();
    for row in picker
        .surface_rows
        .iter()
        .chain(stress.connector_surface_rows.iter())
    {
        let label = volatility_connector_label(row.width, &row.connector);
        if selected_connectors.contains(&label) {
            rows_by_surface
                .entry(row.surface_id.clone())
                .or_default()
                .push(row.clone());
        }
    }

    let mut surface_rows = rows_by_surface
        .iter()
        .map(|(surface_id, rows)| {
            build_surface_family_contrast_surface_row(surface_id, &selected.direction, rows)
        })
        .collect::<Vec<_>>();
    surface_rows.sort_by(|left, right| left.surface_id.cmp(&right.surface_id));

    let mut family_groups: BTreeMap<String, Vec<ConnectorWidth6SurfaceFamilyContrastSurfaceRow>> =
        BTreeMap::new();
    for row in &surface_rows {
        family_groups
            .entry(row.surface_family.clone())
            .or_default()
            .push(row.clone());
    }
    let mut family_rows = family_groups
        .iter()
        .map(|(surface_family, rows)| {
            build_surface_family_contrast_family_row(surface_family, rows)
        })
        .collect::<Vec<_>>();
    family_rows.sort_by(|left, right| left.surface_family.cmp(&right.surface_family));

    let retained_family_count = family_rows
        .iter()
        .filter(|row| row.surface_family_status == "selected-direction-retained-surface-family")
        .count();
    let split_family_count = family_rows
        .iter()
        .filter(|row| row.surface_family_status == "opposite-direction-split-surface-family")
        .count();
    let mixed_family_count = family_rows.len() - retained_family_count - split_family_count;
    let selected_family = family_rows
        .iter()
        .find(|row| row.surface_family_status == "selected-direction-retained-surface-family")
        .map(|row| row.surface_family.clone());
    let opposite_family = family_rows
        .iter()
        .find(|row| row.surface_family_status == "opposite-direction-split-surface-family")
        .map(|row| row.surface_family.clone());

    let (contrast_status, picker_decision, next_experiment_target) = if let (
        Some(selected_family),
        Some(opposite_family),
    ) =
        (selected_family.as_ref(), opposite_family.as_ref())
    {
        (
                "surface-family-directional-contrast-found",
                "surface-family-contrast-picker-selected-directional-gap-size-contrast",
                format!(
                    "stress-test-surface-family-contrast-{selected_family}-{}-vs-{opposite_family}-opposite",
                    selected.direction
                ),
            )
    } else if retained_family_count > 0 {
        (
            "surface-family-retention-without-opposite-family",
            "surface-family-contrast-picker-found-retention-without-clean-contrast",
            format!(
                "expand-surface-family-retention-direction-{}-before-residue-profile",
                selected.direction
            ),
        )
    } else {
        (
            "surface-family-contrast-null",
            "surface-family-contrast-picker-found-no-family-level-contrast",
            "select-new-cohort-invariant-surface-after-surface-family-contrast-null".to_string(),
        )
    };

    Some(ConnectorWidth6PairFamilyGapCohortSurfaceFamilyContrastPicker {
        selection_rule:
            "after volatility/ensemble fresh split, group all selected-ensemble surfaces into gap-family versus size-family and ask whether one surface family retains the selected direction while the other splits"
                .to_string(),
        source_route_status: stress.stress_status.clone(),
        source_direction: selected.direction.clone(),
        source_connector_count: selected.connector_count,
        source_surface_count: surface_rows.len(),
        surface_family_count: family_rows.len(),
        connector_surface_row_count: surface_rows.iter().map(|row| row.connector_count).sum(),
        retained_family_count,
        split_family_count,
        mixed_family_count,
        selected_family,
        opposite_family,
        contrast_status: contrast_status.to_string(),
        picker_decision: picker_decision.to_string(),
        next_experiment_target,
        family_rows,
        surface_rows,
    })
}

fn surface_family_contrast_stress_surface_specs() -> Vec<(
    &'static str,
    Vec<(&'static str, Vec<PairCase>, Vec<PairCase>, Vec<PairCase>)>,
)> {
    let (gap44_source, gap44_fresh, gap44_separator) = connector_gap44_generated_pair_cases();
    let (gap46_source, gap46_fresh, gap46_separator) = connector_gap46_generated_pair_cases();
    let (gap48_source, gap48_fresh, gap48_separator) = connector_gap48_generated_pair_cases();
    let (size520_source, size520_fresh, size520_separator) =
        connector_gap8_size520k_generated_pair_cases();
    let (size560_source, size560_fresh, size560_separator) =
        connector_gap8_size560k_generated_pair_cases();
    let (size600_source, size600_fresh, size600_separator) =
        connector_gap8_size600k_generated_pair_cases();

    vec![
        (
            "fresh-contrast-generated-gap-family",
            vec![
                ("prime-gap44", gap44_source, gap44_fresh, gap44_separator),
                ("prime-gap46", gap46_source, gap46_fresh, gap46_separator),
                ("prime-gap48", gap48_source, gap48_fresh, gap48_separator),
            ],
        ),
        (
            "fresh-contrast-generated-gap8-size-family",
            vec![
                (
                    "prime-gap8-size520k",
                    size520_source,
                    size520_fresh,
                    size520_separator,
                ),
                (
                    "prime-gap8-size560k",
                    size560_source,
                    size560_fresh,
                    size560_separator,
                ),
                (
                    "prime-gap8-size600k",
                    size600_source,
                    size600_fresh,
                    size600_separator,
                ),
            ],
        ),
    ]
}

fn build_pair_family_gap_cohort_surface_family_contrast_stress(
    picker: Option<&ConnectorWidth6PairFamilyGapCohortSurfaceFamilyContrastPicker>,
    volatility_stress: Option<&ConnectorWidth6PairFamilyGapCohortVolatilityEnsembleStress>,
) -> Option<ConnectorWidth6PairFamilyGapCohortSurfaceFamilyContrastStress> {
    let picker = picker?;
    let volatility_stress = volatility_stress?;
    if picker.next_experiment_target
        != "stress-test-surface-family-contrast-gap-family-forward-vs-size-family-opposite"
    {
        return None;
    }
    let selected_family = picker.selected_family.clone()?;
    let opposite_family = picker.opposite_family.clone()?;
    let selected_connectors = volatility_stress
        .source_connectors
        .iter()
        .map(|label| parse_volatility_connector_label(label))
        .collect::<Option<Vec<_>>>()?;
    let stress_surfaces = surface_family_contrast_stress_surface_specs();
    let mut surface_rows = Vec::new();
    let mut connector_surface_rows = Vec::new();
    let mut family_window_rows = Vec::new();
    let mut pair_families = BTreeSet::new();

    for (surface_id, families) in stress_surfaces {
        let pair_family_names = families
            .iter()
            .map(|(pair_family, _, _, _)| *pair_family)
            .collect::<Vec<_>>();
        let mut surface_connector_rows = Vec::new();

        for (width, connector) in &selected_connectors {
            let connector_value = connector.parse::<u128>().ok()?;
            let mut connector_family_rows = Vec::new();
            for (pair_family, source_pairs, fresh_pairs, separator_pairs) in &families {
                pair_families.insert((*pair_family).to_string());
                let rows = build_window_consensus_stress_family_rows(
                    pair_family,
                    *width,
                    connector_value,
                    connector,
                    source_pairs.clone(),
                    fresh_pairs.clone(),
                    separator_pairs.clone(),
                )?;
                connector_family_rows.extend(rows.clone());
                family_window_rows.extend(rows);
            }
            let surface_row = build_sign_persistence_surface_row(
                *width,
                connector,
                surface_id,
                &pair_family_names,
                &connector_family_rows,
            )?;
            surface_connector_rows.push(surface_row.clone());
            connector_surface_rows.push(surface_row);
        }

        surface_rows.push(build_surface_family_contrast_surface_row(
            surface_id,
            &picker.source_direction,
            &surface_connector_rows,
        ));
    }
    surface_rows.sort_by(|left, right| left.surface_id.cmp(&right.surface_id));

    let mut family_groups: BTreeMap<String, Vec<ConnectorWidth6SurfaceFamilyContrastSurfaceRow>> =
        BTreeMap::new();
    for row in &surface_rows {
        family_groups
            .entry(row.surface_family.clone())
            .or_default()
            .push(row.clone());
    }
    let mut family_rows = family_groups
        .iter()
        .map(|(surface_family, rows)| {
            build_surface_family_contrast_family_row(surface_family, rows)
        })
        .collect::<Vec<_>>();
    family_rows.sort_by(|left, right| left.surface_family.cmp(&right.surface_family));

    let retained_family_count = family_rows
        .iter()
        .filter(|row| row.surface_family_status == "selected-direction-retained-surface-family")
        .count();
    let split_family_count = family_rows
        .iter()
        .filter(|row| row.surface_family_status == "opposite-direction-split-surface-family")
        .count();
    let mixed_family_count = family_rows.len() - retained_family_count - split_family_count;
    let retained_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_status == "selected-direction-retained-surface")
        .count();
    let split_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_status == "opposite-direction-split-surface")
        .count();
    let mixed_surface_count = surface_rows.len() - retained_surface_count - split_surface_count;
    let retained_connector_total = family_rows
        .iter()
        .map(|row| row.retained_connector_total)
        .sum();
    let opposite_connector_total = family_rows
        .iter()
        .map(|row| row.opposite_connector_total)
        .sum();
    let neutral_connector_total = family_rows
        .iter()
        .map(|row| row.neutral_connector_total)
        .sum();
    let retained_window_total = family_rows
        .iter()
        .map(|row| row.retained_window_total)
        .sum();
    let opposite_window_total = family_rows
        .iter()
        .map(|row| row.opposite_window_total)
        .sum();
    let neutral_window_total = family_rows.iter().map(|row| row.neutral_window_total).sum();
    let signed_hit_delta_total = family_rows
        .iter()
        .map(|row| row.signed_hit_delta_total)
        .sum();
    let absolute_hit_delta_total = family_rows
        .iter()
        .map(|row| row.absolute_hit_delta_total)
        .sum();

    let selected_family_retained = family_rows.iter().any(|row| {
        row.surface_family == selected_family
            && row.surface_family_status == "selected-direction-retained-surface-family"
    });
    let opposite_family_split = family_rows.iter().any(|row| {
        row.surface_family == opposite_family
            && row.surface_family_status == "opposite-direction-split-surface-family"
    });
    let (stress_status, stress_decision, next_experiment_target) = if selected_family_retained
        && opposite_family_split
    {
        (
                "surface-family-contrast-retained-on-fresh-surfaces",
                "surface-family-contrast-fresh-stress-retained-anatomy-next",
                format!(
                    "analyze-surface-family-contrast-anatomy-{selected_family}-{}-vs-{opposite_family}-opposite",
                    picker.source_direction
                ),
            )
    } else if selected_family_retained || opposite_family_split {
        (
            "surface-family-contrast-partial-split-on-fresh-surfaces",
            "surface-family-contrast-fresh-stress-partial-split-record-falsification",
            "select-new-cohort-invariant-surface-after-surface-family-contrast-partial-split"
                .to_string(),
        )
    } else {
        (
            "surface-family-contrast-collapsed-on-fresh-surfaces",
            "surface-family-contrast-fresh-stress-collapsed-record-falsification",
            "select-new-cohort-invariant-surface-after-surface-family-contrast-collapse"
                .to_string(),
        )
    };

    Some(ConnectorWidth6PairFamilyGapCohortSurfaceFamilyContrastStress {
        selection_rule:
            "stress-test the selected gap-family versus size-family directional contrast on disjoint generated gap44/46/48 and gap8 size520k/560k/600k surfaces before residue profiling or theorem work"
                .to_string(),
        source_route_status: picker.contrast_status.clone(),
        source_direction: picker.source_direction.clone(),
        source_connector_count: picker.source_connector_count,
        source_selected_family: selected_family,
        source_opposite_family: opposite_family,
        source_target: picker.next_experiment_target.clone(),
        surface_count: surface_rows.len(),
        surface_family_count: family_rows.len(),
        pair_family_count: pair_families.len(),
        connector_surface_row_count: connector_surface_rows.len(),
        family_window_row_count: family_window_rows.len(),
        retained_family_count,
        split_family_count,
        mixed_family_count,
        retained_surface_count,
        split_surface_count,
        mixed_surface_count,
        retained_connector_total,
        opposite_connector_total,
        neutral_connector_total,
        retained_window_total,
        opposite_window_total,
        neutral_window_total,
        signed_hit_delta_total,
        absolute_hit_delta_total,
        stress_status: stress_status.to_string(),
        stress_decision: stress_decision.to_string(),
        next_experiment_target,
        family_rows,
        surface_rows,
        connector_surface_rows,
        family_window_rows,
    })
}

fn positive_margin(left: usize, right: usize) -> usize {
    left.saturating_sub(right)
}

fn build_surface_family_contrast_anatomy_row(
    selected_direction: &str,
    selected_family: &str,
    opposite_family: &str,
    rows: &[ConnectorWidth6SignPersistenceSurfaceRow],
) -> Option<ConnectorWidth6SurfaceFamilyContrastAnatomyRow> {
    let gap_row = rows
        .iter()
        .find(|row| surface_family_for_contrast(&row.surface_id) == selected_family)?;
    let size_row = rows
        .iter()
        .find(|row| surface_family_for_contrast(&row.surface_id) == opposite_family)?;
    let (gap_retained, gap_opposite) =
        volatility_window_counts_for_direction(gap_row, selected_direction);
    let (size_retained, size_opposite) =
        volatility_window_counts_for_direction(size_row, selected_direction);
    let gap_driver_score = if gap_row.surface_direction == selected_direction {
        positive_margin(gap_retained, gap_opposite)
    } else {
        0
    };
    let size_driver_score = if size_row.surface_direction != "none"
        && size_row.surface_direction != selected_direction
    {
        positive_margin(size_opposite, size_retained)
    } else {
        0
    };
    let total_driver_score = gap_driver_score + size_driver_score;
    let contrast_role = match (gap_driver_score > 0, size_driver_score > 0) {
        (true, true) => "full-gap-retained-size-opposed-driver",
        (true, false) => "gap-family-retention-driver",
        (false, true) => "size-family-opposition-driver",
        (false, false) => "neutral-or-mixed-contrast-row",
    };

    Some(ConnectorWidth6SurfaceFamilyContrastAnatomyRow {
        anatomy_rank: 0,
        width: gap_row.width,
        connector: gap_row.connector.clone(),
        connector_label: volatility_connector_label(gap_row.width, &gap_row.connector),
        gap_surface_direction: gap_row.surface_direction.clone(),
        size_surface_direction: size_row.surface_direction.clone(),
        gap_retained_window_count: gap_retained,
        gap_opposite_window_count: gap_opposite,
        gap_neutral_window_count: gap_row.neutral_window_count,
        size_retained_window_count: size_retained,
        size_opposite_window_count: size_opposite,
        size_neutral_window_count: size_row.neutral_window_count,
        gap_driver_score,
        size_driver_score,
        total_driver_score,
        gap_absolute_delta: gap_row.absolute_hit_delta_total,
        size_absolute_delta: size_row.absolute_hit_delta_total,
        contrast_role: contrast_role.to_string(),
    })
}

fn build_pair_family_gap_cohort_surface_family_contrast_anatomy(
    stress: Option<&ConnectorWidth6PairFamilyGapCohortSurfaceFamilyContrastStress>,
) -> Option<ConnectorWidth6PairFamilyGapCohortSurfaceFamilyContrastAnatomy> {
    let stress = stress?;
    if stress.next_experiment_target
        != "analyze-surface-family-contrast-anatomy-gap-family-forward-vs-size-family-opposite"
    {
        return None;
    }

    let mut grouped_rows: BTreeMap<String, Vec<ConnectorWidth6SignPersistenceSurfaceRow>> =
        BTreeMap::new();
    for row in &stress.connector_surface_rows {
        grouped_rows
            .entry(volatility_connector_label(row.width, &row.connector))
            .or_default()
            .push(row.clone());
    }
    let mut rows = grouped_rows
        .values()
        .filter_map(|rows| {
            build_surface_family_contrast_anatomy_row(
                &stress.source_direction,
                &stress.source_selected_family,
                &stress.source_opposite_family,
                rows,
            )
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        let left_full = left.contrast_role == "full-gap-retained-size-opposed-driver";
        let right_full = right.contrast_role == "full-gap-retained-size-opposed-driver";
        right_full
            .cmp(&left_full)
            .then_with(|| right.total_driver_score.cmp(&left.total_driver_score))
            .then_with(|| right.gap_driver_score.cmp(&left.gap_driver_score))
            .then_with(|| right.size_driver_score.cmp(&left.size_driver_score))
            .then_with(|| left.width.cmp(&right.width))
            .then_with(|| left.connector.cmp(&right.connector))
    });
    for (index, row) in rows.iter_mut().enumerate() {
        row.anatomy_rank = index + 1;
    }

    let full_contrast_driver_count = rows
        .iter()
        .filter(|row| row.contrast_role == "full-gap-retained-size-opposed-driver")
        .count();
    let gap_only_driver_count = rows
        .iter()
        .filter(|row| row.contrast_role == "gap-family-retention-driver")
        .count();
    let size_only_driver_count = rows
        .iter()
        .filter(|row| row.contrast_role == "size-family-opposition-driver")
        .count();
    let neutral_or_mixed_count = rows
        .iter()
        .filter(|row| row.contrast_role == "neutral-or-mixed-contrast-row")
        .count();
    let total_driver_score = rows.iter().map(|row| row.total_driver_score).sum();
    let top_driver_score = rows
        .first()
        .map(|row| row.total_driver_score)
        .unwrap_or_default();
    let top_driver_share_basis_points = if total_driver_score == 0 {
        0
    } else {
        (top_driver_score * 10_000 + total_driver_score / 2) / total_driver_score
    };
    let concentration_status =
        if full_contrast_driver_count >= 3 && top_driver_share_basis_points <= 4_000 {
            "distributed-full-driver-cohort"
        } else if full_contrast_driver_count >= 2 && top_driver_share_basis_points <= 5_500 {
            "moderately-concentrated-full-driver-cohort"
        } else if top_driver_score > 0 {
            "top-driver-concentrated-contrast"
        } else {
            "no-clear-driver-cohort"
        };
    let (anatomy_decision, next_experiment_target) = match concentration_status {
        "distributed-full-driver-cohort" => (
            "surface-family-contrast-anatomy-found-distributed-driver-cohort",
            format!(
                "stress-test-surface-family-contrast-driver-cohort-distributed-{}-{}-vs-{}-opposite",
                stress.source_selected_family, stress.source_direction, stress.source_opposite_family
            ),
        ),
        "moderately-concentrated-full-driver-cohort" => (
            "surface-family-contrast-anatomy-found-moderately-concentrated-driver-cohort",
            format!(
                "stress-test-surface-family-contrast-driver-cohort-moderate-{}-{}-vs-{}-opposite",
                stress.source_selected_family, stress.source_direction, stress.source_opposite_family
            ),
        ),
        "top-driver-concentrated-contrast" => {
            let top = rows.first()?;
            (
                "surface-family-contrast-anatomy-found-top-driver-concentration",
                format!(
                    "stress-test-surface-family-contrast-top-driver-width{}-connector-{}",
                    top.width, top.connector
                ),
            )
        }
        _ => (
            "surface-family-contrast-anatomy-found-no-clear-driver-cohort",
            "select-new-cohort-invariant-surface-after-surface-family-contrast-anatomy-null"
                .to_string(),
        ),
    };

    Some(ConnectorWidth6PairFamilyGapCohortSurfaceFamilyContrastAnatomy {
        selection_rule:
            "rank selected-ensemble connectors by whether they jointly drive gap-family forward retention and size-family opposition after the retained contrast stress"
                .to_string(),
        source_status: stress.stress_status.clone(),
        source_direction: stress.source_direction.clone(),
        source_connector_count: stress.source_connector_count,
        source_selected_family: stress.source_selected_family.clone(),
        source_opposite_family: stress.source_opposite_family.clone(),
        source_target: stress.next_experiment_target.clone(),
        connector_count: rows.len(),
        full_contrast_driver_count,
        gap_only_driver_count,
        size_only_driver_count,
        neutral_or_mixed_count,
        total_driver_score,
        top_driver_score,
        top_driver_share_basis_points,
        concentration_status: concentration_status.to_string(),
        anatomy_decision: anatomy_decision.to_string(),
        next_experiment_target,
        rows,
    })
}

fn surface_family_driver_cohort_stress_surface_specs() -> Vec<(
    &'static str,
    Vec<(&'static str, Vec<PairCase>, Vec<PairCase>, Vec<PairCase>)>,
)> {
    let (gap50_source, gap50_fresh, gap50_separator) = connector_gap50_generated_pair_cases();
    let (gap52_source, gap52_fresh, gap52_separator) = connector_gap52_generated_pair_cases();
    let (gap54_source, gap54_fresh, gap54_separator) = connector_gap54_generated_pair_cases();
    let (size640_source, size640_fresh, size640_separator) =
        connector_gap8_size640k_generated_pair_cases();
    let (size680_source, size680_fresh, size680_separator) =
        connector_gap8_size680k_generated_pair_cases();
    let (size720_source, size720_fresh, size720_separator) =
        connector_gap8_size720k_generated_pair_cases();

    vec![
        (
            "fresh-driver-generated-gap-family",
            vec![
                ("prime-gap50", gap50_source, gap50_fresh, gap50_separator),
                ("prime-gap52", gap52_source, gap52_fresh, gap52_separator),
                ("prime-gap54", gap54_source, gap54_fresh, gap54_separator),
            ],
        ),
        (
            "fresh-driver-generated-gap8-size-family",
            vec![
                (
                    "prime-gap8-size640k",
                    size640_source,
                    size640_fresh,
                    size640_separator,
                ),
                (
                    "prime-gap8-size680k",
                    size680_source,
                    size680_fresh,
                    size680_separator,
                ),
                (
                    "prime-gap8-size720k",
                    size720_source,
                    size720_fresh,
                    size720_separator,
                ),
            ],
        ),
    ]
}

fn build_pair_family_gap_cohort_surface_family_driver_cohort_stress(
    anatomy: Option<&ConnectorWidth6PairFamilyGapCohortSurfaceFamilyContrastAnatomy>,
) -> Option<ConnectorWidth6PairFamilyGapCohortSurfaceFamilyDriverCohortStress> {
    let anatomy = anatomy?;
    if anatomy.next_experiment_target
        != "stress-test-surface-family-contrast-driver-cohort-distributed-gap-family-forward-vs-size-family-opposite"
    {
        return None;
    }

    let driver_rows = anatomy
        .rows
        .iter()
        .filter(|row| row.contrast_role == "full-gap-retained-size-opposed-driver")
        .collect::<Vec<_>>();
    if driver_rows.len() != 4 {
        return None;
    }
    let driver_connectors = driver_rows
        .iter()
        .map(|row| volatility_connector_label(row.width, &row.connector))
        .collect::<Vec<_>>();
    let driver_specs = driver_rows
        .iter()
        .map(|row| (row.width, row.connector.clone()))
        .collect::<Vec<_>>();
    let stress_surfaces = surface_family_driver_cohort_stress_surface_specs();
    let mut surface_rows = Vec::new();
    let mut connector_surface_rows = Vec::new();
    let mut family_window_rows = Vec::new();
    let mut pair_families = BTreeSet::new();

    for (surface_id, families) in stress_surfaces {
        let pair_family_names = families
            .iter()
            .map(|(pair_family, _, _, _)| *pair_family)
            .collect::<Vec<_>>();
        let mut surface_connector_rows = Vec::new();

        for (width, connector) in &driver_specs {
            let connector_value = connector.parse::<u128>().ok()?;
            let mut connector_family_rows = Vec::new();
            for (pair_family, source_pairs, fresh_pairs, separator_pairs) in &families {
                pair_families.insert((*pair_family).to_string());
                let rows = build_window_consensus_stress_family_rows(
                    pair_family,
                    *width,
                    connector_value,
                    connector,
                    source_pairs.clone(),
                    fresh_pairs.clone(),
                    separator_pairs.clone(),
                )?;
                connector_family_rows.extend(rows.clone());
                family_window_rows.extend(rows);
            }
            let surface_row = build_sign_persistence_surface_row(
                *width,
                connector,
                surface_id,
                &pair_family_names,
                &connector_family_rows,
            )?;
            surface_connector_rows.push(surface_row.clone());
            connector_surface_rows.push(surface_row);
        }

        surface_rows.push(build_surface_family_contrast_surface_row(
            surface_id,
            &anatomy.source_direction,
            &surface_connector_rows,
        ));
    }
    surface_rows.sort_by(|left, right| left.surface_id.cmp(&right.surface_id));

    let mut family_groups: BTreeMap<String, Vec<ConnectorWidth6SurfaceFamilyContrastSurfaceRow>> =
        BTreeMap::new();
    for row in &surface_rows {
        family_groups
            .entry(row.surface_family.clone())
            .or_default()
            .push(row.clone());
    }
    let mut family_rows = family_groups
        .iter()
        .map(|(surface_family, rows)| {
            build_surface_family_contrast_family_row(surface_family, rows)
        })
        .collect::<Vec<_>>();
    family_rows.sort_by(|left, right| left.surface_family.cmp(&right.surface_family));

    let retained_family_count = family_rows
        .iter()
        .filter(|row| row.surface_family_status == "selected-direction-retained-surface-family")
        .count();
    let split_family_count = family_rows
        .iter()
        .filter(|row| row.surface_family_status == "opposite-direction-split-surface-family")
        .count();
    let mixed_family_count = family_rows.len() - retained_family_count - split_family_count;
    let retained_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_status == "selected-direction-retained-surface")
        .count();
    let split_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_status == "opposite-direction-split-surface")
        .count();
    let mixed_surface_count = surface_rows.len() - retained_surface_count - split_surface_count;
    let retained_connector_total = family_rows
        .iter()
        .map(|row| row.retained_connector_total)
        .sum();
    let opposite_connector_total = family_rows
        .iter()
        .map(|row| row.opposite_connector_total)
        .sum();
    let neutral_connector_total = family_rows
        .iter()
        .map(|row| row.neutral_connector_total)
        .sum();
    let retained_window_total = family_rows
        .iter()
        .map(|row| row.retained_window_total)
        .sum();
    let opposite_window_total = family_rows
        .iter()
        .map(|row| row.opposite_window_total)
        .sum();
    let neutral_window_total = family_rows.iter().map(|row| row.neutral_window_total).sum();
    let signed_hit_delta_total = family_rows
        .iter()
        .map(|row| row.signed_hit_delta_total)
        .sum();
    let absolute_hit_delta_total = family_rows
        .iter()
        .map(|row| row.absolute_hit_delta_total)
        .sum();

    let selected_family_retained = family_rows.iter().any(|row| {
        row.surface_family == anatomy.source_selected_family
            && row.surface_family_status == "selected-direction-retained-surface-family"
    });
    let selected_family_split = family_rows.iter().any(|row| {
        row.surface_family == anatomy.source_selected_family
            && row.surface_family_status == "opposite-direction-split-surface-family"
    });
    let opposite_family_split = family_rows.iter().any(|row| {
        row.surface_family == anatomy.source_opposite_family
            && row.surface_family_status == "opposite-direction-split-surface-family"
    });
    let (stress_status, stress_decision, next_experiment_target) =
        if selected_family_retained && opposite_family_split {
            (
                "driver-cohort-contrast-retained-on-fresh-surfaces",
                "driver-cohort-contrast-fresh-stress-retained-anatomy-next",
                "analyze-driver-cohort-contrast-anatomy-after-fresh-retention".to_string(),
            )
        } else if selected_family_split || opposite_family_split || split_family_count > 0 {
            (
                "driver-cohort-contrast-split-on-fresh-surfaces",
                "driver-cohort-contrast-fresh-stress-split-record-falsification",
                "select-new-cohort-invariant-surface-after-driver-cohort-contrast-fresh-split"
                    .to_string(),
            )
        } else {
            (
                "driver-cohort-contrast-collapsed-on-fresh-surfaces",
                "driver-cohort-contrast-fresh-stress-collapsed-record-falsification",
                "select-new-cohort-invariant-surface-after-driver-cohort-contrast-fresh-collapse"
                    .to_string(),
            )
        };

    Some(ConnectorWidth6PairFamilyGapCohortSurfaceFamilyDriverCohortStress {
        selection_rule:
            "stress-test the four distributed full contrast drivers on disjoint generated gap50/52/54 and gap8 size640k/680k/720k surfaces before residue profiling or theorem work"
                .to_string(),
        source_status: anatomy.concentration_status.clone(),
        source_direction: anatomy.source_direction.clone(),
        source_selected_family: anatomy.source_selected_family.clone(),
        source_opposite_family: anatomy.source_opposite_family.clone(),
        source_target: anatomy.next_experiment_target.clone(),
        driver_count: driver_connectors.len(),
        driver_connectors,
        surface_count: surface_rows.len(),
        surface_family_count: family_rows.len(),
        pair_family_count: pair_families.len(),
        connector_surface_row_count: connector_surface_rows.len(),
        family_window_row_count: family_window_rows.len(),
        retained_family_count,
        split_family_count,
        mixed_family_count,
        retained_surface_count,
        split_surface_count,
        mixed_surface_count,
        retained_connector_total,
        opposite_connector_total,
        neutral_connector_total,
        retained_window_total,
        opposite_window_total,
        neutral_window_total,
        signed_hit_delta_total,
        absolute_hit_delta_total,
        stress_status: stress_status.to_string(),
        stress_decision: stress_decision.to_string(),
        next_experiment_target,
        family_rows,
        surface_rows,
        connector_surface_rows,
        family_window_rows,
    })
}

fn matched_nondriver_control_specs(
    anatomy: &ConnectorWidth6PairFamilyGapCohortSurfaceFamilyContrastAnatomy,
) -> Option<Vec<(u32, String)>> {
    let driver_rows = anatomy
        .rows
        .iter()
        .filter(|row| row.contrast_role == "full-gap-retained-size-opposed-driver")
        .collect::<Vec<_>>();
    if driver_rows.len() != 4 {
        return None;
    }
    let non_driver_rows = anatomy
        .rows
        .iter()
        .filter(|row| row.contrast_role != "full-gap-retained-size-opposed-driver")
        .collect::<Vec<_>>();
    let mut used = BTreeSet::new();
    let mut controls = Vec::new();

    for driver in driver_rows {
        let same_width = non_driver_rows
            .iter()
            .filter(|row| row.width == driver.width)
            .find(|row| used.insert(row.connector_label.clone()))
            .map(|row| (row.width, row.connector.clone()));
        if let Some(control) = same_width {
            controls.push(control);
            continue;
        }

        let fallback = non_driver_rows
            .iter()
            .find(|row| used.insert(row.connector_label.clone()))
            .map(|row| (row.width, row.connector.clone()))?;
        controls.push(fallback);
    }

    Some(controls)
}

fn build_pair_family_gap_cohort_surface_family_matched_nondriver_control_stress(
    anatomy: Option<&ConnectorWidth6PairFamilyGapCohortSurfaceFamilyContrastAnatomy>,
    driver_stress: Option<&ConnectorWidth6PairFamilyGapCohortSurfaceFamilyDriverCohortStress>,
) -> Option<ConnectorWidth6PairFamilyGapCohortSurfaceFamilyMatchedNonDriverControlStress> {
    let anatomy = anatomy?;
    let driver_stress = driver_stress?;
    if driver_stress.next_experiment_target
        != "select-new-cohort-invariant-surface-after-driver-cohort-contrast-fresh-split"
    {
        return None;
    }
    let control_specs = matched_nondriver_control_specs(anatomy)?;
    let control_connectors = control_specs
        .iter()
        .map(|(width, connector)| volatility_connector_label(*width, connector))
        .collect::<Vec<_>>();
    let stress_surfaces = surface_family_driver_cohort_stress_surface_specs();
    let mut surface_rows = Vec::new();
    let mut connector_surface_rows = Vec::new();
    let mut family_window_rows = Vec::new();
    let mut pair_families = BTreeSet::new();

    for (surface_id, families) in stress_surfaces {
        let pair_family_names = families
            .iter()
            .map(|(pair_family, _, _, _)| *pair_family)
            .collect::<Vec<_>>();
        let mut surface_connector_rows = Vec::new();

        for (width, connector) in &control_specs {
            let connector_value = connector.parse::<u128>().ok()?;
            let mut connector_family_rows = Vec::new();
            for (pair_family, source_pairs, fresh_pairs, separator_pairs) in &families {
                pair_families.insert((*pair_family).to_string());
                let rows = build_window_consensus_stress_family_rows(
                    pair_family,
                    *width,
                    connector_value,
                    connector,
                    source_pairs.clone(),
                    fresh_pairs.clone(),
                    separator_pairs.clone(),
                )?;
                connector_family_rows.extend(rows.clone());
                family_window_rows.extend(rows);
            }
            let surface_row = build_sign_persistence_surface_row(
                *width,
                connector,
                surface_id,
                &pair_family_names,
                &connector_family_rows,
            )?;
            surface_connector_rows.push(surface_row.clone());
            connector_surface_rows.push(surface_row);
        }

        surface_rows.push(build_surface_family_contrast_surface_row(
            surface_id,
            &driver_stress.source_direction,
            &surface_connector_rows,
        ));
    }
    surface_rows.sort_by(|left, right| left.surface_id.cmp(&right.surface_id));

    let mut family_groups: BTreeMap<String, Vec<ConnectorWidth6SurfaceFamilyContrastSurfaceRow>> =
        BTreeMap::new();
    for row in &surface_rows {
        family_groups
            .entry(row.surface_family.clone())
            .or_default()
            .push(row.clone());
    }
    let mut family_rows = family_groups
        .iter()
        .map(|(surface_family, rows)| {
            build_surface_family_contrast_family_row(surface_family, rows)
        })
        .collect::<Vec<_>>();
    family_rows.sort_by(|left, right| left.surface_family.cmp(&right.surface_family));

    let retained_family_count = family_rows
        .iter()
        .filter(|row| row.surface_family_status == "selected-direction-retained-surface-family")
        .count();
    let split_family_count = family_rows
        .iter()
        .filter(|row| row.surface_family_status == "opposite-direction-split-surface-family")
        .count();
    let mixed_family_count = family_rows.len() - retained_family_count - split_family_count;
    let retained_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_status == "selected-direction-retained-surface")
        .count();
    let split_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_status == "opposite-direction-split-surface")
        .count();
    let mixed_surface_count = surface_rows.len() - retained_surface_count - split_surface_count;
    let retained_connector_total = family_rows
        .iter()
        .map(|row| row.retained_connector_total)
        .sum();
    let opposite_connector_total = family_rows
        .iter()
        .map(|row| row.opposite_connector_total)
        .sum();
    let neutral_connector_total = family_rows
        .iter()
        .map(|row| row.neutral_connector_total)
        .sum();
    let retained_window_total = family_rows
        .iter()
        .map(|row| row.retained_window_total)
        .sum();
    let opposite_window_total = family_rows
        .iter()
        .map(|row| row.opposite_window_total)
        .sum();
    let neutral_window_total = family_rows.iter().map(|row| row.neutral_window_total).sum();
    let signed_hit_delta_total = family_rows
        .iter()
        .map(|row| row.signed_hit_delta_total)
        .sum();
    let absolute_hit_delta_total = family_rows
        .iter()
        .map(|row| row.absolute_hit_delta_total)
        .sum();

    let control_status = if split_family_count > 0 && retained_family_count == 0 {
        "matched-nondriver-control-split-on-fresh-surfaces"
    } else if split_family_count > 0 && retained_family_count > 0 {
        "matched-nondriver-control-mixed-split-on-fresh-surfaces"
    } else if retained_family_count > 0 {
        "matched-nondriver-control-retained-on-fresh-surfaces"
    } else {
        "matched-nondriver-control-collapsed-on-fresh-surfaces"
    };
    let (control_decision, next_experiment_target) = match control_status {
        "matched-nondriver-control-split-on-fresh-surfaces"
        | "matched-nondriver-control-mixed-split-on-fresh-surfaces" => (
            "matched-nondriver-control-also-split-record-broad-surface-falsification",
            "select-new-cohort-invariant-surface-after-driver-and-nondriver-fresh-split"
                .to_string(),
        ),
        "matched-nondriver-control-retained-on-fresh-surfaces" => (
            "matched-nondriver-control-retained-driver-specific-split-analysis-next",
            "analyze-driver-specific-fresh-split-against-matched-nondriver-control".to_string(),
        ),
        _ => (
            "matched-nondriver-control-collapsed-record-falsification",
            "select-new-cohort-invariant-surface-after-driver-split-control-collapse".to_string(),
        ),
    };

    Some(ConnectorWidth6PairFamilyGapCohortSurfaceFamilyMatchedNonDriverControlStress {
        selection_rule:
            "match each full contrast driver to the highest-ranked unused non-driver at the same width, then stress-test the matched control cohort on the same fresh generated surfaces"
                .to_string(),
        source_driver_stress_status: driver_stress.stress_status.clone(),
        source_driver_stress_decision: driver_stress.stress_decision.clone(),
        source_direction: driver_stress.source_direction.clone(),
        source_target: driver_stress.next_experiment_target.clone(),
        driver_count: driver_stress.driver_count,
        driver_connectors: driver_stress.driver_connectors.clone(),
        control_count: control_connectors.len(),
        control_connectors,
        surface_count: surface_rows.len(),
        surface_family_count: family_rows.len(),
        pair_family_count: pair_families.len(),
        connector_surface_row_count: connector_surface_rows.len(),
        family_window_row_count: family_window_rows.len(),
        retained_family_count,
        split_family_count,
        mixed_family_count,
        retained_surface_count,
        split_surface_count,
        mixed_surface_count,
        retained_connector_total,
        opposite_connector_total,
        neutral_connector_total,
        retained_window_total,
        opposite_window_total,
        neutral_window_total,
        signed_hit_delta_total,
        absolute_hit_delta_total,
        control_status: control_status.to_string(),
        control_decision: control_decision.to_string(),
        next_experiment_target,
        family_rows,
        surface_rows,
        connector_surface_rows,
        family_window_rows,
    })
}

fn build_surface_agnostic_candidate_row(
    width: u32,
    connector: &str,
    surface_rows: &[ConnectorWidth6SignPersistenceSurfaceRow],
) -> ConnectorWidth6SurfaceAgnosticCandidateRow {
    let reverse_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_direction == "reverse")
        .count();
    let forward_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_direction == "forward")
        .count();
    let neutral_surface_count = surface_rows
        .iter()
        .filter(|row| row.surface_direction == "none")
        .count();
    let (retained_direction, retained_surface_count, opposite_surface_count) =
        match reverse_surface_count.cmp(&forward_surface_count) {
            std::cmp::Ordering::Greater => {
                ("reverse", reverse_surface_count, forward_surface_count)
            }
            std::cmp::Ordering::Less => ("forward", forward_surface_count, reverse_surface_count),
            std::cmp::Ordering::Equal => ("none", 0, 0),
        };
    let retained_window_count = surface_rows
        .iter()
        .map(|row| volatility_window_counts_for_direction(row, retained_direction).0)
        .sum();
    let opposite_window_count = surface_rows
        .iter()
        .map(|row| volatility_window_counts_for_direction(row, retained_direction).1)
        .sum();
    let neutral_window_count = surface_rows
        .iter()
        .map(|row| row.neutral_window_count)
        .sum();
    let signed_hit_delta_total = surface_rows
        .iter()
        .map(|row| row.signed_hit_delta_total)
        .sum();
    let absolute_hit_delta_total = surface_rows
        .iter()
        .map(|row| row.absolute_hit_delta_total)
        .sum();
    let volatility_score =
        opposite_surface_count * 100 + neutral_surface_count * 25 + opposite_window_count;
    let stability_status = if retained_direction != "none"
        && retained_surface_count >= 8
        && opposite_surface_count <= 2
    {
        "stable-surface-agnostic-direction"
    } else if retained_direction != "none" && retained_surface_count >= 6 {
        "mixed-surface-agnostic-direction"
    } else {
        "no-surface-agnostic-direction"
    };
    let next_experiment_target = if stability_status == "stable-surface-agnostic-direction" {
        format!(
            "stress-test-surface-agnostic-candidate-width{width}-connector-{connector}-direction-{retained_direction}"
        )
    } else {
        format!(
            "do-not-promote-surface-agnostic-width{width}-connector-{connector}-without-8-of-12-stability"
        )
    };

    ConnectorWidth6SurfaceAgnosticCandidateRow {
        candidate_rank: 0,
        width,
        connector: connector.to_string(),
        connector_label: volatility_connector_label(width, connector),
        retained_direction: retained_direction.to_string(),
        reverse_surface_count,
        forward_surface_count,
        retained_surface_count,
        opposite_surface_count,
        neutral_surface_count,
        retained_window_count,
        opposite_window_count,
        neutral_window_count,
        signed_hit_delta_total,
        absolute_hit_delta_total,
        volatility_score,
        stability_status: stability_status.to_string(),
        next_experiment_target,
    }
}

fn build_surface_agnostic_ensemble_row(
    direction: &str,
    candidates: &[ConnectorWidth6SurfaceAgnosticCandidateRow],
) -> ConnectorWidth6SurfaceAgnosticEnsembleRow {
    let stable_candidates = candidates
        .iter()
        .filter(|row| {
            row.stability_status == "stable-surface-agnostic-direction"
                && row.retained_direction == direction
        })
        .collect::<Vec<_>>();
    let selected_connectors = stable_candidates
        .iter()
        .map(|row| row.connector_label.clone())
        .collect::<Vec<_>>();
    let connector_count = selected_connectors.len();
    let stable_surface_total = stable_candidates
        .iter()
        .map(|row| row.retained_surface_count)
        .sum();
    let retained_window_total = stable_candidates
        .iter()
        .map(|row| row.retained_window_count)
        .sum();
    let opposite_window_total = stable_candidates
        .iter()
        .map(|row| row.opposite_window_count)
        .sum();
    let neutral_window_total = stable_candidates
        .iter()
        .map(|row| row.neutral_window_count)
        .sum();
    let signed_hit_delta_total = stable_candidates
        .iter()
        .map(|row| row.signed_hit_delta_total)
        .sum();
    let absolute_hit_delta_total = stable_candidates
        .iter()
        .map(|row| row.absolute_hit_delta_total)
        .sum();
    let ensemble_status = if connector_count >= 3 {
        "surface-agnostic-ensemble-qualified"
    } else {
        "surface-agnostic-ensemble-below-three-connector-threshold"
    };
    let next_experiment_target = if ensemble_status == "surface-agnostic-ensemble-qualified" {
        format!("stress-test-surface-agnostic-ensemble-direction-{direction}-connector-count-{connector_count}")
    } else {
        format!(
            "do-not-promote-surface-agnostic-ensemble-direction-{direction}-without-three-stable-connectors"
        )
    };

    ConnectorWidth6SurfaceAgnosticEnsembleRow {
        ensemble_rank: 0,
        direction: direction.to_string(),
        connector_count,
        stable_surface_total,
        selected_connectors,
        retained_window_total,
        opposite_window_total,
        neutral_window_total,
        signed_hit_delta_total,
        absolute_hit_delta_total,
        ensemble_status: ensemble_status.to_string(),
        next_experiment_target,
    }
}

fn build_pair_family_gap_cohort_surface_agnostic_ensemble_picker(
    matched_nondriver_stress: Option<
        &ConnectorWidth6PairFamilyGapCohortSurfaceFamilyMatchedNonDriverControlStress,
    >,
) -> Option<ConnectorWidth6PairFamilyGapCohortSurfaceAgnosticEnsemblePicker> {
    let matched_nondriver_stress = matched_nondriver_stress?;
    if matched_nondriver_stress.next_experiment_target
        != "select-new-cohort-invariant-surface-after-driver-and-nondriver-fresh-split"
    {
        return None;
    }

    let surfaces = surface_agnostic_ensemble_surface_specs();
    let surface_names = surfaces
        .iter()
        .map(|(surface_id, _)| (*surface_id).to_string())
        .collect::<Vec<_>>();
    let mut candidate_rows = Vec::new();
    let mut surface_rows = Vec::new();
    let mut family_rows = Vec::new();
    let mut pair_families = BTreeSet::new();

    for (width, connector_value) in pair_family_gap_portfolio_connector_values() {
        let connector = format!("{connector_value:0width$}", width = width as usize);
        let mut connector_surface_rows = Vec::new();
        for (surface_id, families) in &surfaces {
            let pair_family_names = families
                .iter()
                .map(|(pair_family, _, _, _)| *pair_family)
                .collect::<Vec<_>>();
            let mut surface_family_rows = Vec::new();
            for (pair_family, source_pairs, fresh_pairs, separator_pairs) in families {
                pair_families.insert((*pair_family).to_string());
                let rows = build_window_consensus_stress_family_rows(
                    pair_family,
                    width,
                    connector_value,
                    &connector,
                    source_pairs.clone(),
                    fresh_pairs.clone(),
                    separator_pairs.clone(),
                )?;
                surface_family_rows.extend(rows.clone());
                family_rows.extend(rows);
            }
            let surface_row = build_sign_persistence_surface_row(
                width,
                &connector,
                surface_id,
                &pair_family_names,
                &surface_family_rows,
            )?;
            connector_surface_rows.push(surface_row.clone());
            surface_rows.push(surface_row);
        }
        candidate_rows.push(build_surface_agnostic_candidate_row(
            width,
            &connector,
            &connector_surface_rows,
        ));
    }

    candidate_rows.sort_by(|left, right| {
        let left_stable = left.stability_status == "stable-surface-agnostic-direction";
        let right_stable = right.stability_status == "stable-surface-agnostic-direction";
        right_stable
            .cmp(&left_stable)
            .then_with(|| {
                ratio_geometry_picker_direction_priority(&left.retained_direction).cmp(
                    &ratio_geometry_picker_direction_priority(&right.retained_direction),
                )
            })
            .then_with(|| {
                right
                    .retained_surface_count
                    .cmp(&left.retained_surface_count)
            })
            .then_with(|| {
                left.opposite_surface_count
                    .cmp(&right.opposite_surface_count)
            })
            .then_with(|| left.volatility_score.cmp(&right.volatility_score))
            .then_with(|| right.retained_window_count.cmp(&left.retained_window_count))
            .then_with(|| {
                right
                    .absolute_hit_delta_total
                    .cmp(&left.absolute_hit_delta_total)
            })
            .then_with(|| left.width.cmp(&right.width))
            .then_with(|| left.connector.cmp(&right.connector))
    });
    for (index, row) in candidate_rows.iter_mut().enumerate() {
        row.candidate_rank = index + 1;
    }

    let stable_connector_count = candidate_rows
        .iter()
        .filter(|row| row.stability_status == "stable-surface-agnostic-direction")
        .count();
    let mut ensemble_rows = vec![
        build_surface_agnostic_ensemble_row("reverse", &candidate_rows),
        build_surface_agnostic_ensemble_row("forward", &candidate_rows),
    ];
    ensemble_rows.sort_by(|left, right| {
        let left_qualifies = left.ensemble_status == "surface-agnostic-ensemble-qualified";
        let right_qualifies = right.ensemble_status == "surface-agnostic-ensemble-qualified";
        right_qualifies
            .cmp(&left_qualifies)
            .then_with(|| right.connector_count.cmp(&left.connector_count))
            .then_with(|| right.stable_surface_total.cmp(&left.stable_surface_total))
            .then_with(|| left.opposite_window_total.cmp(&right.opposite_window_total))
            .then_with(|| {
                right
                    .absolute_hit_delta_total
                    .cmp(&left.absolute_hit_delta_total)
            })
            .then_with(|| {
                ratio_geometry_picker_direction_priority(&left.direction)
                    .cmp(&ratio_geometry_picker_direction_priority(&right.direction))
            })
            .then_with(|| left.selected_connectors.cmp(&right.selected_connectors))
    });
    for (index, row) in ensemble_rows.iter_mut().enumerate() {
        row.ensemble_rank = index + 1;
    }
    let qualifying_ensemble_count = ensemble_rows
        .iter()
        .filter(|row| row.ensemble_status == "surface-agnostic-ensemble-qualified")
        .count();
    let selected_ensemble = ensemble_rows
        .iter()
        .find(|row| row.ensemble_status == "surface-agnostic-ensemble-qualified")
        .cloned();
    let picker_decision = if selected_ensemble.is_some() {
        "surface-agnostic-ensemble-picker-selected-stable-mixed-surface-cohort"
    } else {
        "surface-agnostic-ensemble-picker-found-no-stable-mixed-surface-cohort"
    };
    let next_experiment_target = selected_ensemble
        .as_ref()
        .map(|row| row.next_experiment_target.clone())
        .unwrap_or_else(|| {
            "select-new-cohort-invariant-surface-after-surface-agnostic-ensemble-picker-collapse"
                .to_string()
        });

    surface_rows.sort_by(|left, right| {
        volatility_connector_label(left.width, &left.connector)
            .cmp(&volatility_connector_label(right.width, &right.connector))
            .then_with(|| left.surface_id.cmp(&right.surface_id))
    });
    family_rows.sort_by(|left, right| {
        left.width
            .cmp(&right.width)
            .then_with(|| left.connector.cmp(&right.connector))
            .then_with(|| left.pair_family.cmp(&right.pair_family))
            .then_with(|| left.stage.cmp(&right.stage))
    });

    Some(ConnectorWidth6PairFamilyGapCohortSurfaceAgnosticEnsemblePicker {
        selection_rule:
            "after broad driver and matched-nondriver fresh split, scan the frozen connector portfolio across twelve mixed gap and size surfaces; stable means one non-neutral direction appears on at least 8 of 12 surfaces with at most 2 opposite surfaces"
                .to_string(),
        source_route_status: matched_nondriver_stress.control_status.clone(),
        source_target: matched_nondriver_stress.next_experiment_target.clone(),
        candidate_count: candidate_rows.len(),
        stable_connector_count,
        surface_count: surface_names.len(),
        surfaces: surface_names,
        pair_family_count: pair_families.len(),
        window_count: family_rows.len(),
        ensemble_count: ensemble_rows.len(),
        qualifying_ensemble_count,
        selected_ensemble,
        picker_decision: picker_decision.to_string(),
        next_experiment_target,
        candidate_rows,
        ensemble_rows,
        surface_rows,
        family_rows,
    })
}

fn build_pair_family_cohort_residue_separator_replication(
    profile: &ConnectorWidth6PairFamilyCohortResidueProfile,
) -> Option<ConnectorWidth6PairFamilyCohortResidueSeparatorReplication> {
    let separator = profile.best_separator.as_ref()?;
    let connector_value = profile.connector.parse::<u128>().ok()?;
    let mut rows = Vec::new();
    let mut separator_pair_labels = Vec::new();

    for pair_family in &profile.pair_families {
        let pair_cases = connector_pair_family_separator_pair_cases(pair_family)?;
        for case in pair_cases {
            separator_pair_labels.push(case.name.to_string());
            if let Some(row) = build_connector_value_row(
                &case,
                profile.width,
                connector_value,
                &format!("pair-family-cohort-residue-separator-replication-{pair_family}"),
            ) {
                rows.push(row);
            }
        }
    }

    rows.sort_by(|left, right| {
        left.control_family
            .cmp(&right.control_family)
            .then_with(|| left.left.cmp(&right.left))
            .then_with(|| left.right.cmp(&right.right))
    });
    separator_pair_labels.sort();
    separator_pair_labels.dedup();

    let reverse_only_rows = rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .collect::<Vec<_>>();
    let comparison_rows = rows
        .iter()
        .filter(|row| row.contrast_class != "reverse-only-prime-hit")
        .collect::<Vec<_>>();
    let reverse_only_residues = reverse_only_rows
        .iter()
        .map(|row| (row.left % separator.modulus as u128) as u32)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let comparison_residues = comparison_rows
        .iter()
        .map(|row| (row.left % separator.modulus as u128) as u32)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let source_set = separator
        .reverse_only_residues
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    let comparison_set = comparison_residues.iter().copied().collect::<BTreeSet<_>>();
    let reverse_set = reverse_only_residues
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    let shared_residues = reverse_only_residues
        .iter()
        .copied()
        .filter(|residue| comparison_set.contains(residue))
        .collect::<Vec<_>>();
    let retained_residue_count = reverse_only_residues
        .iter()
        .filter(|residue| source_set.contains(residue))
        .count();
    let split_residue_count = reverse_only_residues
        .iter()
        .filter(|residue| !source_set.contains(residue))
        .count();
    let collapsed_residue_count = separator
        .reverse_only_residues
        .iter()
        .filter(|residue| !reverse_set.contains(residue))
        .count();

    let source_retained_exactly = !reverse_only_residues.is_empty()
        && reverse_set == source_set
        && shared_residues.is_empty();
    let separator_status = if reverse_only_residues.is_empty() {
        "collapsed-no-reverse-only-on-cohort-separator-ladders"
    } else if source_retained_exactly {
        "retained-source-residue-separator-on-cohort-separator-ladders"
    } else if shared_residues.is_empty() {
        "split-exact-residue-separator-on-cohort-separator-ladders"
    } else {
        "collapsed-overlapping-residue-classes-on-cohort-separator-ladders"
    };
    let replication_decision = match separator_status {
        "retained-source-residue-separator-on-cohort-separator-ladders" => {
            format!(
                "mod{}-cohort-residue-separator-retained-lean-candidate",
                separator.modulus
            )
        }
        "split-exact-residue-separator-on-cohort-separator-ladders" => {
            format!(
                "mod{}-cohort-residue-separator-mutated-keep-empirical",
                separator.modulus
            )
        }
        _ => format!(
            "mod{}-cohort-residue-separator-collapsed-keep-empirical",
            separator.modulus
        ),
    };
    let next_experiment_target =
        if separator_status == "retained-source-residue-separator-on-cohort-separator-ladders" {
            format!(
                "lean-finite-classifier-candidate-cohort-width{}-connector-{}-mod{}",
                profile.width, profile.connector, separator.modulus
            )
        } else {
            format!(
                "select-new-family-level-replication-surface-after-cohort-{}-separator-collapse",
                profile.connector
            )
        };

    Some(ConnectorWidth6PairFamilyCohortResidueSeparatorReplication {
        selection_rule:
            "test-best-cohort-residue-separator-on-related-pair-family-separator-ladders-before-lean"
                .to_string(),
        cohort_id: profile.cohort_id.clone(),
        width: profile.width,
        connector: profile.connector.clone(),
        pair_families: profile.pair_families.clone(),
        source_branch_ids: profile.source_branch_ids.clone(),
        source_modulus: separator.modulus,
        source_reverse_only_residues: separator.reverse_only_residues.clone(),
        separator_family_count: profile.pair_families.len(),
        separator_pair_count: separator_pair_labels.len(),
        separator_pair_labels,
        row_count: rows.len(),
        reverse_only_pair_count: reverse_only_rows.len(),
        comparison_pair_count: comparison_rows.len(),
        reverse_only_residues,
        comparison_residues,
        shared_residues,
        retained_residue_count,
        split_residue_count,
        collapsed_residue_count,
        separator_status: separator_status.to_string(),
        replication_decision,
        next_experiment_target,
        rows,
    })
}

fn build_pair_family_surface_picker(
    cohort_profile: Option<&ConnectorWidth6PairFamilyCohortResidueProfile>,
    matrices: &[(
        &str,
        &str,
        Option<&ConnectorWidth6OrthogonalPairFamilyControlMatrix>,
    )],
) -> Option<ConnectorWidth6PairFamilySurfacePicker> {
    let cohort_profile = cohort_profile?;
    if cohort_profile.profile_decision != "no-small-prime-cohort-residue-separator-found" {
        return None;
    }

    let mut rows = Vec::new();
    let mut source_surface_count = 0;
    for (surface_id, surface_label, matrix) in matrices {
        let Some(matrix) = matrix else {
            continue;
        };
        source_surface_count += 1;
        let mut pair_families = Vec::new();
        let mut source_branch_ids = Vec::new();
        let mut source_selected_count = 0;
        let mut source_reverse_only_total = 0;
        let mut fresh_survivor_count = 0;
        let mut fresh_reverse_only_total = 0;
        let mut fresh_forward_only_total = 0;

        for family in &matrix.pair_families {
            let Some(selected) = &family.selected_motif else {
                continue;
            };
            let Some(fresh) = &family.fresh_replication else {
                continue;
            };
            pair_families.push(fresh.pair_family.clone());
            source_branch_ids.push(fresh.source_branch_id.clone());
            source_selected_count += 1;
            source_reverse_only_total += selected.reverse_only_pair_count;
            if fresh.reverse_only_pair_count > 0 {
                fresh_survivor_count += 1;
            }
            fresh_reverse_only_total += fresh.reverse_only_pair_count;
            fresh_forward_only_total += fresh.forward_only_pair_count;
        }

        pair_families.sort();
        pair_families.dedup();
        source_branch_ids.sort();
        source_branch_ids.dedup();
        let surface_status = if fresh_survivor_count >= 2 {
            "fresh-family-surface-survived-needs-surface-residue-profile"
        } else if fresh_survivor_count == 1 {
            "single-branch-survived-not-family-surface-ready"
        } else {
            "family-surface-collapsed-on-fresh-ladders"
        };
        let next_experiment_target = if fresh_survivor_count >= 2 {
            format!("surface-residue-profile-{surface_id}-across-selected-branches")
        } else {
            format!("do-not-profile-{surface_id}-without-family-level-retention")
        };

        rows.push(ConnectorWidth6PairFamilySurfaceRow {
            surface_id: (*surface_id).to_string(),
            surface_label: (*surface_label).to_string(),
            pair_families,
            source_branch_ids,
            source_selected_count,
            source_reverse_only_total,
            fresh_survivor_count,
            fresh_reverse_only_total,
            fresh_forward_only_total,
            surface_status: surface_status.to_string(),
            next_experiment_target,
        });
    }

    rows.sort_by(|left, right| {
        right
            .fresh_survivor_count
            .cmp(&left.fresh_survivor_count)
            .then_with(|| {
                right
                    .fresh_reverse_only_total
                    .cmp(&left.fresh_reverse_only_total)
            })
            .then_with(|| {
                right
                    .source_reverse_only_total
                    .cmp(&left.source_reverse_only_total)
            })
            .then_with(|| {
                left.fresh_forward_only_total
                    .cmp(&right.fresh_forward_only_total)
            })
            .then_with(|| left.surface_id.cmp(&right.surface_id))
    });
    let selected_surface = rows
        .iter()
        .find(|row| row.fresh_survivor_count >= 2)
        .cloned();
    let surface_ready_count = rows
        .iter()
        .filter(|row| row.fresh_survivor_count >= 2)
        .count();
    let next_experiment_target = selected_surface
        .as_ref()
        .map(|row| row.next_experiment_target.clone())
        .unwrap_or_else(|| {
            "select-new-family-level-replication-surface-after-family-surface-collapse".to_string()
        });
    let picker_decision = if selected_surface.is_some() {
        "cohort-connector-profile-failed-select-family-level-pair-surface"
    } else {
        "no-family-level-pair-surface-retention-found-pivot-again"
    };

    Some(ConnectorWidth6PairFamilySurfacePicker {
        selection_rule:
            "after-connector-cohort-profile-finds-no-small-prime-separator;rank-whole-pair-family-control-surfaces-by-fresh-surviving-related-branches"
                .to_string(),
        source_surface_count,
        candidate_surface_count: rows.len(),
        surface_ready_count,
        selected_surface,
        picker_decision: picker_decision.to_string(),
        next_experiment_target,
        rows,
    })
}

fn build_pair_family_surface_residue_profile(
    picker: Option<&ConnectorWidth6PairFamilySurfacePicker>,
    matrices: &[(
        &str,
        Option<&ConnectorWidth6OrthogonalPairFamilyControlMatrix>,
    )],
) -> Option<ConnectorWidth6PairFamilySurfaceResidueProfile> {
    let selected = picker?.selected_surface.as_ref()?;
    if selected.fresh_survivor_count < 2 {
        return None;
    }
    let matrix = matrices
        .iter()
        .find(|(surface_id, _)| *surface_id == selected.surface_id)
        .and_then(|(_, matrix)| *matrix)?;

    let mut rows = Vec::new();
    let mut connectors = BTreeSet::new();
    let mut source_branch_ids = Vec::new();
    let mut pair_families = Vec::new();
    let mut fresh_survivor_branch_count = 0;

    for family in &matrix.pair_families {
        let Some(fresh) = &family.fresh_replication else {
            continue;
        };
        source_branch_ids.push(fresh.source_branch_id.clone());
        pair_families.push(fresh.pair_family.clone());
        connectors.insert(fresh.connector.clone());
        if fresh.reverse_only_pair_count > 0 {
            fresh_survivor_branch_count += 1;
        }
        rows.extend(fresh.rows.iter().cloned());
    }

    if rows.is_empty() || fresh_survivor_branch_count < 2 {
        return None;
    }

    rows.sort_by(|left, right| {
        left.control_family
            .cmp(&right.control_family)
            .then_with(|| left.connector.cmp(&right.connector))
            .then_with(|| left.left.cmp(&right.left))
            .then_with(|| left.right.cmp(&right.right))
    });
    source_branch_ids.sort();
    source_branch_ids.dedup();
    pair_families.sort();
    pair_families.dedup();

    let moduli = vec![3_u32, 5, 7, 11, 13, 17, 19, 23, 29, 31];
    let reverse_only_rows = rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .collect::<Vec<_>>();
    let comparison_rows = rows
        .iter()
        .filter(|row| row.contrast_class != "reverse-only-prime-hit")
        .collect::<Vec<_>>();
    let mut residue_rows = moduli
        .iter()
        .map(|modulus| {
            let reverse_only_residues = reverse_only_rows
                .iter()
                .map(|row| (row.left % *modulus as u128) as u32)
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            let comparison_residues = comparison_rows
                .iter()
                .map(|row| (row.left % *modulus as u128) as u32)
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            let comparison_set = comparison_residues.iter().copied().collect::<BTreeSet<_>>();
            let shared_residues = reverse_only_residues
                .iter()
                .copied()
                .filter(|residue| comparison_set.contains(residue))
                .collect::<Vec<_>>();
            let separator_status = if reverse_only_residues.is_empty() {
                "no-reverse-only-residues"
            } else if shared_residues.is_empty() {
                "exact-residue-separator"
            } else {
                "overlapping-residue-classes"
            };

            ConnectorWidth6NonMod3CandidateResidueProfileRow {
                modulus: *modulus,
                reverse_only_pair_count: reverse_only_rows.len(),
                comparison_pair_count: comparison_rows.len(),
                reverse_only_residues,
                comparison_residues,
                shared_residues,
                separator_status: separator_status.to_string(),
            }
        })
        .collect::<Vec<_>>();
    residue_rows.sort_by(|left, right| left.modulus.cmp(&right.modulus));

    let exact_separator_count = residue_rows
        .iter()
        .filter(|row| row.separator_status == "exact-residue-separator")
        .count();
    let best_separator = residue_rows
        .iter()
        .filter(|row| row.separator_status == "exact-residue-separator")
        .min_by(|left, right| {
            left.reverse_only_residues
                .len()
                .cmp(&right.reverse_only_residues.len())
                .then_with(|| left.modulus.cmp(&right.modulus))
        })
        .cloned();
    let profile_decision = if best_separator.is_some() {
        "small-prime-family-surface-residue-separator-found-replicate-before-lean"
    } else {
        "no-small-prime-family-surface-residue-separator-found"
    };
    let next_experiment_target = best_separator
        .as_ref()
        .map(|separator| {
            format!(
                "replicate-family-surface-{}-mod{}-residue-separator-before-lean",
                selected.surface_id, separator.modulus
            )
        })
        .unwrap_or_else(|| {
            format!(
                "select-new-family-level-replication-surface-after-{}-profile-no-small-prime-separator",
                selected.surface_id
            )
        });

    Some(ConnectorWidth6PairFamilySurfaceResidueProfile {
        selection_rule:
            "aggregate-selected-branches-from-one-pair-family-control-surface-and-profile-reverse-only-left-endpoints-by-small-prime-residue"
                .to_string(),
        surface_id: selected.surface_id.clone(),
        surface_label: selected.surface_label.clone(),
        pair_families,
        source_branch_ids,
        branch_count: selected.source_selected_count,
        fresh_survivor_branch_count,
        connectors: connectors.into_iter().collect(),
        moduli,
        row_count: rows.len(),
        reverse_only_pair_count: reverse_only_rows.len(),
        comparison_pair_count: comparison_rows.len(),
        profiled_modulus_count: residue_rows.len(),
        exact_separator_count,
        best_separator,
        profile_decision: profile_decision.to_string(),
        next_experiment_target,
        rows: residue_rows,
    })
}

fn build_orthogonal_pair_family_control(
    pair_family: &str,
    pair_gap: u32,
    source_pair_cases: Vec<PairCase>,
    fresh_pair_cases: Vec<PairCase>,
    widths: &[u32],
    digits: &[u8],
    retired_branch_ids: &BTreeSet<String>,
) -> ConnectorWidth6OrthogonalPairFamilyControl {
    let mut rows = Vec::new();
    for case in &source_pair_cases {
        for &width in widths {
            for start_position in 1..(width - 2) {
                for &first_digit in digits {
                    for &second_digit in digits {
                        if let Some(row) = build_multi_digit_motif_row(
                            case,
                            width,
                            start_position,
                            [first_digit, second_digit],
                            &format!("orthogonal-pair-family-control-source-{pair_family}"),
                        ) {
                            rows.push(row);
                        }
                    }
                }
            }
        }
    }
    rows.sort_by(|left, right| {
        left.left
            .cmp(&right.left)
            .then_with(|| left.right.cmp(&right.right))
            .then_with(|| left.width.cmp(&right.width))
            .then_with(|| left.start_position.cmp(&right.start_position))
            .then_with(|| left.motif_digits.cmp(&right.motif_digits))
    });
    let rankings = rank_multi_digit_motif_cells(&rows);
    let selected_motif = rankings
        .iter()
        .find(|row| {
            row.reverse_only_pair_count > 0
                && !retired_branch_ids.contains(&orthogonal_branch_id_for_motif(
                    pair_gap,
                    row.width,
                    row.start_position,
                    &row.motif_positions,
                    &row.motif_digits,
                    &row.connector,
                ))
        })
        .cloned();
    let fresh_replication = selected_motif.as_ref().map(|motif| {
        build_orthogonal_pair_family_replication(pair_family, pair_gap, motif, &fresh_pair_cases)
    });
    let theorem_blocked_row_count = rows.iter().filter(|row| row.mod3_theorem_blocked).count();
    let nonblocked_row_count = rows.iter().filter(|row| !row.mod3_theorem_blocked).count();
    let reverse_only_motif_count = rankings
        .iter()
        .filter(|row| row.reverse_only_pair_count > 0)
        .count();
    let picker_decision = if selected_motif.is_some() {
        "orthogonal-pair-family-source-motif-selected-for-fresh-ladder"
    } else {
        "orthogonal-pair-family-source-picker-found-no-reverse-only-branch"
    };
    let next_experiment_target = fresh_replication
        .as_ref()
        .map(|replication| replication.next_experiment_target.clone())
        .or_else(|| {
            selected_motif.as_ref().map(|motif| {
                format!(
                    "independently-replicate-orthogonal-gap{}-multidigit-motif-{}-width{}-start{}-digits{}",
                    pair_gap,
                    motif.connector,
                    motif.width,
                    motif.start_position,
                    motif_digits_label(&motif.motif_digits)
                )
            })
        })
        .unwrap_or_else(|| format!("no-orthogonal-{pair_family}-motif-selected"));

    ConnectorWidth6OrthogonalPairFamilyControl {
        pair_family: pair_family.to_string(),
        pair_gap,
        source_pair_count: source_pair_cases.len(),
        source_pair_labels: source_pair_cases
            .iter()
            .map(|case| case.name.to_string())
            .collect(),
        fresh_pair_count: fresh_pair_cases.len(),
        fresh_pair_labels: fresh_pair_cases
            .iter()
            .map(|case| case.name.to_string())
            .collect(),
        row_count: rows.len(),
        theorem_blocked_row_count,
        nonblocked_row_count,
        ranked_motif_count: rankings.len(),
        reverse_only_motif_count,
        selected_motif,
        fresh_replication,
        picker_decision: picker_decision.to_string(),
        next_experiment_target,
        rankings,
        rows,
    }
}

fn build_orthogonal_pair_family_replication(
    pair_family: &str,
    pair_gap: u32,
    motif: &ConnectorWidth6MultiDigitMotifRankRow,
    pair_cases: &[PairCase],
) -> ConnectorWidth6OrthogonalPairFamilyReplication {
    let positions = motif.motif_positions.clone();
    let mut rows = Vec::new();
    for case in pair_cases {
        if let Some(row) = build_positioned_motif_row(
            case,
            motif.width,
            &positions,
            &motif.motif_digits,
            &format!("orthogonal-pair-family-control-fresh-{pair_family}"),
        ) {
            rows.push(row);
        }
    }
    rows.sort_by(|left, right| {
        left.left
            .cmp(&right.left)
            .then_with(|| left.right.cmp(&right.right))
    });
    let row_count = rows.len();
    let theorem_blocked_row_count = rows.iter().filter(|row| row.mod3_theorem_blocked).count();
    let nonblocked_row_count = rows.iter().filter(|row| !row.mod3_theorem_blocked).count();
    let residue_admissible_pair_count = rows
        .iter()
        .filter(|row| row.residue_admissible_in_both_directions)
        .count();
    let reverse_only_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .count();
    let forward_only_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "forward-only-prime-hit")
        .count();
    let both_hit_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "both-prime-hit")
        .count();
    let neither_hit_pair_count = rows
        .iter()
        .filter(|row| row.contrast_class == "neither-prime-hit")
        .count();
    let reverse_only_pair_labels = rows
        .iter()
        .filter(|row| row.contrast_class == "reverse-only-prime-hit")
        .map(|row| row.pair_label.clone())
        .collect::<Vec<_>>();
    let replication_decision = if nonblocked_row_count > 0 && reverse_only_pair_count > 0 {
        "survived-orthogonal-pair-family-independent-ladder-residue-profiler-next"
    } else {
        "collapsed-orthogonal-pair-family-independent-ladder-retire-without-lean"
    };
    let source_branch_id = orthogonal_branch_id_for_motif(
        pair_gap,
        motif.width,
        motif.start_position,
        &motif.motif_positions,
        &motif.motif_digits,
        &motif.connector,
    );
    let next_experiment_target = if nonblocked_row_count > 0 && reverse_only_pair_count > 0 {
        orthogonal_residue_profile_target(pair_gap, motif)
    } else {
        format_orthogonal_retire_target(
            pair_gap,
            &motif.connector,
            motif.width,
            motif.start_position,
            &motif.motif_positions,
            &motif.motif_digits,
        )
    };

    ConnectorWidth6OrthogonalPairFamilyReplication {
        selection_rule: format!("selected-{pair_family}-motif-on-fresh-disjoint-prime-pair-ladder"),
        pair_family: pair_family.to_string(),
        pair_gap,
        source_branch_id,
        source_motif_rank: motif.rank,
        width: motif.width,
        start_position: motif.start_position,
        motif_positions: motif.motif_positions.clone(),
        motif_digits: motif.motif_digits.clone(),
        connector: motif.connector.clone(),
        fresh_pair_count: pair_cases.len(),
        fresh_pair_labels: pair_cases
            .iter()
            .map(|case| case.name.to_string())
            .collect(),
        row_count,
        theorem_blocked_row_count,
        nonblocked_row_count,
        residue_admissible_pair_count,
        reverse_only_pair_count,
        forward_only_pair_count,
        both_hit_pair_count,
        neither_hit_pair_count,
        reverse_only_pair_labels,
        replication_decision: replication_decision.to_string(),
        next_experiment_target,
        rows,
    }
}

