fn orthogonal_branch_id_for_motif(
    pair_gap: u32,
    width: u32,
    start_position: u32,
    motif_positions: &[u32],
    motif_digits: &[u8],
    connector: &str,
) -> String {
    let adjacent_positions = adjacent_motif_positions(start_position, motif_digits.len());
    if is_gapped_repeated_block_motif(motif_positions, motif_digits) {
        orthogonal_repeated_block_branch_id(
            pair_gap,
            width,
            motif_positions,
            motif_digits,
            connector,
        )
    } else if motif_positions_touch_edge(width, motif_positions) {
        orthogonal_edge_plus_interior_branch_id(
            pair_gap,
            width,
            motif_positions,
            motif_digits,
            connector,
        )
    } else if motif_digits.len() == 2 && motif_positions != adjacent_positions {
        orthogonal_nonadjacent_two_digit_branch_id(
            pair_gap,
            width,
            motif_positions,
            motif_digits,
            connector,
        )
    } else if motif_digits.len() == 3 {
        orthogonal_compact_three_digit_branch_id(
            pair_gap,
            width,
            start_position,
            motif_digits,
            connector,
        )
    } else {
        orthogonal_pair_family_branch_id(pair_gap, width, start_position, motif_digits, connector)
    }
}

fn orthogonal_residue_profile_target(
    pair_gap: u32,
    motif: &ConnectorWidth6MultiDigitMotifRankRow,
) -> String {
    let adjacent_positions =
        adjacent_motif_positions(motif.start_position, motif.motif_digits.len());
    if is_gapped_repeated_block_motif(&motif.motif_positions, &motif.motif_digits) {
        format!(
            "residue-profile-orthogonal-repeatblock-gap{}-motif-{}-width{}-pos{}-digits{}",
            pair_gap,
            motif.connector,
            motif.width,
            motif_positions_label(&motif.motif_positions),
            motif_digits_label(&motif.motif_digits)
        )
    } else if motif_positions_touch_edge(motif.width, &motif.motif_positions) {
        format!(
            "residue-profile-orthogonal-edgeplus2-gap{}-motif-{}-width{}-pos{}-digits{}",
            pair_gap,
            motif.connector,
            motif.width,
            motif_positions_label(&motif.motif_positions),
            motif_digits_label(&motif.motif_digits)
        )
    } else if motif.motif_digits.len() == 2 && motif.motif_positions != adjacent_positions {
        format!(
            "residue-profile-orthogonal-nonadjacent2-gap{}-multidigit-motif-{}-width{}-pos{}-digits{}",
            pair_gap,
            motif.connector,
            motif.width,
            motif_positions_label(&motif.motif_positions),
            motif_digits_label(&motif.motif_digits)
        )
    } else {
        format!(
            "residue-profile-orthogonal-gap{}-multidigit-motif-{}-width{}-start{}-digits{}",
            pair_gap,
            motif.connector,
            motif.width,
            motif.start_position,
            motif_digits_label(&motif.motif_digits)
        )
    }
}

