fn rank_edge_pair_replication_cells(
    rows: &[ConnectorWidth6PeakMatchedControlRow],
) -> Vec<ConnectorWidth6PeakEdgePairReplicationRankRow> {
    let mut cells: BTreeMap<(String, u32, u8), Vec<&ConnectorWidth6PeakMatchedControlRow>> =
        BTreeMap::new();
    for row in rows {
        cells
            .entry((edge_label(row).to_string(), row.width, row.digit))
            .or_default()
            .push(row);
    }

    let mut ranked = cells
        .into_iter()
        .filter_map(|((edge, width, digit), cell_rows)| {
            let mut nonblocked: Vec<_> = cell_rows
                .iter()
                .copied()
                .filter(|row| !row.mod3_theorem_blocked)
                .collect();
            if nonblocked.is_empty() {
                return None;
            }
            nonblocked.sort_by(|left, right| {
                left.left
                    .cmp(&right.left)
                    .then_with(|| left.right.cmp(&right.right))
            });
            let connector = nonblocked.first()?.connector.clone();
            let theorem_blocked_pair_count = cell_rows
                .iter()
                .filter(|row| row.mod3_theorem_blocked)
                .count();
            let residue_admissible_pair_count = nonblocked
                .iter()
                .filter(|row| row.residue_admissible_in_both_directions)
                .count();
            let reverse_only_pair_count = nonblocked
                .iter()
                .filter(|row| row.contrast_class == "reverse-only-prime-hit")
                .count();
            let forward_only_pair_count = nonblocked
                .iter()
                .filter(|row| row.contrast_class == "forward-only-prime-hit")
                .count();
            let both_hit_pair_count = nonblocked
                .iter()
                .filter(|row| row.contrast_class == "both-prime-hit")
                .count();
            let neither_hit_pair_count = nonblocked
                .iter()
                .filter(|row| row.contrast_class == "neither-prime-hit")
                .count();
            let reverse_only_pair_labels = nonblocked
                .iter()
                .filter(|row| row.contrast_class == "reverse-only-prime-hit")
                .map(|row| row.pair_label.clone())
                .collect::<Vec<_>>();
            let strongest_pool = nonblocked
                .iter()
                .copied()
                .filter(|row| row.contrast_class == "reverse-only-prime-hit")
                .collect::<Vec<_>>();
            let strongest_candidates = if strongest_pool.is_empty() {
                nonblocked.clone()
            } else {
                strongest_pool
            };
            let strongest = strongest_candidates.iter().max_by(|left, right| {
                left.absolute_observed_to_corrected_ratio_gap
                    .total_cmp(&right.absolute_observed_to_corrected_ratio_gap)
                    .then_with(|| right.left.cmp(&left.left))
                    .then_with(|| right.right.cmp(&left.right))
            })?;
            let replication_status = match reverse_only_pair_count {
                0 => "no-nonblocked-reverse-only-replication",
                1 => "singleton-nonblocked-reverse-only-edge-cell",
                _ => "replicated-nonblocked-reverse-only-edge-cell",
            };

            Some(ConnectorWidth6PeakEdgePairReplicationRankRow {
                rank: 0,
                edge,
                width,
                digit,
                connector,
                nonblocked_pair_count: nonblocked.len(),
                theorem_blocked_pair_count,
                residue_admissible_pair_count,
                reverse_only_pair_count,
                forward_only_pair_count,
                both_hit_pair_count,
                neither_hit_pair_count,
                reverse_only_pair_labels,
                strongest_pair_label: strongest.pair_label.clone(),
                strongest_signed_observed_to_corrected_ratio_gap: strongest
                    .signed_observed_to_corrected_ratio_gap,
                replication_status: replication_status.to_string(),
            })
        })
        .collect::<Vec<_>>();

    ranked.sort_by(|left, right| {
        right
            .reverse_only_pair_count
            .cmp(&left.reverse_only_pair_count)
            .then_with(|| right.nonblocked_pair_count.cmp(&left.nonblocked_pair_count))
            .then_with(|| {
                right
                    .strongest_signed_observed_to_corrected_ratio_gap
                    .abs()
                    .total_cmp(&left.strongest_signed_observed_to_corrected_ratio_gap.abs())
            })
            .then_with(|| left.edge.cmp(&right.edge))
            .then_with(|| left.width.cmp(&right.width))
            .then_with(|| left.digit.cmp(&right.digit))
    });
    for (index, row) in ranked.iter_mut().enumerate() {
        row.rank = index + 1;
    }
    ranked
}

fn rank_interior_non_mod3_family_cells(
    rows: &[ConnectorWidth6PeakMatchedControlRow],
) -> Vec<ConnectorWidth6InteriorNonMod3FamilyRankRow> {
    let mut cells: BTreeMap<(u32, u32, u8), Vec<&ConnectorWidth6PeakMatchedControlRow>> =
        BTreeMap::new();
    for row in rows {
        cells
            .entry((row.width, row.position, row.digit))
            .or_default()
            .push(row);
    }

    let mut ranked = cells
        .into_iter()
        .filter_map(|((width, position, digit), cell_rows)| {
            let mut nonblocked: Vec<_> = cell_rows
                .iter()
                .copied()
                .filter(|row| !row.mod3_theorem_blocked)
                .collect();
            if nonblocked.is_empty() {
                return None;
            }
            nonblocked.sort_by(|left, right| {
                left.left
                    .cmp(&right.left)
                    .then_with(|| left.right.cmp(&right.right))
            });
            let connector = nonblocked.first()?.connector.clone();
            let theorem_blocked_pair_count = cell_rows
                .iter()
                .filter(|row| row.mod3_theorem_blocked)
                .count();
            let residue_admissible_pair_count = nonblocked
                .iter()
                .filter(|row| row.residue_admissible_in_both_directions)
                .count();
            let reverse_only_pair_count = nonblocked
                .iter()
                .filter(|row| row.contrast_class == "reverse-only-prime-hit")
                .count();
            let forward_only_pair_count = nonblocked
                .iter()
                .filter(|row| row.contrast_class == "forward-only-prime-hit")
                .count();
            let both_hit_pair_count = nonblocked
                .iter()
                .filter(|row| row.contrast_class == "both-prime-hit")
                .count();
            let neither_hit_pair_count = nonblocked
                .iter()
                .filter(|row| row.contrast_class == "neither-prime-hit")
                .count();
            let reverse_only_pair_labels = nonblocked
                .iter()
                .filter(|row| row.contrast_class == "reverse-only-prime-hit")
                .map(|row| row.pair_label.clone())
                .collect::<Vec<_>>();
            let strongest_pool = nonblocked
                .iter()
                .copied()
                .filter(|row| row.contrast_class == "reverse-only-prime-hit")
                .collect::<Vec<_>>();
            let strongest_candidates = if strongest_pool.is_empty() {
                nonblocked.clone()
            } else {
                strongest_pool
            };
            let strongest = strongest_candidates.iter().max_by(|left, right| {
                left.absolute_observed_to_corrected_ratio_gap
                    .total_cmp(&right.absolute_observed_to_corrected_ratio_gap)
                    .then_with(|| right.left.cmp(&left.left))
                    .then_with(|| right.right.cmp(&left.right))
            })?;
            let replication_status = match reverse_only_pair_count {
                0 => "no-nonblocked-reverse-only-interior-cell",
                1 => "singleton-nonblocked-reverse-only-interior-cell",
                _ => "replicated-nonblocked-reverse-only-interior-cell",
            };

            Some(ConnectorWidth6InteriorNonMod3FamilyRankRow {
                rank: 0,
                width,
                position,
                digit,
                connector,
                nonblocked_pair_count: nonblocked.len(),
                theorem_blocked_pair_count,
                residue_admissible_pair_count,
                reverse_only_pair_count,
                forward_only_pair_count,
                both_hit_pair_count,
                neither_hit_pair_count,
                reverse_only_pair_labels,
                strongest_pair_label: strongest.pair_label.clone(),
                strongest_signed_observed_to_corrected_ratio_gap: strongest
                    .signed_observed_to_corrected_ratio_gap,
                replication_status: replication_status.to_string(),
            })
        })
        .collect::<Vec<_>>();

    ranked.sort_by(|left, right| {
        right
            .reverse_only_pair_count
            .cmp(&left.reverse_only_pair_count)
            .then_with(|| right.nonblocked_pair_count.cmp(&left.nonblocked_pair_count))
            .then_with(|| {
                right
                    .strongest_signed_observed_to_corrected_ratio_gap
                    .abs()
                    .total_cmp(&left.strongest_signed_observed_to_corrected_ratio_gap.abs())
            })
            .then_with(|| left.width.cmp(&right.width))
            .then_with(|| left.position.cmp(&right.position))
            .then_with(|| left.digit.cmp(&right.digit))
            .then_with(|| left.connector.cmp(&right.connector))
    });
    for (index, row) in ranked.iter_mut().enumerate() {
        row.rank = index + 1;
    }
    ranked
}

fn edge_label(row: &ConnectorWidth6PeakMatchedControlRow) -> &'static str {
    if row.position == 0 {
        "leading"
    } else {
        "trailing"
    }
}

fn peak_matched_control_screen_decision(
    summaries: &[ConnectorWidth6PeakMatchedControlSummary],
) -> String {
    let summary = |name: &str| summaries.iter().find(|row| row.control_family == name);
    let all_aligned = summaries
        .iter()
        .all(|summary| summary.aligned_count == summary.row_count);
    if all_aligned {
        return "peak-alignment-persists-across-all-matched-controls-review-exact-feature"
            .to_string();
    }
    if summary("pair-control").is_some_and(|row| row.aligned_count < row.row_count) {
        return "peak-alignment-is-pair-specific-under-nearby-twin-controls".to_string();
    }
    if summary("adjacent-width-control").is_some_and(|row| row.aligned_count < row.row_count) {
        return "peak-alignment-is-width-specific-under-adjacent-width-controls".to_string();
    }
    "peak-alignment-partial-replication-target-before-theorem-growth".to_string()
}

fn most_frequent_string<'a>(values: impl Iterator<Item = &'a str>) -> Option<String> {
    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
    for value in values {
        *counts.entry(value).or_default() += 1;
    }
    counts
        .into_iter()
        .max_by(|left, right| left.1.cmp(&right.1).then_with(|| right.0.cmp(left.0)))
        .map(|(value, _)| value.to_string())
}

fn width6_stress_target_decision(selected: &ConnectorWidth6StressPairSummary) -> String {
    if selected.sign_stable
        && selected.localization_statuses
            == vec!["diffuse-mixed-sign-position-digit-contrast".to_string()]
    {
        "selected-width6-gap-persists-across-correction-bounds-but-microscope-is-diffuse-mixed-sign"
            .to_string()
    } else if selected.sign_stable {
        "selected-width6-gap-persists-review-position-digit-localization-before-theorem".to_string()
    } else {
        "selected-width6-gap-collapses-under-correction-bound-stress".to_string()
    }
}

fn median_sorted(values: &[f64]) -> f64 {
    if values.is_empty() {
        return 0.0;
    }
    let mid = values.len() / 2;
    if values.len().is_multiple_of(2) {
        (values[mid - 1] + values[mid]) / 2.0
    } else {
        values[mid]
    }
}

fn sorted_unique_strings(values: impl Iterator<Item = String>) -> Vec<String> {
    values.collect::<BTreeSet<_>>().into_iter().collect()
}

