pub fn build_position_export_rows(reports: &[NamedPairReport]) -> Vec<PositionExportRow> {
    let mut rows = Vec::new();

    for report in reports {
        let asymmetry = report.summary.directional_asymmetry();

        for row in report
            .audit
            .forward_positions
            .iter()
            .chain(report.audit.reverse_positions.iter())
        {
            let direction_stats = match row.direction {
                Direction::Forward => &report.audit.forward,
                Direction::Reverse => &report.audit.reverse,
            };
            rows.push(position_export_row(
                report,
                row,
                direction_stats,
                &asymmetry,
            ));
        }
    }

    rows
}

pub fn build_sweep_export_rows(reports: &[NamedPairReport]) -> Vec<ResidualSweepExportRow> {
    reports
        .iter()
        .flat_map(|report| {
            report
                .sweep
                .iter()
                .map(|row| ResidualSweepExportRow {
                    pair_label: row.pair_label.clone(),
                    bound: row.bound,
                    small_primes: format!("{:?}", row.small_primes),
                    forward_corrected_ratio: row.forward_corrected_ratio,
                    reverse_corrected_ratio: row.reverse_corrected_ratio,
                    corrected_residual_ratio_delta: row.corrected_residual_ratio_delta,
                    corrected_expected_hit_delta: row.corrected_expected_hit_delta,
                    forward_corrected_expected_hits: row.forward_corrected_expected_hits,
                    reverse_corrected_expected_hits: row.reverse_corrected_expected_hits,
                    forward_corrected_poisson_z: row.forward_corrected_poisson_z,
                    reverse_corrected_poisson_z: row.reverse_corrected_poisson_z,
                })
                .collect::<Vec<_>>()
        })
        .collect()
}

pub fn build_residue_survivor_rows(
    reports: &[NamedPairReport],
) -> Vec<ConnectorResidueSurvivorRow> {
    reports
        .iter()
        .flat_map(|report| {
            report
                .summary
                .residue_profiles
                .iter()
                .map(|profile| {
                    let forward_survivors = report
                        .summary
                        .forward
                        .candidates
                        .iter()
                        .filter(|candidate| profile.classify(&candidate.hit).is_yes())
                        .count();
                    let reverse_survivors = report
                        .summary
                        .reverse
                        .candidates
                        .iter()
                        .filter(|candidate| profile.classify(&candidate.hit).is_yes())
                        .count();
                    let (lean_module, lean_theorem) = connector_residue_survivor_theorem_link(
                        report.summary.pair,
                        profile.modulus,
                    );
                    ConnectorResidueSurvivorRow {
                        pair_label: report.name.clone(),
                        left: report.summary.pair.left,
                        right: report.summary.pair.right,
                        modulus: profile.modulus,
                        pair_residue: profile.pair_residue,
                        blocked_class: profile.blocked_connector_residue,
                        forward_raw_candidates: report.summary.forward.raw_candidates(),
                        reverse_raw_candidates: report.summary.reverse.raw_candidates(),
                        forward_survivors,
                        reverse_survivors,
                        survivor_delta: forward_survivors as isize - reverse_survivors as isize,
                        proof_status: "theorem-backed-equal-directional-survivor-counts"
                            .to_string(),
                        lean_module: Some(lean_module.to_string()),
                        lean_theorem: Some(lean_theorem.to_string()),
                    }
                })
                .collect::<Vec<_>>()
        })
        .collect()
}

pub fn build_residual_boundary_rows(
    reports: &[NamedPairReport],
    residue_survivor_rows: &[ConnectorResidueSurvivorRow],
) -> Vec<ConnectorResidualBoundaryRow> {
    let mut survivor_deltas_by_pair: BTreeMap<(u128, u128), Vec<ConnectorResidueSurvivorDelta>> =
        BTreeMap::new();
    for row in residue_survivor_rows {
        survivor_deltas_by_pair
            .entry((row.left, row.right))
            .or_default()
            .push(ConnectorResidueSurvivorDelta {
                modulus: row.modulus,
                survivor_delta: row.survivor_delta,
            });
    }
    for deltas in survivor_deltas_by_pair.values_mut() {
        deltas.sort_by_key(|row| row.modulus);
    }

    reports
        .iter()
        .map(|report| {
            let asymmetry = report.summary.directional_asymmetry();
            let residue_survivor_deltas = survivor_deltas_by_pair
                .get(&(report.summary.pair.left, report.summary.pair.right))
                .cloned()
                .unwrap_or_default();
            let residue_survivors_equal = residue_survivor_deltas
                .iter()
                .all(|row| row.survivor_delta == 0);

            ConnectorResidualBoundaryRow {
                pair_label: report.name.clone(),
                left: report.summary.pair.left,
                right: report.summary.pair.right,
                residue_survivor_deltas,
                residue_survivors_equal,
                residue_survivor_null_status: "theorem-backed-equal-directional-survivor-counts"
                    .to_string(),
                empirical_raw_hit_delta: asymmetry.hit_delta(),
                empirical_corrected_expected_hit_delta: report.audit.corrected_expected_hit_delta(),
                empirical_corrected_residual_ratio_delta: report
                    .audit
                    .corrected_residual_ratio_delta(),
                boundary_interpretation:
                    "exact-local-filter-direction-neutral-residual-gap-outside-theorem-layer"
                        .to_string(),
            }
        })
        .collect()
}

pub fn pick_residual_target(
    rows: &[ConnectorResidualBoundaryRow],
) -> Option<ConnectorResidualTargetPick> {
    let mut candidates: Vec<_> = rows
        .iter()
        .filter(|row| row.residue_survivors_equal)
        .collect();
    candidates.sort_by(|a, b| {
        b.empirical_corrected_residual_ratio_delta
            .abs()
            .total_cmp(&a.empirical_corrected_residual_ratio_delta.abs())
            .then_with(|| a.pair_label.cmp(&b.pair_label))
            .then_with(|| a.left.cmp(&b.left))
            .then_with(|| a.right.cmp(&b.right))
    });

    candidates.first().map(|row| ConnectorResidualTargetPick {
        pair_label: row.pair_label.clone(),
        left: row.left,
        right: row.right,
        selection_rule:
            "largest-absolute-corrected-residual-ratio-delta-after-residue-survivor-null"
                .to_string(),
        absolute_corrected_residual_ratio_delta: row.empirical_corrected_residual_ratio_delta.abs(),
        corrected_residual_ratio_delta: row.empirical_corrected_residual_ratio_delta,
        raw_hit_delta: row.empirical_raw_hit_delta,
        residue_survivors_equal: row.residue_survivors_equal,
        residue_survivor_deltas: row.residue_survivor_deltas.clone(),
        target_status: "empirical-residual-target-not-mechanism-claim".to_string(),
        next_step_note:
            "investigate this residual gap only after preserving the exact residue-null boundary"
                .to_string(),
    })
}

pub fn build_residual_target_follow_up(
    reports: &[NamedPairReport],
    target: Option<&ConnectorResidualTargetPick>,
) -> Option<ConnectorResidualTargetFollowUp> {
    let target = target?;
    let report = reports.iter().find(|report| {
        report.summary.pair.left == target.left && report.summary.pair.right == target.right
    })?;
    let mut width_buckets: BTreeMap<(Direction, u32), (usize, usize, f64)> = BTreeMap::new();

    for row in report
        .audit
        .forward_positions
        .iter()
        .chain(report.audit.reverse_positions.iter())
    {
        let entry = width_buckets
            .entry((row.direction, row.width))
            .or_insert((0, 0, 0.0));
        entry.0 += row.residue_admissible_candidates;
        entry.1 += row.prime_hits;
        entry.2 += row.small_prime_corrected_expected_hits;
    }

    let width_rows: Vec<ConnectorResidualTargetWidthRow> = width_buckets
        .into_iter()
        .map(
            |(
                (direction, width),
                (residue_admissible_candidates, prime_hits, small_prime_corrected_expected_hits),
            )| ConnectorResidualTargetWidthRow {
                direction,
                width,
                residue_admissible_candidates,
                prime_hits,
                small_prime_corrected_expected_hits,
                observed_to_corrected_ratio: if small_prime_corrected_expected_hits > 0.0 {
                    prime_hits as f64 / small_prime_corrected_expected_hits
                } else {
                    0.0
                },
            },
        )
        .collect();

    let width_contrast_pick = pick_width_contrast(&width_rows);
    let width_contrast_micro_atlas =
        build_width_contrast_micro_atlas(target, report, &width_rows, width_contrast_pick.as_ref());

    Some(ConnectorResidualTargetFollowUp {
        pair_label: target.pair_label.clone(),
        left: target.left,
        right: target.right,
        scan_scope: format!(
            "selected-target-only;widths={:?};digits={:?};residue-moduli={:?}",
            WIDTHS, DIGITS, RESIDUE_MODULI
        ),
        residue_survivor_deltas: target.residue_survivor_deltas.clone(),
        residue_survivors_equal: target.residue_survivors_equal,
        residue_survivor_null_status: "theorem-backed-equal-directional-survivor-counts"
            .to_string(),
        residue_null_lean_module: CONNECTOR_PROFILE_EXAMPLES_MODULE.to_string(),
        residue_null_lean_theorem: TWIN_SMALL_MOD3_MOD9_SURVIVOR_COUNT_THEOREM.to_string(),
        corrected_residual_ratio_delta: target.corrected_residual_ratio_delta,
        width_contrast_pick,
        width_contrast_micro_atlas,
        width_rows,
        follow_up_status: "bounded-scan-follow-up-not-mechanism-claim".to_string(),
        interpretation: "width-level empirical rows preserve the exact residue-null guardrail"
            .to_string(),
    })
}

pub fn pick_width_contrast(
    rows: &[ConnectorResidualTargetWidthRow],
) -> Option<ConnectorResidualTargetWidthContrastPick> {
    let mut by_width: BTreeMap<u32, BTreeMap<Direction, &ConnectorResidualTargetWidthRow>> =
        BTreeMap::new();
    for row in rows {
        by_width
            .entry(row.width)
            .or_default()
            .insert(row.direction, row);
    }

    let mut candidates: Vec<_> = by_width
        .into_iter()
        .filter_map(|(width, rows)| {
            let forward = rows.get(&Direction::Forward)?;
            let reverse = rows.get(&Direction::Reverse)?;
            let signed_ratio_gap =
                forward.observed_to_corrected_ratio - reverse.observed_to_corrected_ratio;
            Some(ConnectorResidualTargetWidthContrastPick {
                width,
                selection_rule: "largest-absolute-forward-reverse-observed-to-corrected-ratio-gap"
                    .to_string(),
                forward_observed_to_corrected_ratio: forward.observed_to_corrected_ratio,
                reverse_observed_to_corrected_ratio: reverse.observed_to_corrected_ratio,
                signed_ratio_gap,
                absolute_ratio_gap: signed_ratio_gap.abs(),
                forward_prime_hits: forward.prime_hits,
                reverse_prime_hits: reverse.prime_hits,
                contrast_status: "empirical-width-contrast-not-mechanism-claim".to_string(),
            })
        })
        .collect();
    candidates.sort_by(|a, b| {
        b.absolute_ratio_gap
            .total_cmp(&a.absolute_ratio_gap)
            .then_with(|| a.width.cmp(&b.width))
    });
    candidates.into_iter().next()
}

pub fn build_width_contrast_micro_atlas(
    target: &ConnectorResidualTargetPick,
    report: &NamedPairReport,
    rows: &[ConnectorResidualTargetWidthRow],
    contrast: Option<&ConnectorResidualTargetWidthContrastPick>,
) -> Option<ConnectorResidualTargetWidthContrastMicroAtlas> {
    let contrast = contrast?;
    let forward = rows
        .iter()
        .find(|row| row.direction == Direction::Forward && row.width == contrast.width)?;
    let reverse = rows
        .iter()
        .find(|row| row.direction == Direction::Reverse && row.width == contrast.width)?;
    let position_digit_contrast_rows =
        build_position_digit_contrast_rows(report, contrast.width, &report.audit.small_primes);
    let position_digit_contrast_pick =
        pick_position_digit_contrast(&position_digit_contrast_rows, contrast.signed_ratio_gap);
    let next_theorem_decision = match position_digit_contrast_pick
        .as_ref()
        .map(|pick| pick.localization_status.as_str())
    {
        Some("single-aligned-position-digit-feature-candidate") => {
            "review-selected-position-digit-for-new-exact-feature-before-theorem"
        }
        _ => "replicate-before-adding-new-connector-theorem",
    };
    let next_experiment_target = position_digit_contrast_pick
        .as_ref()
        .map(|pick| {
            format!(
                "replicate-width-{}-position-{}-digit-{}-twin-prime-profile-under-matched-connector-controls",
                pick.row.width, pick.row.position, pick.row.digit
            )
        })
        .unwrap_or_else(|| {
            "replicate-or-stress-width-6-twin-prime-profile-under-matched-connector-controls"
                .to_string()
        });

    Some(ConnectorResidualTargetWidthContrastMicroAtlas {
        pair_label: target.pair_label.clone(),
        left: target.left,
        right: target.right,
        width: contrast.width,
        selection_rule: "selected-width-largest-forward-reverse-observed-to-corrected-ratio-gap"
            .to_string(),
        residue_survivor_deltas: target.residue_survivor_deltas.clone(),
        residue_survivors_equal: target.residue_survivors_equal,
        residue_null_lean_module: CONNECTOR_PROFILE_EXAMPLES_MODULE.to_string(),
        residue_null_lean_theorem: TWIN_SMALL_MOD3_MOD9_SURVIVOR_COUNT_THEOREM.to_string(),
        exact_layer_decision: "exact-residue-null-layer-cannot-distinguish-this-width-contrast"
            .to_string(),
        forward_residue_admissible_candidates: forward.residue_admissible_candidates,
        reverse_residue_admissible_candidates: reverse.residue_admissible_candidates,
        forward_prime_hits: forward.prime_hits,
        reverse_prime_hits: reverse.prime_hits,
        raw_hit_delta: forward.prime_hits as isize - reverse.prime_hits as isize,
        forward_corrected_expected_hits: forward.small_prime_corrected_expected_hits,
        reverse_corrected_expected_hits: reverse.small_prime_corrected_expected_hits,
        corrected_expected_hit_delta: forward.small_prime_corrected_expected_hits
            - reverse.small_prime_corrected_expected_hits,
        forward_observed_to_corrected_ratio: contrast.forward_observed_to_corrected_ratio,
        reverse_observed_to_corrected_ratio: contrast.reverse_observed_to_corrected_ratio,
        signed_observed_to_corrected_ratio_gap: contrast.signed_ratio_gap,
        absolute_observed_to_corrected_ratio_gap: contrast.absolute_ratio_gap,
        position_digit_contrast_rows,
        position_digit_contrast_pick,
        empirical_status: "bounded-width-empirical-residual-contrast-not-mechanism-claim"
            .to_string(),
        next_theorem_decision: next_theorem_decision.to_string(),
        next_experiment_target,
    })
}

pub fn build_position_digit_contrast_rows(
    report: &NamedPairReport,
    width: u32,
    small_primes: &[u32],
) -> Vec<ConnectorResidualTargetPositionDigitContrastRow> {
    let forward = position_digit_metrics(&report.summary.forward, width, small_primes);
    let reverse = position_digit_metrics(&report.summary.reverse, width, small_primes);
    let mut keys: BTreeSet<_> = forward.keys().copied().collect();
    keys.extend(reverse.keys().copied());

    let mut rows: Vec<_> = keys
        .into_iter()
        .filter_map(|(position, digit)| {
            let forward = forward.get(&(position, digit))?;
            let reverse = reverse.get(&(position, digit))?;
            let signed_observed_to_corrected_ratio_gap =
                forward.observed_to_corrected_ratio - reverse.observed_to_corrected_ratio;
            Some(ConnectorResidualTargetPositionDigitContrastRow {
                rank: 0,
                width,
                position,
                digit,
                connector: forward.connector.clone(),
                forward_prime_hit: forward.prime_hit,
                reverse_prime_hit: reverse.prime_hit,
                forward_corrected_expected_hit: forward.corrected_expected_hit,
                reverse_corrected_expected_hit: reverse.corrected_expected_hit,
                corrected_expected_hit_delta: forward.corrected_expected_hit
                    - reverse.corrected_expected_hit,
                forward_observed_to_corrected_ratio: forward.observed_to_corrected_ratio,
                reverse_observed_to_corrected_ratio: reverse.observed_to_corrected_ratio,
                signed_observed_to_corrected_ratio_gap,
                absolute_observed_to_corrected_ratio_gap: signed_observed_to_corrected_ratio_gap
                    .abs(),
                contrast_class: position_digit_contrast_class(forward.prime_hit, reverse.prime_hit)
                    .to_string(),
            })
        })
        .collect();

    rows.sort_by(|a, b| {
        b.absolute_observed_to_corrected_ratio_gap
            .total_cmp(&a.absolute_observed_to_corrected_ratio_gap)
            .then_with(|| a.position.cmp(&b.position))
            .then_with(|| a.digit.cmp(&b.digit))
    });
    for (index, row) in rows.iter_mut().enumerate() {
        row.rank = index + 1;
    }
    rows
}

pub fn pick_position_digit_contrast(
    rows: &[ConnectorResidualTargetPositionDigitContrastRow],
    width_signed_observed_to_corrected_ratio_gap: f64,
) -> Option<ConnectorResidualTargetPositionDigitContrastPick> {
    let row = rows.first()?.clone();
    let total_absolute_gap: f64 = rows
        .iter()
        .map(|row| row.absolute_observed_to_corrected_ratio_gap)
        .sum();
    let concentration_share_of_absolute_gap = if total_absolute_gap > 0.0 {
        row.absolute_observed_to_corrected_ratio_gap / total_absolute_gap
    } else {
        0.0
    };
    let top_row_aligns_with_width_gap = same_nonzero_sign(
        row.signed_observed_to_corrected_ratio_gap,
        width_signed_observed_to_corrected_ratio_gap,
    );
    let concentration_status = if concentration_share_of_absolute_gap >= 0.25 {
        "single-position-digit-concentration-candidate"
    } else {
        "diffuse-position-digit-contrast-replication-target"
    };
    let localization_status =
        if concentration_share_of_absolute_gap >= 0.25 && top_row_aligns_with_width_gap {
            "single-aligned-position-digit-feature-candidate"
        } else if !top_row_aligns_with_width_gap {
            "diffuse-mixed-sign-position-digit-contrast"
        } else {
            "diffuse-aligned-position-digit-contrast"
        };

    Some(ConnectorResidualTargetPositionDigitContrastPick {
        selection_rule:
            "largest-absolute-forward-reverse-position-digit-observed-to-corrected-ratio-gap;concentrated-if-share>=0.25"
                .to_string(),
        row,
        width_signed_observed_to_corrected_ratio_gap,
        top_row_aligns_with_width_gap,
        concentration_share_of_absolute_gap,
        concentration_status: concentration_status.to_string(),
        localization_status: localization_status.to_string(),
    })
}

#[derive(Debug, Clone)]
struct PositionDigitMetric {
    connector: String,
    prime_hit: bool,
    corrected_expected_hit: f64,
    observed_to_corrected_ratio: f64,
}

fn position_digit_metrics(
    stats: &DirectionScanStats,
    width: u32,
    small_primes: &[u32],
) -> BTreeMap<(u32, u8), PositionDigitMetric> {
    stats
        .candidates
        .iter()
        .filter(|candidate| candidate.hit.width == width && candidate.residue_admissible.is_yes())
        .filter_map(|candidate| {
            let connector = candidate.hit.connector_string()?;
            let corrected_expected_hit =
                corrected_expected_hit_for_candidate(candidate, small_primes);
            let observed_to_corrected_ratio = if corrected_expected_hit > 0.0 {
                usize::from(candidate.is_prime) as f64 / corrected_expected_hit
            } else {
                0.0
            };
            Some((
                (candidate.hit.position, candidate.hit.digit),
                PositionDigitMetric {
                    connector,
                    prime_hit: candidate.is_prime,
                    corrected_expected_hit,
                    observed_to_corrected_ratio,
                },
            ))
        })
        .collect()
}

fn corrected_expected_hit_for_candidate(
    candidate: &ConnectorCandidate,
    small_primes: &[u32],
) -> f64 {
    let Some(value) = candidate.hit.concatenated_value() else {
        return 0.0;
    };
    corrected_expected_hit_for_value(value, small_primes)
}

fn corrected_expected_hit_for_value(value: u128, small_primes: &[u32]) -> f64 {
    let random_joint_survival_share = small_primes
        .iter()
        .fold(1.0, |acc, prime| acc * (1.0 - 1.0 / *prime as f64));
    let survives_small_prime_sieve = small_primes
        .iter()
        .all(|prime| value == *prime as u128 || value % *prime as u128 != 0);
    let value = value as f64;
    if random_joint_survival_share > 0.0 && survives_small_prime_sieve && value > 1.0 {
        (1.0 / value.ln()) / random_joint_survival_share
    } else {
        0.0
    }
}

fn position_digit_contrast_class(forward_prime_hit: bool, reverse_prime_hit: bool) -> &'static str {
    match (forward_prime_hit, reverse_prime_hit) {
        (true, true) => "both-prime-hit",
        (true, false) => "forward-only-prime-hit",
        (false, true) => "reverse-only-prime-hit",
        (false, false) => "neither-prime-hit",
    }
}

fn same_nonzero_sign(left: f64, right: f64) -> bool {
    left != 0.0 && right != 0.0 && left.signum() == right.signum()
}

fn connector_residue_survivor_theorem_link(
    pair: ConcatenationSystem,
    modulus: u32,
) -> (&'static str, &'static str) {
    if pair.left == CANONICAL_LEFT && pair.right == CANONICAL_RIGHT {
        match modulus {
            3 => (
                CONNECTOR_FAMILIES_MODULE,
                CANONICAL_MOD3_SURVIVOR_COUNT_THEOREM,
            ),
            9 => (
                CONNECTOR_FAMILIES_MODULE,
                CANONICAL_MOD9_SURVIVOR_COUNT_THEOREM,
            ),
            _ => (CONNECTOR_FAMILIES_MODULE, GENERIC_SURVIVOR_COUNT_THEOREM),
        }
    } else if pair.left == CANONICAL_LEFT && pair.right == ZERO_PADDED_RIGHT {
        match modulus {
            3 => (
                CONNECTOR_PROFILE_EXAMPLES_MODULE,
                ZERO_PADDED_MOD3_SURVIVOR_COUNT_THEOREM,
            ),
            9 => (
                CONNECTOR_PROFILE_EXAMPLES_MODULE,
                ZERO_PADDED_MOD9_SURVIVOR_COUNT_THEOREM,
            ),
            _ => (CONNECTOR_FAMILIES_MODULE, GENERIC_SURVIVOR_COUNT_THEOREM),
        }
    } else if pair.left == TWIN_SMALL_LEFT && pair.right == TWIN_SMALL_RIGHT {
        match modulus {
            3 => (
                CONNECTOR_PROFILE_EXAMPLES_MODULE,
                TWIN_SMALL_MOD3_SURVIVOR_COUNT_THEOREM,
            ),
            9 => (
                CONNECTOR_PROFILE_EXAMPLES_MODULE,
                TWIN_SMALL_MOD9_SURVIVOR_COUNT_THEOREM,
            ),
            _ => (CONNECTOR_FAMILIES_MODULE, GENERIC_SURVIVOR_COUNT_THEOREM),
        }
    } else if pair.left == SOPHIE_SMALL_LEFT && pair.right == SOPHIE_SMALL_RIGHT {
        match modulus {
            3 => (
                CONNECTOR_PROFILE_EXAMPLES_MODULE,
                SOPHIE_SMALL_MOD3_SURVIVOR_COUNT_THEOREM,
            ),
            9 => (
                CONNECTOR_PROFILE_EXAMPLES_MODULE,
                SOPHIE_SMALL_MOD9_SURVIVOR_COUNT_THEOREM,
            ),
            _ => (CONNECTOR_FAMILIES_MODULE, GENERIC_SURVIVOR_COUNT_THEOREM),
        }
    } else {
        (CONNECTOR_FAMILIES_MODULE, GENERIC_SURVIVOR_COUNT_THEOREM)
    }
}

pub fn summarize_residual_sweep(report: &NamedPairReport) -> ResidualSweepSummary {
    let negative_bounds = report
        .sweep
        .iter()
        .filter(|row| row.corrected_residual_ratio_delta < 0.0)
        .count();
    let positive_bounds = report
        .sweep
        .iter()
        .filter(|row| row.corrected_residual_ratio_delta > 0.0)
        .count();
    let zero_bounds = report.sweep.len() - negative_bounds - positive_bounds;
    let min_delta = report
        .sweep
        .iter()
        .map(|row| row.corrected_residual_ratio_delta)
        .fold(f64::INFINITY, f64::min);
    let max_delta = report
        .sweep
        .iter()
        .map(|row| row.corrected_residual_ratio_delta)
        .fold(f64::NEG_INFINITY, f64::max);

    ResidualSweepSummary {
        pair_label: report.name.clone(),
        negative_bounds,
        positive_bounds,
        zero_bounds,
        min_delta,
        max_delta,
        sign_stable: (negative_bounds == report.sweep.len()
            || positive_bounds == report.sweep.len())
            && zero_bounds == 0,
    }
}

