    #[test]
    fn connector_atlas_has_deterministic_core_shape() {
        let atlas = build_connector_signal_atlas();

        assert_eq!(atlas.schema_version, CONNECTOR_SIGNAL_ATLAS_SCHEMA_VERSION);
        assert_eq!(atlas.schema_version, "connector-signal-atlas-v2");
        assert_eq!(atlas.maintained_pairs.len(), 4);
        assert_eq!(atlas.canonical_source_cases.len(), 5);
        assert_eq!(atlas.residual_sweep_summary.len(), 4);
        assert_eq!(
            atlas.residual_boundary_rows.len(),
            atlas.maintained_pairs.len()
        );
        assert!(atlas.residual_target_pick.is_some());
        assert!(atlas.residual_target_follow_up.is_some());
        assert!(atlas
            .residual_target_follow_up
            .as_ref()
            .and_then(|follow_up| follow_up.width_contrast_micro_atlas.as_ref())
            .is_some());
        assert_eq!(
            atlas.residue_survivor_rows.len(),
            atlas.maintained_pairs.len() * atlas.settings.residue_moduli.len()
        );
        assert!(atlas
            .residue_survivor_rows
            .iter()
            .all(|row| row.survivor_delta == 0));
        assert!(atlas
            .residual_boundary_rows
            .iter()
            .all(|row| row.residue_survivors_equal));
        assert_eq!(
            atlas.claim_status.residue_survivor_null_status,
            "theorem-backed-equal-directional-survivor-counts"
        );
        assert_eq!(atlas.claim_status.density_mechanism_status, "not-claimed");
        assert!(atlas
            .proof_links
            .iter()
            .any(|link| link.lean_module == "PrimeArithmetic.Analysis.HardyLittlewoodShell"));
        assert!(atlas
            .proof_links
            .iter()
            .any(|link| link.label == "finite connector residue-survivor count null theorem"));
        assert!(atlas
            .proof_links
            .iter()
            .any(|link| link.label == "canonical connector residue-survivor count null theorem"));
    }

    #[test]
    fn connector_atlas_json_round_trips() {
        let atlas = build_connector_signal_atlas();
        let json = serde_json::to_string_pretty(&atlas).expect("serialize atlas");
        assert!(!json.contains("generated_at_utc"));
        let decoded: ConnectorSignalAtlas = serde_json::from_str(&json).expect("decode atlas");
        assert_eq!(decoded.schema_version, atlas.schema_version);
        assert_eq!(decoded.artifact_id, atlas.artifact_id);
        assert_eq!(decoded.settings, atlas.settings);
        assert_eq!(decoded.maintained_pairs.len(), atlas.maintained_pairs.len());
        assert_eq!(decoded.canonical_source_cases, atlas.canonical_source_cases);
        assert_eq!(decoded.residue_survivor_rows, atlas.residue_survivor_rows);
        assert_eq!(
            decoded.residual_boundary_rows.len(),
            atlas.residual_boundary_rows.len()
        );
        assert_eq!(
            decoded.residual_target_pick.as_ref().map(|target| (
                target.pair_label.as_str(),
                target.selection_rule.as_str(),
                target.target_status.as_str()
            )),
            atlas.residual_target_pick.as_ref().map(|target| (
                target.pair_label.as_str(),
                target.selection_rule.as_str(),
                target.target_status.as_str()
            ))
        );
        assert_eq!(
            decoded.residual_target_follow_up.as_ref().map(|target| (
                target.pair_label.as_str(),
                target.scan_scope.as_str(),
                target.follow_up_status.as_str(),
                target.residue_null_lean_theorem.as_str(),
                target.width_contrast_pick.as_ref().map(|pick| pick.width),
                target
                    .width_contrast_micro_atlas
                    .as_ref()
                    .map(|micro_atlas| (
                        micro_atlas.width,
                        micro_atlas.exact_layer_decision.as_str(),
                        micro_atlas.next_theorem_decision.as_str()
                    )),
                target.width_rows.len()
            )),
            atlas.residual_target_follow_up.as_ref().map(|target| (
                target.pair_label.as_str(),
                target.scan_scope.as_str(),
                target.follow_up_status.as_str(),
                target.residue_null_lean_theorem.as_str(),
                target.width_contrast_pick.as_ref().map(|pick| pick.width),
                target
                    .width_contrast_micro_atlas
                    .as_ref()
                    .map(|micro_atlas| (
                        micro_atlas.width,
                        micro_atlas.exact_layer_decision.as_str(),
                        micro_atlas.next_theorem_decision.as_str()
                    )),
                target.width_rows.len()
            ))
        );
        assert_eq!(
            decoded
                .residual_boundary_rows
                .iter()
                .map(|row| (
                    row.pair_label.as_str(),
                    row.residue_survivors_equal,
                    row.empirical_raw_hit_delta,
                    row.boundary_interpretation.as_str()
                ))
                .collect::<Vec<_>>(),
            atlas
                .residual_boundary_rows
                .iter()
                .map(|row| (
                    row.pair_label.as_str(),
                    row.residue_survivors_equal,
                    row.empirical_raw_hit_delta,
                    row.boundary_interpretation.as_str()
                ))
                .collect::<Vec<_>>()
        );
        assert_eq!(decoded.proof_links, atlas.proof_links);
        assert_eq!(decoded.claim_status, atlas.claim_status);
    }

    #[test]
    fn residual_boundary_rows_pair_residue_null_with_empirical_deltas() {
        let analysis = build_connector_signal_analysis(DEFAULT_SMALL_PRIME_BOUND);
        let residue_survivor_rows = build_residue_survivor_rows(&analysis.reports);
        let rows = build_residual_boundary_rows(&analysis.reports, &residue_survivor_rows);

        assert_eq!(rows.len(), analysis.reports.len());
        for row in &rows {
            let report = analysis
                .reports
                .iter()
                .find(|report| report.name == row.pair_label)
                .expect("boundary row report exists");
            let asymmetry = report.summary.directional_asymmetry();

            assert_eq!(row.residue_survivor_deltas.len(), RESIDUE_MODULI.len());
            assert!(row.residue_survivors_equal);
            assert!(row
                .residue_survivor_deltas
                .iter()
                .all(|delta| delta.survivor_delta == 0));
            assert_eq!(row.empirical_raw_hit_delta, asymmetry.hit_delta());
            assert_eq!(
                row.empirical_corrected_expected_hit_delta,
                report.audit.corrected_expected_hit_delta()
            );
            assert_eq!(
                row.empirical_corrected_residual_ratio_delta,
                report.audit.corrected_residual_ratio_delta()
            );
            assert_eq!(
                row.boundary_interpretation,
                "exact-local-filter-direction-neutral-residual-gap-outside-theorem-layer"
            );
        }
    }

