    #[test]
    fn residual_target_follow_up_summarizes_selected_pair_by_width() {
        let atlas = build_connector_signal_atlas();
        let follow_up = atlas
            .residual_target_follow_up
            .as_ref()
            .expect("residual target follow-up selected");

        assert_eq!(follow_up.pair_label, "Twin-prime profile (11 \u{2218} 13)");
        assert_eq!(follow_up.left, TWIN_SMALL_LEFT);
        assert_eq!(follow_up.right, TWIN_SMALL_RIGHT);
        assert!(follow_up.residue_survivors_equal);
        assert_eq!(follow_up.width_rows.len(), WIDTHS.len() * 2);
        assert_eq!(
            follow_up.follow_up_status,
            "bounded-scan-follow-up-not-mechanism-claim"
        );
        assert_eq!(
            follow_up.residue_null_lean_module,
            CONNECTOR_PROFILE_EXAMPLES_MODULE
        );
        assert_eq!(
            follow_up.residue_null_lean_theorem,
            TWIN_SMALL_MOD3_MOD9_SURVIVOR_COUNT_THEOREM
        );
        let contrast = follow_up
            .width_contrast_pick
            .as_ref()
            .expect("width contrast selected");
        assert_eq!(contrast.width, 6);
        assert_eq!(
            contrast.selection_rule,
            "largest-absolute-forward-reverse-observed-to-corrected-ratio-gap"
        );
        assert_eq!(
            contrast.contrast_status,
            "empirical-width-contrast-not-mechanism-claim"
        );
        assert_eq!(contrast.forward_prime_hits, 8);
        assert_eq!(contrast.reverse_prime_hits, 2);
        assert!(contrast.signed_ratio_gap > 0.0);
        let micro_atlas = follow_up
            .width_contrast_micro_atlas
            .as_ref()
            .expect("width contrast micro-atlas selected");
        assert_eq!(micro_atlas.width, 6);
        assert_eq!(micro_atlas.pair_label, follow_up.pair_label);
        assert_eq!(micro_atlas.left, TWIN_SMALL_LEFT);
        assert_eq!(micro_atlas.right, TWIN_SMALL_RIGHT);
        assert!(micro_atlas.residue_survivors_equal);
        assert!(micro_atlas
            .residue_survivor_deltas
            .iter()
            .all(|delta| delta.survivor_delta == 0));
        assert_eq!(
            micro_atlas.exact_layer_decision,
            "exact-residue-null-layer-cannot-distinguish-this-width-contrast"
        );
        assert_eq!(
            micro_atlas.empirical_status,
            "bounded-width-empirical-residual-contrast-not-mechanism-claim"
        );
        assert_eq!(
            micro_atlas.next_theorem_decision,
            "replicate-before-adding-new-connector-theorem"
        );
        assert_eq!(
            micro_atlas.next_experiment_target,
            "replicate-width-6-position-0-digit-5-twin-prime-profile-under-matched-connector-controls"
        );
        assert_eq!(micro_atlas.forward_prime_hits, contrast.forward_prime_hits);
        assert_eq!(micro_atlas.reverse_prime_hits, contrast.reverse_prime_hits);
        assert_eq!(micro_atlas.raw_hit_delta, 6);
        assert_eq!(
            micro_atlas.signed_observed_to_corrected_ratio_gap,
            contrast.signed_ratio_gap
        );
        assert_eq!(micro_atlas.position_digit_contrast_rows.len(), 36);
        let position_digit_pick = micro_atlas
            .position_digit_contrast_pick
            .as_ref()
            .expect("position/digit contrast selected");
        assert_eq!(position_digit_pick.row.width, 6);
        assert_eq!(position_digit_pick.row.position, 0);
        assert_eq!(position_digit_pick.row.digit, 5);
        assert_eq!(position_digit_pick.row.connector, "500000");
        assert_eq!(
            position_digit_pick.row.contrast_class,
            "reverse-only-prime-hit"
        );
        assert!(!position_digit_pick.row.forward_prime_hit);
        assert!(position_digit_pick.row.reverse_prime_hit);
        assert!(
            position_digit_pick
                .row
                .signed_observed_to_corrected_ratio_gap
                < 0.0
        );
        assert!(position_digit_pick.width_signed_observed_to_corrected_ratio_gap > 0.0);
        assert!(!position_digit_pick.top_row_aligns_with_width_gap);
        assert_eq!(
            position_digit_pick.concentration_status,
            "diffuse-position-digit-contrast-replication-target"
        );
        assert_eq!(
            position_digit_pick.localization_status,
            "diffuse-mixed-sign-position-digit-contrast"
        );
        assert!(position_digit_pick.concentration_share_of_absolute_gap < 0.25);
        assert!(follow_up
            .width_rows
            .iter()
            .all(|row| WIDTHS.contains(&row.width)));
        let total_hits: usize = follow_up.width_rows.iter().map(|row| row.prime_hits).sum();
        let target_report = build_connector_signal_analysis(DEFAULT_SMALL_PRIME_BOUND)
            .reports
            .into_iter()
            .find(|report| report.summary.pair.left == TWIN_SMALL_LEFT)
            .expect("twin target report");
        assert_eq!(
            total_hits,
            target_report.audit.forward.prime_hits + target_report.audit.reverse.prime_hits
        );
    }

    #[test]
    fn residue_survivor_rows_match_direct_profile_classification() {
        let analysis = build_connector_signal_analysis(DEFAULT_SMALL_PRIME_BOUND);
        let rows = build_residue_survivor_rows(&analysis.reports);

        for row in &rows {
            let report = analysis
                .reports
                .iter()
                .find(|report| report.name == row.pair_label)
                .expect("row report exists");
            let profile = report
                .summary
                .residue_profiles
                .iter()
                .find(|profile| profile.modulus == row.modulus)
                .expect("row profile exists");
            let direct_forward = report
                .summary
                .forward
                .candidates
                .iter()
                .filter(|candidate| profile.classify(&candidate.hit).is_yes())
                .count();
            let direct_reverse = report
                .summary
                .reverse
                .candidates
                .iter()
                .filter(|candidate| profile.classify(&candidate.hit).is_yes())
                .count();

            assert_eq!(
                row.forward_raw_candidates,
                report.summary.forward.raw_candidates()
            );
            assert_eq!(
                row.reverse_raw_candidates,
                report.summary.reverse.raw_candidates()
            );
            assert_eq!(row.forward_survivors, direct_forward);
            assert_eq!(row.reverse_survivors, direct_reverse);
            assert_eq!(row.survivor_delta, 0);
            let (expected_module, expected_theorem) =
                connector_residue_survivor_theorem_link(report.summary.pair, row.modulus);
            assert_eq!(row.lean_module.as_deref(), Some(expected_module));
            assert_eq!(row.lean_theorem.as_deref(), Some(expected_theorem));
        }
    }

    #[test]
    fn residue_survivor_rows_use_concrete_maintained_theorem_links() {
        let atlas = build_connector_signal_atlas();
        let expected = [
            (
                CANONICAL_LEFT,
                CANONICAL_RIGHT,
                3,
                CANONICAL_MOD3_SURVIVOR_COUNT_THEOREM,
            ),
            (
                CANONICAL_LEFT,
                CANONICAL_RIGHT,
                9,
                CANONICAL_MOD9_SURVIVOR_COUNT_THEOREM,
            ),
            (
                CANONICAL_LEFT,
                ZERO_PADDED_RIGHT,
                3,
                ZERO_PADDED_MOD3_SURVIVOR_COUNT_THEOREM,
            ),
            (
                CANONICAL_LEFT,
                ZERO_PADDED_RIGHT,
                9,
                ZERO_PADDED_MOD9_SURVIVOR_COUNT_THEOREM,
            ),
            (
                TWIN_SMALL_LEFT,
                TWIN_SMALL_RIGHT,
                3,
                TWIN_SMALL_MOD3_SURVIVOR_COUNT_THEOREM,
            ),
            (
                TWIN_SMALL_LEFT,
                TWIN_SMALL_RIGHT,
                9,
                TWIN_SMALL_MOD9_SURVIVOR_COUNT_THEOREM,
            ),
            (
                SOPHIE_SMALL_LEFT,
                SOPHIE_SMALL_RIGHT,
                3,
                SOPHIE_SMALL_MOD3_SURVIVOR_COUNT_THEOREM,
            ),
            (
                SOPHIE_SMALL_LEFT,
                SOPHIE_SMALL_RIGHT,
                9,
                SOPHIE_SMALL_MOD9_SURVIVOR_COUNT_THEOREM,
            ),
        ];

        for (left, right, modulus, theorem) in expected {
            let row = atlas
                .residue_survivor_rows
                .iter()
                .find(|row| row.left == left && row.right == right && row.modulus == modulus)
                .expect("maintained survivor row exists");
            let (expected_module, expected_theorem) = connector_residue_survivor_theorem_link(
                ConcatenationSystem::new(left, right),
                modulus,
            );
            assert_eq!(expected_theorem, theorem);
            assert_eq!(row.lean_module.as_deref(), Some(expected_module));
            assert_eq!(row.lean_theorem.as_deref(), Some(theorem));
        }
        assert!(atlas
            .residue_survivor_rows
            .iter()
            .all(|row| row.lean_theorem.as_deref() != Some(GENERIC_SURVIVOR_COUNT_THEOREM)));
    }

