        assert!(checks.contains(&format!("import {}", CONNECTOR_PROFILE_EXAMPLES_MODULE)));
        assert!(checks.contains(DIGIT8_LEADING_WIDTH6_MOD17_CLASSIFIER_THEOREM));
        assert!(checks.contains(DIGIT8_LEADING_WIDTH6_MOD23_CLASSIFIER_THEOREM));
