        assert!(checks.contains(DIGIT8_LEADING_WIDTH6_MOD31_CLASSIFIER_THEOREM));
        assert!(checks.contains(DIGIT8_TRAILING_WIDTH5_MOD19_CLASSIFIER_THEOREM));
