        assert!(checks.contains(DIGIT8_TRAILING_WIDTH5_MOD31_CLASSIFIER_THEOREM));
        assert!(checks.contains(DIGIT8_TRAILING_WIDTH6_MOD17_CLASSIFIER_THEOREM));
        assert!(checks.contains(DIGIT8_TRAILING_WIDTH6_MOD19_CLASSIFIER_THEOREM));
        assert!(checks.contains(DIGIT8_TRAILING_WIDTH6_MOD29_CLASSIFIER_THEOREM));
        assert!(checks.contains(DIGIT8_TRAILING_WIDTH6_MOD31_CLASSIFIER_THEOREM));
        assert!(checks.contains(DIGIT8_LEADING_WIDTH6_MULTI_MODULUS_CLASSIFIER_THEOREM));
        assert!(checks.contains(DIGIT8_TRAILING_WIDTH5_MULTI_MODULUS_CLASSIFIER_THEOREM));
