    #[test]
    fn connector_width6_stress_lean_checks_reject_bad_theorem_name() {
        let mut report = build_connector_width6_stress_report();
        let profile = report
            .ladder_peak_matched_control_screen
            .as_mut()
            .and_then(|screen| screen.digit8_edge_zoom_probe.as_mut())
            .and_then(|probe| probe.residue_profile.as_mut())
            .expect("digit-8 residue profile exists");
        let backed = profile
            .cell_profiles
            .iter_mut()
            .flat_map(|cell| cell.separator_rows.iter_mut())
            .find(|row| row.lean_theorem.is_some())
            .expect("stress profile has a theorem-backed row");
        backed.lean_theorem = Some("bad-theorem-name".to_string());

        let error = render_connector_width6_stress_lean_checks(&report)
            .expect_err("bad theorem name should fail before Lean");
        assert!(error.contains("invalid Lean theorem name"));
    }

    #[test]
    fn connector_width6_stress_lean_checks_reject_bad_summary_theorem_name() {
        let mut report = build_connector_width6_stress_report();
        let profile = report
            .ladder_peak_matched_control_screen
            .as_mut()
            .and_then(|screen| screen.digit8_edge_zoom_probe.as_mut())
            .and_then(|probe| probe.residue_profile.as_mut())
            .expect("digit-8 residue profile exists");
        let summary = profile
            .multi_modulus_summaries
            .iter_mut()
            .find(|summary| summary.lean_summary_theorem.is_some())
            .expect("stress profile has a theorem-backed summary");
        summary.lean_summary_theorem = Some("bad-summary-theorem-name".to_string());

        let error = render_connector_width6_stress_lean_checks(&report)
            .expect_err("bad summary theorem name should fail before Lean");
        assert!(error.contains("invalid Lean theorem name"));
    }

    #[test]
    fn timestamped_signal_report_keeps_legacy_export_shape() {
        let analysis = build_connector_signal_analysis(DEFAULT_SMALL_PRIME_BOUND);
        let bundle = build_signal_report_bundle(&analysis);

        assert_eq!(bundle.export_version, CONNECTOR_SIGNAL_EXPORT_VERSION);
        assert_eq!(bundle.pairs.len(), analysis.reports.len());
        assert!(bundle.generated_at_utc.ends_with('Z'));
    }
